-- ============================================================
-- Ozbek2c (3/6) — DB kontentinin UZ tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning uyqu tartibi siz uchun ustuvor bo‘lishi kerak. Uning faol mashg‘ulotlari juda kech soatlargacha davom etmasligi va xonasida televizor, noutbuk kabi texnologik qurilmalar bo‘lmasligi uyqu sifatiga ijobiy ta’sir qiladi. Yetarli uxlamaslik ishtahani oshirib, bolani yuqori kaloriyali mahsulotlarga moyil qilishi va semirishga olib kelishi mumkin. Shuningdek, bu holat hissiy ahvolni yomonlashtirib, xavotir yoki depressiyaga sabab bo‘lishi mumkin. Xotira va diqqat buzilishi tufayli maktabdagi o‘zlashtirish darajasi pasayishi, sport jarohatlari bilan bog‘liq hodisalar hamda boshqa baxtsiz hodisalarga moyillik ortishi mumkin. Uyqusizlik bolaning qaror qabul qilish qobiliyatini ham susaytiradi va noto‘g‘ri qadamlar tashlashiga sabab bo‘ladi.') WHERE id = '57b0220c-72e8-44f7-8b63-aa64a167b83f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda til ko‘nikmalarini ancha rivojlantirgan bo‘ladi. Endi so‘ralganda ismi va familiyasini ayta oladi. Gapirish va hazillashishdan zavq oladi. She’r, qo‘shiq va tez aytishlarni yoddan ayta oladi. Qanday? so‘roq olmoshidan foydalanib savollar beradi va o‘ziga berilgan savollarga javob qaytaradi. Ikki gapni bog‘lovchilar yordamida bir-biriga bog‘lay oladi. Tinglayotganda yoki gapirayotganda ko‘z bilan aloqa o‘rnatadi va suhbatda faol ishtirok etadi.') WHERE id = '8b9223c1-8cb2-41b5-98b2-84189ec82cbb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz 3,5 yoshga to‘lgan bo‘lsa ham, hali ham chaqaloqlardek gapirayotganini kuzatishingiz mumkin. Bu holat tengdoshlari tomonidan salbiy qabul qilinishiga, ijtimoiy hayotda qiyinchiliklarga duch kelishiga va o‘ziga bo‘lgan ishonchi pasayishiga sabab bo‘lishi mumkin. Bunday vaziyatda ota-onalarning to‘g‘ri yondashuvi bilan tezroq natijaga erishish mumkin. Avvalo, bola bilan uning uslubida, chaqaloq tilida gaplashib, noto‘g‘ri talaffuzini mustahkamlab qo‘ymasligingiz kerak. Shu bilan birga, uning gapirish uslubini aslo masxara qilmang. To‘g‘ri ayta olmaydigan so‘zlarini tanqid qilayotgandek tuzatishdan saqlaning. U so‘zni noto‘g‘ri talaffuz qilgan zahoti sizdan o‘sha so‘zning to‘g‘ri variantini tabiiy tarzda eshitishi kerak. Masalan, bola Eshikni yoptim deganda, siz Barakalla, bolam eshikni yopdi deb, to‘g‘ri namuna ko‘rsatishingiz kerak.') WHERE id = 'c4b115b3-ef2f-472a-953f-e45e211c4cd3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Qanday farzandlarni tarbiyalamoqchi bo‘lsak, o‘zimiz ham shunday yo‘l tutishimiz kerak. Agar saxiy bola voyaga yetkazmoqchi bo‘lsak, o‘zimiz ham saxovatli bo‘lishimiz kerak. Mehribon farzand xohlasak, o‘zimiz ham yordamga tayyor bo‘lishimiz lozim. Yordam berish nimaligini ko‘rmagan insondan boshqalarga ko‘maklashishini kutolmaymiz. Tabiatni sevadigan bola tarbiyalash uchun hayvonlarni sevishimiz, atrof-muhitni toza saqlashimiz kerak. Atrofga chiqindi tashlab, bolamizdan tabiatni sevishini kutish samimiy bo‘lmaydi. Aytgan gaplarimiz bilan qilgan ishlarimiz doimo bir-birini to‘ldirishi kerak.') WHERE id = '5f784ef7-81b7-45ed-8f69-52151968d6e6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizda kitobga mehr uyg‘otishning ko‘plab usullari bor. Kitob hayotning bir qismi ekanini his qilishi uchun unga chaqaloqligidanoq kitoblar olib berishingiz kerak edi. Muntazam kitob o‘qiydigan ota-ona sifatida unga namuna bo‘ling. Vaqti-vaqti bilan birga kitob xarid qilishga boring. Unga yoshiga mos, qiziqishini uyg‘otadigan, turli mavzulardagi, ham o‘rgatuvchi, ham qiziqarli kitoblar olib bering. Hatto biror pul qutisini Kitob jamg‘armasi deb nomlang va unda yig‘ilgan pulga u istagan kitoblarni birga sotib oling. Har kuni birgalikda kitob o‘qish uchun vaqt ajrating. Unga kitob o‘qib berayotganda ovoz ohangingiz va mimikalaringiz bilan hayajon qo‘shib, hikoyani jonlantiring. Kitoblarini xonasidagi osongina qo‘li yetadigan va ko‘zga ko‘rinadigan joyga qo‘yishingiz unga istagan vaqtingda kitob o‘qishing mumkin degan mazmundagi xabarni beradi.') WHERE id = 'f1964371-90a4-463e-96ce-62c966f65628';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yoshda qo‘rquvlar tez-tez kuzatilishining sababi — bolalarning bilim va tajribasi cheklanganligi, fikrlash qobiliyati esa hali to‘liq rivojlanmaganidir. Shu bois ular ko‘rgan narsalarining ma’nosini tushunishda qiynaladi. Odatda bola ulg‘aygani sari bu qo‘rquvlar kamayadi, ammo ruhiy jarohat yetkazuvchi voqealar va ota-onaning noto‘g‘ri munosabati ularni surunkali holga keltirishi mumkin. Bundan tashqari, kattalar sifatida o‘zimiz nazorat qilmay namoyon etadigan qo‘rquvlarimiz ham bolamizga o‘tishi mumkin. Qo‘rquvlar rivojlanish jarayonining muhim qismi bo‘lsa-da, ko‘plab ota-onalar bundan xavotirga tushadi. Buning asosiy sababi qo‘rquvni qanday yengish haqida yetarli ma’lumotga ega emaslikdir. Siz xotirjamlikni saqlab, chaqalog‘ingizning qo‘rquviga tushunish bilan munosabatda bo‘lishingiz va uni bartaraf etish yo‘llarini o‘rganishingiz kerak.') WHERE id = 'd2b56eb9-64b3-4d2a-9bea-2c89289a5a9f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Intizom bolaning yangi xulq-atvor ko‘nikmalarini egallashiga yordam beradi. Intizom tufayli farzandingiz jamiyatda o‘zini tutishni, qoidalarga rioya qilishni, o‘zini boshqarishni va o‘ziga ishonishni o‘rganadi. Bolani intizomga o‘rgatish aslo baqirish, koyish yoki urish degani emas. “Bitta yengil tarsakdan hech narsa bo‘lmaydi” degan fikr ijobiy intizom tushunchasiga kirmaydi. Sizdan ko‘ra himoyasizroq kishini urishingiz aslida o‘zingizni nazorat qila olmay qolganingizni ko‘rsatadi. Ammo bundan ham jiddiyroq jihati shundaki, farzandingiz sizdan o‘rnak oladi. Agar bolangiz o‘zidan kichik ukasi yoki singlisiga bir-ikki tarsaki tushirganini ko‘rsangiz, unga aytadigan gapingiz qolmaydi. Shu sababli intizomni ta’minlashda zo‘ravonlikka aslo o‘rin bermaslikka e’tibor qilishingiz kerak.') WHERE id = '1771eb2a-f537-43ee-b06f-ae57310d6566';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ko‘plab ota-onalar va o‘qituvchilar bolaning tartibsizligidan shikoyat qiladi. Bu tartibsizlikning ortida turli sabablar bo‘lishi mumkin. Onaga tartib-intizom kerak bo‘lsa, bolaga shunchaki "ona" kerak. Balki farzandingiz tartibsizlik orqali e’tiboringizni o‘ziga qaratib turmoqchidir. Bolaning tartibsizligi ham uning ozodaligi kabi muayyan ma’noga ega. Agar bolangiz tartibsiz bo‘lsa, buning sababini anglash uchun uning ehtiyojlarini to‘g‘ri tahlil qilish va orangizdagi rishtalar qanchalik ishonchli ekanini ko‘rib chiqish lozim. Uning asl ehtiyojini (tinglanish, o‘yin, jismoniy yaqinlik...) his qilib, qondirishga intilishingiz bolaning ham xonasini, ham ichki dunyosini tartibga solishiga yordam beradi. Shu tariqa uning ota-onasi bilan munosabatlari ham tabiiy ravishda yaxshilanadi.') WHERE id = '0c1e3fdc-522c-4ec0-b788-6079b836c01d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz sizni diqqat bilan tinglamaydi deb o‘ylasangiz, uning diqqatini jamlash qobiliyatini rivojlantirish o‘z qo‘lingizda. Yaxshi tinglovchi qanday bo‘lishini bolangizga o‘rnak bo‘lib ko‘rsating. U bilan gaplashayotganda o‘zingizni tinglayotgandek ko‘rsatmang, ko‘zlariga qarab, chindan ham tinglang. U biror narsa aytayotganida gapini bo‘lmang, jumlalarini o‘zi tugatsin. U sizning gapingizni bo‘lishga uringanida esa kutishi kerakligini tushuntiring. Uni qiziqtiradigan mavzularda tez-tez suhbatlashing. Bu ham munosabatlaringizga, ham bolaning o‘z fikrini ifodalash va tinglash qobiliyatiga ijobiy ta’sir qiladi. O‘yinchoqlarini oldiga terib qo‘ying, ulardan birini tasvirlab bering, u esa ko‘rsatmalaringiz asosida o‘sha o‘yinchoqni topsin. Ko‘rsatmalar berib rasm chizdiring: “Qog‘ozning o‘rtasiga katta doira chiz. Endi uning o‘ng tomoniga doiraning yarmidek kattalikdagi uchburchak chiz.” Birgalikda ovqat tayyorlang: masalliqlarni siz ayting, u esa ularni navbati bilan aralashtirsin.') WHERE id = 'd5751336-7039-4c31-8668-3f750e2f3116';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ota-onalar vaqti-vaqti bilan farzandlariga turlicha munosabatda bo‘lishlari mumkin. Charchatadigan kun oxirida farzandingizga yetarlicha vaqt ajrata olmasligingiz yoki uning biror gapiga haddan tashqari keskin munosabat bildirishingiz mumkin. Eng muhimi, bunday salbiy xatti-harakatlar doimiy tus olmasligidir. Har ikki ota-onaning bir xil tarbiya usulini qo‘llashi bolaning sog‘lom shaxs bo‘lib shakllanishida juda muhim omildir. Ona va otaning har bir masalada turlicha munosabat bildirishi bolada sarosima va ishonchsizlik hissini uyg‘otadi. Qilgan xatti-harakatiga ota-onasi qanday munosabat bildirishini bilmagan bolaning xavotiri kuchayadi. Bu holat uzoq davom etsa, bolada hissiy va xulq-atvor buzilishlariga sabab bo‘lishi mumkin.') WHERE id = 'a5bd86bc-c069-466f-af85-e16d00cba4e2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar kun davomida “Yana qancha qoldi?” yoki “Yetib keldikmi?” kabi savollarni tez-tez eshitsangiz, bilingki, bu odatiy hol. Bolalarning kognitiv rivojlanishi hali yakunlanmagani uchun ular vaqt tushunchasini bizdan boshqacha idrok etadi. Aynan shuning uchun ular bir xil savolni qayta-qayta so‘raydi. “30 daqiqa qoldi” yoki “Ikki soatlik yo‘limiz bor” kabi iboralar bola uchun hech qanday ma’no anglatmaydi. Iloji boricha tushunarli va aniq misollar bilan izohlash kerak. “Yo‘limiz yana to‘rtta multfilm davomiyligicha qoldi” yoki “Kechki ovqatni yeb bo‘lgunimizcha o‘tadigan vaqtcha kutamiz” kabi tushuntirishlar bolani tezroq tinchlantiradi va unga vaziyatni aniqroq anglashga yordam beradi.') WHERE id = '62a96225-850d-4700-bdbf-477dae8e326b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda o‘z iste’dodlarini rivojlantiradi, asosiy ko‘nikmalarni egallaydi, turli tajribalar orttirib ijtimoiylashadi va aqliy qobiliyatlarini oshiradi. Bu bosqichda unga turli tashqi taassurotlarga boy muhit yaratish, rivojlanishini qo‘llab-quvvatlaydigan tajribalar bilan tanishtirish va ota-ona sifatida to‘g‘ri ko‘mak berish uni hayotga eng yaxshi tarzda tayyorlaydi. Farzandingizning har tomonlama rivojlanishini qo‘llab-quvvatlash uchun quyidagilarni qilishingiz mumkin: nutqi rivojlanishi uchun u bilan ko‘p suhbatlashing, kitob o‘qing, o‘qiganlaringiz haqida gaplashing va savollariga sabr bilan javob bering. Jismoniy rivojlanishi uchun har kuni ochiq havoda yugurib o‘ynashi, tirmashishi va sakrashi uchun imkoniyat yarating. Ijtimoiylashishni o‘rganishi uchun tengdoshlari bilan vaqt o‘tkazishiga sharoit yarating. Bularning barchasini amalga oshirishda eng muhim omil farzandingizga ko‘rsatadigan samimiy va mehribon munosabatingiz ekanini unutmang. :)') WHERE id = '4c3211b1-1b69-4c52-9840-6ed951a97c72';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizga to‘g‘ri va noto‘g‘ri xatti-harakatlar borasida yo‘l-yo‘riq ko‘rsatishingiz kerak. Bolalar dunyoni ota-onasining nigohi orqali taniydilar. Uni noto‘g‘ri xatti-harakatlarining tabiiy oqibatlariga duch keltirishingiz muhim. Masalan, do‘stining o‘yinchog‘iga yetkazgan zararini o‘z cho‘ntak pulidan to‘lagan bola har bir xatti-harakatning oqibati borligini va buning uchun mas’uliyatni zimmasiga olishi kerakligini anglaydi. Uning ijobiy harakatlarini albatta e’tirof eting va rag‘batlantiring. Yangi ko‘nikmani shakllantirishda hatto kichik yutuqni ham payqash va maqtash rivojlanish uchun juda muhim. Ma’rifiy kitoblar va filmlardan foydalaning; mehr-muhabbat, do‘stlik va o‘zaro yordam haqidagi qahramonlar bolalar uchun muhim namuna bo‘lib xizmat qiladi.') WHERE id = '49814a58-2096-4190-95ca-b5eac5936f10';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz o‘ynayotgan paytda yiqilishi yoki biror joyga urilishi muqarrar. Ko‘pincha bular yengil jarohatlar bo‘lib, tibbiy aralashuvni talab qilmaydi. Biroq teri salomatligi uchun bunday kichik jarohatlarni parvarish qilish lozim. Shish va ko‘karishlarning oldini olish uchun avvalo farzandingizni tinch joyga olib boring. Qon oqimini cheklash va shishni kamaytirish uchun jarohatlangan joyga darhol sochiqqa o‘ralgan muz qo‘ying. O‘sha joyni yengil bosib, tinchlantiruvchi va tiklovchi krem bilan uqalashingiz mumkin. Va, albatta, kichkintoyingizni quchoqlab, og‘riyotgan joyidan o‘pishni unutmang! 🥰') WHERE id = 'c11ef2e0-c21f-40eb-8a0a-01c49251e495';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar terisi o‘ziga xos sezgirlik xususiyatlariga ega. Shu sababli uning sog‘lom qolishi va atrof-muhitga moslashishi uchun alohida e’tibor va parvarish talab etiladi. Umuman olganda, kattalar uchun mo‘ljallangan tozalash va parvarish vositalarini chaqaloqlar hamda bolalar terisiga ishlatmaslik kerak. Shamol, sovuq havo, qattiq suv yoki yuqori harorat kabi tashqi omillar ta’sirida zaiflashgan bolalar terisi qurishga va ta’sirlarga nisbatan sezgirroq bo‘lishga moyil. Farzandingizni yuvayotganda teri quruqligini kuchaytirmaydigan, mikroorganizmlar ko‘payishining oldini oladigan, qichishishni tinchlantiradigan va terini namlantiradigan yengil, hidsiz tozalash vositalaridan foydalanishingiz mumkin. Chaqaloq terisini, ayniqsa teri burmalarini juda ehtiyotkorlik va muloyimlik bilan quriting. Farzandingizga paxtali kiyimlar kiydirganingiz ma’qul, chunki boshqa matolar, ayniqsa jun va sintetik materiallar terini ta’sirlantirishi mumkin. Xona harorati juda yuqori bo‘lmasligiga e’tibor bering, aks holda havo qurib, uning terisiga zarar yetkazadi.') WHERE id = '10ca6da4-e8de-47e5-922b-c5d97b0658c7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ba’zi ota-onalar bolaga chegara belgilash uni sustlashtiradi va o‘ziga bo‘lgan ishonchiga putur yetkazadi, deb o‘ylaydilar. Aslida esa chegaralar bolaga o‘zini xavfsiz his qilishiga yordam beradigan va qayerda to‘xtash kerakligini ko‘rsatadigan muhim belgilar hisoblanadi. Piyoda yo‘lning narigi tomoniga o‘tayotganda svetofor borligi bizga xotirjamlik bergani kabi, bolalarga ham qayerda to‘xtash kerakligini eslatib turuvchi belgilar o‘zlarini xavfsiz his qilishlariga yordam beradi. Chegara belgilash farzandingizning har bir istagiga "yo‘q" deyish yoki uni bosim ostida ushlab turish degani emas. Bu katta inson sifatida uning nomaqbul xatti-harakatlariga "TO‘XTA" deya olish va ayni xatti-harakat har safar takrorlanganida izchil ravishda bir xil munosabat bildirishdir. Chegaralar asosida tarbiyalangan bolalar o‘z chegaralari qayerda tugashini biladilar va shu tariqa boshqalarning erkinlik hududiga aralashmaydilar. Shuni unutmaylikki, farzandlarimizni baxtli qilish maqsadida ularning barcha istaklarini bajarib, taqdim etadigan "qulay hayotimiz" uzoq muddatda ularni hech narsadan qoniqmaydigan va baxtsiz insonlarga aylantirishi mumkin.') WHERE id = 'ad4cfebf-ee99-4e96-8f98-238ee9140d88';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ovqatlanish rejasi tuzilayotganda bu davrda farzandingizning shaxsiy tanlovlari albatta hisobga olinishi kerak. 3,5 yoshli bolaning taomnomasi u yoqtiradigan foydali mahsulotlardan iborat bo‘lishi lozim. Taomnomani 3 ta asosiy ovqatlanish va 3 ta tamaddiga bo‘lish tavsiya etiladi. Asosiy ovqatlarda tuxum, go‘sht, baliq, tovuq go‘shti, sut va qatiq kabi oqsilga boy mahsulotlar bo‘lishi kerak. Shu bilan birga, kartoshka, makaron va guruch kabi uglevodlarga boy taomlar ham muvozanatli ovqatlanishni ta’minlaydi. Agar farzandingiz ovqatlanishda qiynalsa, unga muqobil taomlarni taklif qilishingiz mumkin. Sabzavotlardan tayyorlangan mazali kotletlar, kartoshka bilan tortiladigan suyaksiz baliq bo‘laklari yoki pomidorli sous bilan bezatilgan makaron taomnomani yanada qiziqarli qiladi.') WHERE id = '9bae275a-b824-4916-834a-a3a6367872a8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni kasalliklardan himoya qilish, immunitetini mustahkamlash yoki unga quvvat berish uchun ziravorlardan foydalanishingiz mumkin. Ziravorlar kuchli antioksidant xususiyatga ega bo‘lish bilan birga, yallig‘lanishga qarshi ham ko‘plab foydali ta’sir ko‘rsatadi. Ularning tarkibidagi beta-karotin, selen, A, C va E vitaminlari kabi antioksidantlar bolangizni yurak kasalliklaridan tortib, ko‘plab og‘ir kasalliklargacha himoya qiladi. Shuningdek, yallig‘lanishga qarshi xususiyatlari tufayli immunitetni mustahkamlaydi va kasalliklarga chidamlilikni oshiradi. Tadqiqotlar kurkuma miya salomatligi va kognitiv rivojlanish uchun juda foydali ekanini ko‘rsatadi. Bir choy qoshiq zanjabil tarkibida bir stakan ismaloqdagiga teng miqdorda antioksidant borligi aniqlangan. Shu sababli, miqdorini to‘g‘ri belgilab va shifokoringiz bilan maslahatlashib, farzandingiz ovqatlanishida foydali ziravorlardan bemalol foydalanishingiz mumkin.') WHERE id = '85dd773a-500a-4181-ba61-330cd6ca6903';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan maroqli vaqt o‘tkazishingiz uchun bir mashg‘ulot taklifimiz bor! Birgalikda turli joylardan barg izlashga chiqishingiz, to‘plagan barglaringizni lupa yordamida o‘rganib, bir-biri bilan taqqoslashingiz mumkin. Nimalarni to‘plash mumkin: qarag‘ay g‘uddalari, turli rang va o‘lchamdagi barglar, novda bo‘laklari, gullar va urug‘lar. Tasavvuringizni ishga solib, to‘plagan narsalaringizni oq qog‘ozga yopishtirishingiz mumkin. Turli shakllar yasab, rangli qalamlar bilan qo‘shimchalar chizishingiz ham mumkin. Tayyorlagan ushbu san’at asaringizni farzandingiz xonasidagi chiroyli bir joyga osib qo‘yishingiz mumkin. Katta barglarni kichkina qo‘llar bilan o‘rganish juda maroqli, tabiatdan to‘plangan materiallarni birlashtirish esa nihoyatda qiziqarli.') WHERE id = 'a3d322c1-283c-451c-8c14-a41a173f99ea';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tengdoshlar bezoriligi (bulling) — bolaning o‘z yosh guruhidagi shaxslar tomonidan qayta-qayta duchor qilinadigan jismoniy, og‘zaki yoki munosabatlarga bog‘liq tajovuzkor xatti-harakatlardir. Farzandingizning gaplari yoki xatti-harakatlarida bunday bezorilik alomatlarini sezsangiz, ularni e’tiborsiz qoldirmasligingiz kerak. Bu belgilarni payqaganingizda, bola bilan muloqotingiz uni hukm qilish yoki ayblashga emas, balki yuz bergan voqealarni va bolaning holatini to‘liq tushunishga qaratilishi juda muhim. Bezorilikka uchragan bolalar o‘zlarini bunga loyiq va yetarli darajada yaxshi emas deb o‘ylashlari mumkin. Shu sababli muloqotda «Nega unga javob qaytarmading?» kabi ayblovchi va so‘roq qiluvchi munosabat salbiy ta’sir ko‘rsatishi mumkin. Tengdoshlar bezoriligi jiddiy muammo bo‘lib, zo‘ravonlik qilayotgan bolalar ham unga uchragan bolalar kabi yordamga muhtoj. Zarur choralar ko‘rilmasa, bu holat har ikki tomon uchun ham qisqa va uzoq muddatda ko‘plab muammolarga olib keladi.') WHERE id = '9a287db2-0736-4590-9beb-67cb23fbacb8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz kuniga taxminan 200 ml, ya’ni 1 stakan kefir ichishi uning umumiy salomatligini saqlash uchun yetarli. Kefir qatiqqa qaraganda to‘yimliroq. U sut tarkibidagi barcha oziq moddalarni saqlab qolishi va tarkibidagi probiotik bakteriyalar ta’siri tufayli juda yuqori ozuqaviy qiymatga ega. Shuningdek, kefir bolangiz organizmi tomonidan osonroq o‘zlashtiriladi. Oqsil, muhim minerallar hamda B12, B1, K vitaminlariga boyligi kefirni boshqa sut mahsulotlariga qaraganda qimmatliroq qiladi. Qatiq ovqat hazm qilish tizimining tozalanishiga va foydali bakteriyalarning oziqlanishiga yordam bersa, kefir ichak mikroflorasini muvozanatga keltiruvchi va mustahkamlovchi bakteriyalarga ega. Qisqasi, farzandingiz taomnomasida qatiq bilan bir qatorda kefirga ham o‘rin berishingiz kerak. Agar bolangiz oddiy kefirning ta’mini yoqtirmasa, uni uydagi mevalar bilan aralashtirib, turli ta’mlar yaratishingiz mumkin.') WHERE id = '75f841e9-b23b-4e4f-8c19-19710a966f43';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ota-ona bo‘lish, ehtimol, dunyodagi eng qiyin vazifadir. Chaqaloqli bo‘lishingiz haqidagi xabarni olgan kundan boshlab zimmangizda katta mas’uliyat bor. Yaxshi ota-ona bo‘lish uchun, avvalo, o‘zingiz ham inson ekaningizni unutmang va o‘zingizga xato qilishga imkon bering. Zimmangizdagi bu bosimni kamaytirsangiz, ota-onalik vazifangizni samaraliroq bajara olasiz. Farzandingiz ulg‘ayish jarayonida rioya qilishi kerak bo‘lgan qoidalar ham bo‘lishi lozim. Agar «U baribir butun umri davomida qoidalar asosida yashaydi, hech bo‘lmasa hozir erkin bo‘lsin», deb o‘ylasangiz, bu bilan bolaning rivojlanishini sekinlashtirishingiz yoki uning doimo bolalarcha bo‘lib qolishiga sabab bo‘lishingiz mumkin. Unutmang, bu qiyin vazifani faqat o‘zingizni zo‘riqtirib uddalashga harakat qilsangiz, juda charchab qolasiz. Muayyan qoidalarni belgilab, bolaning ularga amal qilishini ta’minlash orqali yukingizni biroz bo‘lsa-da yengillashtirishingiz mumkin.') WHERE id = '23ccddfb-c2e9-4bc4-bc64-31a8fb82ad5b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizga xavotir va qo‘rquvlari bilan bosqichma-bosqich yuzlashishga yordam bering hamda birgalikda reja tuzing. Masalan, o‘rgimchakdan qo‘rqadigan bola uchun birinchi qadam o‘rgimchak rasmlarini ko‘rish bo‘lishi mumkin. Keyingi bosqichlarda bola qo‘liga o‘yinchoq o‘rgimchakni olishi, tirik o‘rgimchak bilan bir xonada qolishi va har safar unga bir metr yaqinlashishi mumkin. Bu bosqichlarni farzandingiz bilan birgalikda belgilang va har bir qadamda uning sa’y-harakatlarini maqtang. Uni xavotirga solayotgan masala bo‘yicha imkon qadar ko‘proq yechim topishga undang va qaysi yechim yaxshiroq natija berishini tushunishi uchun unga savollar bering. Farzandingizni o‘z muammolarini mustaqil hal qilish yo‘lida tashlagan ushbu katta qadami bilan albatta tabriklang.') WHERE id = '773a65e5-9a54-4e9c-97a7-6988ed4a909d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz juda ko‘p savol beradi, shunday emasmi? Ba’zan mazmunli, ba’zan ma’nosiz, ba’zan o‘rinli, ba’zan esa mutlaqo noo‘rin. Agar bolaning savoliga shoshilib, u tushunmaydigan murakkab so‘zlar yoki qiziqishini yanada oshiradigan tafsilotlar bilan javob bersangiz, ketma-ket yangi savollar tug‘ilishi muqarrar. Izohingizdan keyin qanday savol berilishini oldindan taxmin qilish vaqtingizni tejaydi hamda dastlabki javobingizni to‘g‘riroq shakllantirishga yordam beradi. Agar qo‘shimcha savollarga vaqtingiz yoki kuchingiz bo‘lmasa, sodda va tushunarli javoblarni afzal ko‘ring. Bola sizni hamma narsani biladi deb o‘ylaydi, aslida esa siz bilmaydigan narsalar ham ko‘p bo‘lishi mumkin. Javobni bilmasangiz, ochiqchasiga Bilmayman deb ayting. Biroq bolaga bu javobni qanday va qayerdan topishi mumkinligini ko‘rsatib berish juda foydali bo‘ladi.') WHERE id = 'e49ce7b4-2a04-4ecf-a4d4-0a18be73ddf0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Oila davrasida o‘z fikrini ifodalash imkoniyati berilgan bola boshqa muhitlarda ham o‘zini dadil tutishi mumkin. Mehr va shartsiz qabulni his qiladigan, oila a’zolari bir-biriga vaqt ajratadigan muhitda ulg‘aygan bola o‘zining qadrli ekanini va fikrlari e’tiborga olinishini his qiladi. Bu esa o‘ziga ishonch uchun beqiyos poydevordir. O‘ziga ishonch insonning o‘z qobiliyatlariga ishonishi va o‘zi haqidagi ijobiy tasavvurini anglatadi. Shu sababli bolalikdan bajarilgan har bir vazifa muhim tajriba orttirish imkonini beradi. Unutmaylik, farzandlarimiz ulg‘ayishi davomida biz ular uchun go‘yo ko‘zgu bo‘lamiz. Ular bizdan ko‘rganlari, eshitganlari va biz ularga his qildirgan tuyg‘ular asosida shakllanadi. O‘ziga ishongan ota-onaning o‘ziga ishongan farzandni voyaga yetkazish ehtimoli yuqoriroq.') WHERE id = 'e0c1d026-5704-4d25-b4c7-eb54776fe87a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maqsadimiz — bolani avvalo o‘ziga, so‘ngra boshqa odamlarga yordam bera oladigan inson qilib tarbiyalash. U faqat men yoki faqat boshqalar degan ikki yondashuv o‘rtasida muvozanatli mavqeni egallashi muhim. Masalan, chaqalog‘ingizga rang-barang mashg‘ulotlar kiritilgan 40 sahifali bo‘yash va stikerlar kitobini sotib oldingiz. Uni kitobning bir sahifasini yirtib, o‘yin o‘rtog‘iga berishga undashingiz mumkin. Birgalikda bo‘yash va stiker yopishtirishdan zavqlanishiga yordam berishingiz mumkin. Do‘sti ham u bilan o‘yinchog‘ini baham ko‘rganida, bu ijobiy xatti-harakatni alohida e’tirof etishingiz mumkin. Bunda bolaning baham ko‘rishga rozi bo‘lishi va beradigan narsasini o‘zi tanlashiga hurmat bilan munosabatda bo‘lish muhim.') WHERE id = '2b7fec61-281a-4d68-bfc0-d7dc7a15e8b1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ovqatlanish tartibi har bir oziq-ovqat guruhidagi mahsulotlar yetarlicha iste’mol qilinishini ta’minlaydigan tarzda tuzilishi kerak. Yetarli va muvozanatli ovqatlanmaydigan bolalarning o‘sishi va aqliy rivojlanishiga salbiy ta’sir ko‘rsatilishi mumkin. Anacan oilasi sifatida siz uchun tayyorlagan namunaviy kundalik menyumiz quyidagicha: Nonushta: Yarim stakan sut, yarim stakan suli yormasi (sut bilan aralashtirilgan), 1 stakan sitrus mevalar sharbati yoki pomidor sharbati, qovun yoki qulupnay. Yengil tamaddi: Yarim stakan sut, yarimta banan, 1 bo‘lak kepakli non, 1 choy qoshiq sariyog‘. Tushlik: 2 bo‘lak kepakli non, 1 choy qoshiq sariyog‘, 30 gramm go‘sht yoki pishloq, chorak stakan sabzavot (60 gramm). Kechki ovqat: 60 gramm go‘sht, baliq yoki tovuq go‘shti, yarim stakan makaron, guruch yoki kartoshka, yarim stakan sabzavot, 1 choy qoshiq sariyog‘.') WHERE id = 'a045a8a2-d4d7-4760-83e1-896e87106a0a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bilan maroqli vaqt o‘tkazish uchun hikoyali mashg‘ulotlar qilishingiz mumkin. Qisqa hikoya o‘qing va o‘qiganlaringiz haqida unga savollar bering. Masalan: Hikoyaning bosh qahramoni kim edi? Voqea qayerda sodir bo‘ldi? Oxirida nima bo‘ldi? kabi... Agar o‘qiyotgan kitobingiz unga tanish bo‘lsa, vaqti-vaqti bilan to‘xtab, Endi nima bo‘ladi? U nima deydi? deb so‘rang. Yangi sotib olgan hikoyangizning bir qismini o‘qing va undan davomini taxmin qilib, hikoyani yakunlashini so‘rang. Siz hikoya o‘qiyotganda u ko‘zlarini yumsin, qahramonning ismi har safar tilga olinganida ko‘zlarini ochsin yoki qarsak chalsin. Siz o‘qiganingiz sari u hikoyani o‘zi jonlantirsin yoki o‘yinchoqlari yordamida namoyish etsin. Butun oila bilan hikoya tuzish o‘yinini o‘ynang: biringiz hikoyani boshlang, keyin hamma navbat bilan bittadan gap qo‘shib, hikoyani yakunlasin.') WHERE id = '15c8d0bb-8482-4ae4-8209-e9a1eaef5f89';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingizning xatti-harakatlarida noodatiy holatni sezsangiz yoki shunchaki nimadir joyida emasligini his qilsangiz, buni e’tiborsiz qoldirmasligingiz kerak. Chunki bolalar ruhiy qiyinchiliklarni boshdan kechirayotganini faqat ularning xatti-harakatlaridagi o‘zgarishlardan anglashimiz mumkin. Bolalar kattalar kabi qarshingizga o‘tirib, "mening muammoyim bor" deb gapirmaydi. Ko‘pincha ularda muayyan alomatlar namoyon bo‘ladi. Ba’zan ular haddan tashqari harakatchan bo‘lishi, ba’zan esa xatti-harakatlarida ortga qaytish kuzatilishi mumkin. Masalan, butilkadan ichishni tashlagan bolaning yana butilka so‘rashi yoki hojatxonadan foydalanishni o‘rgangan bolaning yana tagini ho‘llay boshlashi kabi. Ba’zan diqqat tarqoqligi kabi holatlar ham yuz berishi mumkin. Chaqalog‘ingizda ehtimoliy ruhiy salomatlik muammosiga ishora qiluvchi alomatlarni ko‘rsangiz, uni erta aniqlash davolashni osonlashtiradi.') WHERE id = '11263985-19b8-4671-b976-ed9543821ed8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandim ovqat yemaydi, ishtahasi yo‘q bolaga nima qilish kerak, deb o‘ylayotgan bo‘lsangiz, siz uchun bir nechta tavsiyamiz bor. Avvalo, albatta, shifokor ko‘rigidan o‘tib, kerakli tahlillar yordamida bolaning holatini baholash zarur. Chunki ba’zan qondagi ayrim ko‘rsatkichlarning pastligi ishtahasizlikka sabab bo‘lishi mumkin. Agar muammo jismoniy salomatlik bilan bog‘liq bo‘lmasa, bunga psixologik omillar yoki noto‘g‘ri shakllangan ovqatlanish odatlari ta’sir qilayotgan bo‘lishi mumkin. Bunday holatda farzandingizga to‘g‘ri ovqatlanish haqiqatan ham muhimligini tushuntiring. Ovqat yemagan kuni qornini marmelad yoki zararli yeguliklar bilan to‘ldirishiga yo‘l qo‘ymang; och qolganida o‘ynash qiyinlashishi va quvvati kamayishini unga tushuntiring. Yeydigan taomlarini tanlashiga imkon bering. Unga foydali mahsulotlardan 3 ta variant taklif qiling, yakuniy qarorni o‘zi qabul qilsin. Taom tayyorlashda sizga yordam berishi ham uning ishtahasini oshirishi mumkin. Farzandingiz siz istagan paytgacha emas, o‘zini to‘q his qilguncha ovqatlanishi kerak. To‘yganini aytganida uni yana yeyishga majburlamasangiz, ovqatdan bezishining oldini olasiz.') WHERE id = '57426f07-6e04-4acb-a14f-3d19459d109e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda to‘g‘ri tashkil etilgan san’at ta’limi farzandingizning ijodkorligini rivojlantirish uchun katta imkoniyat yaratadi. Sog‘lom va samarali san’at ta’limi uning atrofdagi go‘zallikni his qiladigan, yangilik yaratadigan va ijodkor inson bo‘lib ulg‘ayishiga yordam beradi. San’at ta’limi albatta maktabda boshlanishi kerak degan qoida yo‘q. Dastlabki asosiy ko‘nikmalar oilada berilgani kabi, bola qiziqish bildirsa va oilasi uni qo‘llab-quvvatlasa, maktabga borishidan oldin ham san’at bilan tanishishi mumkin. Uyda farzandingiz uchun maxsus stol va u osonlik bilan olishi mumkin bo‘lgan anjomlar qutilarini tayyorlang. U bilan birga biror rassomning hayotini o‘rganish va suratlar haqida suhbatlashish uning dunyoqarashi hamda tafakkuri rivojlanishi uchun juda muhim. Uning ishlarini baholashda ruhlantiruvchi va qo‘llab-quvvatlovchi so‘zlarni ayting. "Ko‘z boshning tepasida bo‘lmaydi", "Osmon bunday rangda bo‘lmaydi" kabi tanqidiy fikrlardan saqlaning. Farzandingiz tashlandiq materiallardan xayolingizga ham kelmaydigan asarlar yaratishi mumkin. Buning uchun unga imkoniyat va vaqt bersangiz kifoya. Agar bunday imkoniyat erta yoshda yaratilsa, u maktabga yanada ijobiy, kirishimli va o‘zini erkin ifodalay oladigan inson sifatida qadam qo‘yadi.') WHERE id = 'b288601e-6a7e-4dfe-be66-b4dd1770340c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Muayyan yoshdan keyin farzandingiz bilan birga uxlash ham bolaning rivojlanishi, ham ota-ona munosabatlarining sog‘lomligi uchun muammo tug‘diradi. Ota-onasi bilan birga uxlaydigan bola ularning o‘ziga xos shaxsiy hududi borligini tushunishda qiynaladi. Bundan tashqari, bolaning yolg‘iz uxlash va o‘zini tinchlantirish qobiliyati pasayadi. Boshqacha aytganda, doimo ota-onasi bilan uxlaydigan bola kelajakda mustaqil ravishda uxlab qolishda qiynaladi. Chunki uni tinchlantirib, uyquga tayyorlaydigan inson — ota-onasi yonida bo‘lmasa, o‘zini chorasiz his qiladi. Shuningdek, bir to‘shakda uxlash ham bolaning xavfsizligi, ham ota-onaning uyqu sifati uchun xavf tug‘diradi. Ota-onalar bola bilan birga uxlaganida bir-biriga vaqt ajrata olmaydi, bu esa munosabatlarning hissiy va yaqinlik jihatlariga salbiy ta’sir qiladi. Shuning uchun agar siz hali ham farzandingiz bilan birga uxlayotgan bo‘lsangiz, bunga allaqachon chek qo‘yish vaqti kelgan. Uyqungiz qanchalik sifatli bo‘lsa, uyg‘oq paytingizda birga o‘tkazadigan vaqtingiz shunchalik yoqimli bo‘ladi.') WHERE id = 'c391391b-fd17-4aff-b9b8-249146e9ae1d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘ziga berilgan bola to‘g‘ri muloqot qilishni o‘rganishi uchun ota-onasining ko‘magiga muhtoj. Uni o‘z dunyosidan chiqarib, u bilan haqiqiy dunyo o‘rtasida ko‘prik qurishingiz kerak. Og‘zaki muloqot qila olmagan paytingizda xatti-harakat va yuz ifodalari orqali aloqa o‘rnatishga harakat qiling. Uni o‘z holiga tashlab qo‘yish eng oson, ammo eng noto‘g‘ri yo‘ldir. Avvalo, farzandingizni yaxshi bilib olishingiz kerak. Uni eng ko‘p nima qiziqtirishini aniqlang: tovushlarmi? Ranglarmi? Harakatlarmi? U bilan qayerda va qanday qilib yaxshiroq muloqot qila olasiz? Har safar bir-ikki soniya ko‘proq o‘ynash, bir-ikki so‘z ko‘proq gaplashish uning sizdan va atrofdagilardan qochishining oldini oladi. Vaqt o‘tishi bilan uning tashqi dunyo bilan muloqot qilish istagi ortadi.') WHERE id = '8f9a38dd-ddb8-44a1-9282-56cb4da6e483';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar iste’mol qilishi kerak bo‘lgan foydali mahsulotlarni ko‘pchiligimiz bilamiz, ammo xavfli mahsulotlar deganda xayolingizga nima keladi? Birinchi o‘rinda, albatta, fastfud turadi. Uning tarkibidagi transyog‘lar bolalar salomatligi uchun juda zararli. Qovurilgan taomlar ham xavf tug‘diradi: ular vazn ortishiga sabab bo‘ladi va yurak-qon tomir tizimi salomatligiga tahdid soladi. Bolalar ovqatlanishi uchun zararli bo‘lish bilan birga, ortiqcha kaloriya manbai bo‘lgan gazlangan va rangli ichimliklar hech qanday vitamin yoki mineral bilan ta’minlamaydi. Ortiqcha kaloriyaning yana bir manbai bo‘lgan shirinliklar va konfetlar ham bolalar uchun xavfli mahsulotlardandir; ular qondagi qand miqdori muvozanatini buzadi. Qahva esa bolalar uchun eng xavfli ichimliklardan biridir. Uyqu buzilishi, yurak urishining tezlashishi va tishlarning sarg‘ayishiga olib keladigan qahva bola organizmi uchun juda zararli, shuning uchun undan voz kechish lozim.') WHERE id = '9049d2d7-4116-4517-a99a-80cecd0c0b9b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Har bir ota-ona farzandi bilan gaplashishga eng ko‘p tortinadigan mavzulardan biri — bolalar qanday dunyoga kelishi masalasidir. Bu payt kelganida vaziyatni oson boshqarish uchun oldindan tayyorlaning. U so‘ramasa ham, bir kuni bu mavzular haqida albatta gaplashishingizga to‘g‘ri keladi. Oldindan kerakli ma’lumotlarni o‘qib chiqing va nima deyishingizni belgilab oling. Bunga ona va ota sifatida birgalikda tayyorlaning. Boshqa barcha mavzularda bo‘lgani kabi, bu borada ham bir xil fikrda bo‘lishingiz muhim. Agar biringiz bolaga uni laylaklar olib kelganini aytsangiz, ikkinchingiz esa xonadan qochib chiqib ketsa, demak, muammo bor. :)') WHERE id = '1d121936-7622-4838-8d81-9a1fd3ca7851';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar odatda muayyan masala faqat o‘zlarini tashvishga soladi, deb o‘ylashadi va xavotirlanishni g‘alati holat deb hisoblaganlari uchun bu haqda gapirishdan tortinishadi. Farzandingizga biror masaladan xavotirlanish tabiiy holat ekanini his qildiring. Shu tariqa unga o‘z tashvishlari haqida gapirishni osonlashtirishingiz mumkin. “Sening o‘rningda boshqa birov bo‘lganida, nima deb o‘ylardi?” kabi savollar orqali farzandingizga voqealarga turli nuqtayi nazardan qarashga yordam bering. Uning javoblari o‘ziga yo‘l ko‘rsatadi. “Tashvishlaring ro‘yobga chiqadi deb o‘ylashingga nima sabab bo‘lyapti?” yoki “Bunday holat oldin ham boshingga tushganmi?” kabi savollar berib, farzandingizga xavotirlarining sababini anglashga yordam bering va o‘zingiz ham uni tushunishga harakat qiling. Farzandingizni xavotirga solayotgan masalada shunchaki ovutish o‘rniga, uni qo‘llab-quvvatlashga harakat qiling.') WHERE id = 'd21c7f93-85a4-4a78-bc50-c6c2857a7a2b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz shuni bilishi kerak: yaxshi ish qilsam, meni qadrlashadi, xato qilsam esa menga yo‘l ko‘rsatishadi. Biroq maqtashda mubolag‘adan qochish lozim. Masalan, “Hayotimda ko‘rgan eng chiroyli rasm!” deyish o‘rniga, “Ranglardan foydalanish uslubing menga juda yoqdi!” deyish to‘g‘riroq. Noto‘g‘ri xatti-harakatga bildirgan munosabatingiz ham bolaning shaxsiyatiga emas, bevosita uning xatti-harakatiga qaratilishi kerak. Masalan, “Biror ishni to‘g‘ri qil!” deyish o‘rniga, “Keyingi safar bu masalada yanada e’tiborli bo‘lishingni kutaman”, deng. Bolaning salohiyatiga emas, uning sa’y-harakati, mehnati va osonlikcha taslim bo‘lmasligiga urg‘u bersangiz, u har bir muvaffaqiyatsizligini “hozircha o‘xshamadi” deb qabul qiladi. Shu tariqa ishtiyoqini yo‘qotmasdan yana urinib ko‘rishda davom etadi.') WHERE id = 'ccee8292-0912-47dd-964c-7d03974ce207';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan birga maroqli vaqt o‘tkazish uchun ko‘plab mashg‘ulotlar qilishingiz mumkin. Bir vaqtning o‘zida ham ko‘ngil ochadigan, ham uning rivojlanishini qo‘llab-quvvatlab, diqqat va xotirasini mustahkamlaydigan so‘z o‘yinlarini o‘ynashingiz mumkin. Masalan, siz “Bozorga bordim, olma oldim”, deysiz. Navbat unga kelganida, siz aytgan gapga yana bitta so‘z qo‘shsin: “Bozorga bordim, olma va banan oldim”. Har safar navbat kelganida gapga bittadan so‘z qo‘shib, adashib ketguningizcha o‘yinni davom ettiring. Xotira uchun yana bir o‘yin tavsiyasi: orasida bir soniyadan tanaffus qilib uchta so‘z ayting, farzandingiz esa ularni ayni ketma-ketlikda takrorlasin. U buni oson bajara boshlaganida, so‘zlar sonini to‘rtta, beshta va oltitagacha oshiring.') WHERE id = '11e9cc29-3146-4adb-a397-8a8bd440816e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'So‘nggi paytlarda kundalik hayotimizda mantiqiy va aqlni charxlovchi o‘yinlar haqida ko‘p eshityapmiz. Xo‘sh, bu qanday o‘yinlar, ular haqiqatan ham kerakmi va bolalarimizga qanday foydasi bor? Hech qanday maxsus bilim va ko‘nikma talab qilmaydigan, belgilangan qoidalar doirasida fikr yuritib o‘ynaladigan o‘yinlar aqlni charxlovchi o‘yinlar deb ataladi. Bu o‘yinlar bolalarning muammolarni anglash va baholash qobiliyatini rivojlantirishda muhim o‘rin tutadi. Voqealarga turli tomondan qaray olish, muammoga duch kelganda tez va to‘g‘ri qaror qabul qilish — bunday o‘yinlarning asosiy maqsadlaridandir. Ilmiy tadqiqotlar aqlni charxlovchi o‘yinlar bilan muntazam shug‘ullanadigan bolalarning bilish qobiliyatlari va salohiyati oshishini ko‘rsatadi. Sotuvda bolalarning yoshi va fe’l-atvoriga mos turli xil aqlni charxlovchi o‘yinlar mavjud. Siz ham farzandingiz uchun eng mosini izlab topib, uning aqliy rivojlanishiga qiziqarli tarzda hissa qo‘shishingiz mumkin.') WHERE id = 'f713d2d1-d132-46a0-988c-91151d41322e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ishlaydigan onalar eng ko‘p his qiladigan tuyg‘ular qatoriga aybdorlik va o‘zini yetarli emasdek his qilish kiradi. Bu tuyg‘ular ta’sirida bo‘lgan onalarning aksariyati farzandi bilan yetarlicha vaqt o‘tkaza olmayapman, deb o‘ylab, bolani o‘zi boradigan hamma joyga birga olib borishga harakat qiladi. Biroq bunday tadbirlarda bola bilan o‘tkazgan vaqtingiz uyda u bilan o‘ynab o‘tkazgan vaqtingizdan qadrliroq bo‘lmaydi. Birga vaqt o‘tkazayotganda eng muhimi — u bilan gaplashish, ko‘zlariga qarash, unga mehr bilan teginish, ya’ni butun diqqat va qiziqishingizni unga qaratishdir. Shu yo‘l bilan biz bolaga “sen qadrlisan” degan xabarni sog‘lomroq tarzda yetkazamiz. Farzandingizga ishga qaytishingiz kerakligini ochiq tushuntirishingiz va birgalikda qanday vaqt o‘tkazishingiz mumkinligi haqida gaplashishingiz lozim. Dastlab ayriliq paytida qiyinchilik yuzaga kelsa-da, keyinchalik orttiriladigan ijobiy tajribalar bu jarayonning yengilroq kechishiga yordam beradi.') WHERE id = '6bad7fb7-a9c2-4e5d-aa23-e31daa627dd6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bola hali o‘lim hodisasiga duch kelmasidan oldin unga yoshiga mos tushuntirish berish va savollariga javob qaytarish o‘limni hayotning bir qismi sifatida qabul qilishiga yordam beradi. O‘lim mavzusida gapirganda xotirjam bo‘ling. Farzandingiz savol berganida, barcha savollarning javobini bilmasligingizni aytishingiz mumkin, ammo o‘lim haqida ham tug‘ilish kabi tabiiy tarzda gapirishga harakat qiling. O‘limni to‘liq anglash uchun ma’lum yoshga yetish kerak bo‘lsa-da, bu asta-sekin kechadigan jarayondir. Unga kichikligidanoq gullar, hasharotlar va hayvonlarning hayot sikli haqida so‘zlab berishingiz mumkin. Farzandingizga biror o‘simlik yoki hayvon uchun mas’uliyat yuklab, uning tug‘ilish, o‘sish va o‘lish jarayonlarini kuzatishiga imkon yaratishingiz mumkin. Shu tariqa u barcha tirik mavjudotlarning, jumladan, odamlarning ham o‘lishi tabiiy holat ekanini osonroq anglaydi.') WHERE id = '126484cc-7b4e-4c94-b9de-bb4e567b23d9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tirnoq tishlash odati odatda 3–4 yoshda boshlanadi. Biroz vaqt o‘tgach kamayishi mumkin, ammo o‘smirlik davrida yana paydo bo‘lishi ehtimoli bor. Bu xatti-harakat boshqalarga taqlid qilish orqali o‘rganilishi mumkin, lekin u bolada xavotir yoki tashvish uyg‘otadigan vaziyat tufayli paydo bo‘lgan o‘ziga ishonchsizlik belgisi ham bo‘lishi mumkin. Bolani doimiy tanqid qilish, rashk, mukammallikka intilish, yetarlicha mehr va e’tibor ko‘rmaslik yoki haddan tashqari bosimga asoslangan avtoritar tarbiya bunga misol bo‘la oladi. Bunday xatti-harakatlarga duch kelganda ota-onalar xotirjamlikni saqlashi va keskin munosabat bildirmasligi juda muhim. Tirnoq tishlash, barmoq so‘rish va tagini ho‘llash kabi holatlar ko‘plab bolalarda kuzatilsa-da, to‘g‘ri yondashuv bilan vaqt o‘tishi bilan yo‘qoladi. Buni anglash — qo‘yiladigan birinchi va eng muhim qadamdir.') WHERE id = '9f03c9c1-57bd-4be6-99b4-cf24c5f0befa';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz ham depressiyaga tushishi mumkinligini bilarmidingiz? Bolangizning nutqi va mavhum fikrlash qobiliyati hali to‘liq shakllanmaganligi sababli, uning ahvolini gaplaridan tushunish qiyin bo‘lishi mumkin. Bunday paytda sizning kuzatuvchanligingiz muhim ahamiyat kasb etadi. Avvalo ishtahasiga e’tibor bering: kattalarda bo‘lgani kabi, kichik bolalarda ham depressiya ishtahaning yo‘qolishi yoki haddan tashqari ko‘p ovqatlanishga sabab bo‘lishi mumkin. Uyqu buzilishi ham yana bir belgidir: bola uxlashga qiynalishi, juda ko‘p uxlashi yoki uyqusi tez-tez bo‘linishi mumkin. Depressiyadagi bolaning quvvati va qiziqishi pasayadi, u yangi narsalarni kashf etishni istamaydi. Agar shubhalansangiz, bolangizning yuz ifodasi, ovoz ohangi va o‘ynayotgan o‘yinlariga ham e’tibor bering.') WHERE id = '8ef9e305-ba45-4f0f-bc21-05cb1835ea57';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yoshda siydik pufagi mushaklari hali unchalik kuchli bo‘lmagani uchun, hojatxonaga o‘rgatish yakunlangan bo‘lsa ham, ba’zan “ko‘ngilsiz holatlar” yuz berishi mumkin. Taxminan 6 yoshgacha bu holat me’yoriy hisoblanadi. Ayniqsa, oilada bunday moyillik bo‘lsa, darhol xavotirlanishga hojat yo‘q. Avvalo sabrli bo‘ling va bolani jazolamang. E’tiboringizni hodisaga emas, bolangizga qarating. Suyuqlikni tez shimadigan tagliklar va karavot uchun himoya choyshablari ishingizni yengillashtirishi mumkin. Bolani muayyan vaqtlarda hojatxonaga olib borish yoki buni eslatib turish tagini ho‘llash holatlarini kamaytiradi. Agar bu holat tez-tez takrorlansa, avval fiziologik sabablarni aniqlash uchun shifokorga, muammo fiziologik bo‘lmasa, psixologga murojaat qilishingiz tavsiya etiladi.') WHERE id = '14f257f5-a3b7-4545-bf29-f1af120629f2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘ta ta’sirchan bolalar his-tuyg‘ulariga tayanib yashaydi. Maktabda mavzuni tushuntirishga qiynalishi mumkin. Chunki ular har bir narsani mayda tafsilotlardan boshlaydi va umumiy xulosaga kelishi qiyin bo‘ladi. Bundan tashqari, ular boshqalarning his-tuyg‘ulariga shu qadar sezgir bo‘lishi mumkinki, hatto yuz ifodasidagi eng kichik o‘zgarishlarga ham ortiqcha e’tibor qaratadi. Sinfda do‘stining birgina qarashi ham muammoga sabab bo‘lishi mumkin. Bunday ta’sirchanlik ularning o‘z his-tuyg‘ulariga ham taalluqlidir. Ular o‘z tuyg‘ularini shu qadar kuchli boshdan kechirishi mumkinki, xafa bo‘lganda o‘zini yerga tashlashi, jahli chiqqanda esa kimnidir tepishi mumkin. Albatta, bunday bolani tarbiyalash oson emas. Agar farzandingiz o‘ta ta’sirchan bo‘lsa, uning his-tuyg‘ulariga hurmat bilan yondashishingiz va bu tuyg‘ularni boshqarishiga yordam berish uchun o‘yin terapiyasi kabi turli usullardan foydalanishga harakat qilishingiz kerak.') WHERE id = '284d154e-bcc2-4a5e-8f82-d1327b18c3dd';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Uyda chaqalog‘ingiz uchun maxsus stol va u bemalol qo‘li yetadigan jihozlar qutilarini tayyorlashingiz mumkin. Qutilarga rangli qalamlar, turli bo‘yoqlar, qaychi, yelim, mo‘yqalam, rangli patlar, munchoqlar va yaltiroq bezaklar kabi uning e’tiborini tortadigan materiallarni solishingiz mumkin. Qaychi, yelim va mo‘yqalamdan foydalanish bolaning qo‘l-ko‘z muvofiqligini rivojlantirishga, tushunchalar va muammolar ustida fikr yuritishiga yordam beradi. U kartonlarni kesishi, munchoqlarni yopishtirishi, ishlarini rangli bo‘yoqlar bilan jonlantirishi mumkin... Atrof biroz tartibsiz bo‘lib qolsa ham, qo‘lidagi vositalar bilan mustaqil shug‘ullanishiga ruxsat bering. Farzandingiz qancha ko‘p tajriba orttirsa, ishlari shuncha rang-barang bo‘ladi. Dunyoqarashini kengaytirish uchun turli tajribalarni o‘zlashtirishi muhim.') WHERE id = '587604c7-71d5-493d-8249-0631259082d6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz qo‘rquv va xavotirlarini mustaqil ravishda yenga olishiga chin dildan ishoning. “O‘zi uddalay olmaydi” degan fikrdan yiroq bo‘ling. Bolani haddan tashqari himoya qilish uning qo‘rquv va xavotirlari saqlanib qolishiga sabab bo‘ladi. Agar sharoit xavfsiz bo‘lsa, mustaqil harakat qilishiga ruxsat bering va uning jasoratini oshiring. Maysazorda yugurayotgan chaqalog‘ingiz yiqilib tushishidan xavotirlanib, ortidan yugurib uning ishtiyoqini so‘ndirmang. Farzandingizga qo‘rquvlaridan qochmasdan, ularga yuzlanish imkonini bering, ammo hech qachon bosim o‘tkazmang. Bolaga bosim o‘tkazish vaziyatni yanada murakkablashtirishi mumkin.') WHERE id = '77d921f8-2e0e-404d-a8d3-9897768c9c98';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizga vaqt ajratishingiz, u bilan suhbatlashish uchun turli mavzular topishingiz va unga tez-tez o‘z fikrini bildirish imkonini berishingiz kerak. Suhbat paytida farzandingizning ko‘zlariga qarang, uni diqqat bilan tinglang va fikrlarini qadrlashingizni his qildiring. Unga yoshiga mos vazifalar bering, yutuqlarini e’tirof eting va boshqalar oldida kamsitmang. Uni boshqa bolalar bilan taqqoslashdan, tanqid qilishdan va hukm qilishdan saqlaning. Odamlar orasida o‘z fikrini aytishga undang. Bolaning istak va ehtiyojlariga e’tiborli bo‘ling, muvaffaqiyatga erishishi uchun imkoniyat yarating, fikrlariga hurmat bilan munosabatda bo‘ling va to‘g‘ri qadamlari uchun maqtang. Unutmang, shunchaki nasihat qilish yoki uni gapga kiritishga urinish haqiqiy muloqot emas; muloqot o‘zaro bo‘lishi kerak.') WHERE id = '089d3994-9ba4-466d-b069-c4fef620e5c6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Biz ba’zan bolalar qoidalarni yoqtirmaydi deb o‘ylaymiz, aslida esa qoidalar, ya’ni chegaralar asosida ulg‘aygan bolalar baxtliroq bo‘ladilar. Bolalar “Nimani qay darajada qilishim mumkin?”, “Biror narsani xohlasam, qanchalik turib olishim mumkin?”, “Kim bilan qanday gaplashishim va kimga qanday munosabatda bo‘lishim kerak?” kabi savollarning javobini, ya’ni chegaralar qayerda ekanini bilishga ehtiyoj sezadilar. Ular buni uyda ota-onalar belgilagan qoidalar va bu qoidalarning amalda qo‘llanishi orqali o‘rganadilar. Chegaralar bolalarda o‘ziga ishonch shakllanishiga va kelajakda mas’uliyatli inson bo‘lib ulg‘ayishiga yordam beradi. Bola chegara tushunchasini bilmasa, uning xatti-harakatlari nazoratsiz bo‘lishi va u tez-tez muammolarga duch kelishi mumkin. Tegishli chegaralarni belgilash, avvalo, ularning xavfsizligi va o‘zlarini himoyalangandek his qilishlari uchun muhimdir. Uydagi qoidalar oila a’zolarini bir-biriga bog‘laydi va bolalar ehtiyoj sezadigan oilaga mansublik tuyg‘usini shakllantiradi.') WHERE id = '699e3b68-c7e4-4d03-b2e2-74df09355eb7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2.5 yoshdan boshlab bolalar ko‘rgan voqea va xatti-harakatlariga taqlid qila boshlaydilar. Ehtimol, siz ham buni allaqachon payqagandirsiz. Tug‘ilgan kunidan beri sizning eng katta taqlidchingiz bo‘lgan chaqaloq doimo sizni kuzatadi. Biroq vaqti-vaqti bilan televizor va multfilmlarni tomosha qiladigan bola taqlid qiladigan boshqa obrazlar aynan multfilm qahramonlaridir. 3-6 yosh oralig‘ida multfilmlarning ta’siri yanada ortadi, chunki bu davrda bolalar tomosha qilayotgan voqealarining ma’nosini tushuna boshlaydilar. Ayniqsa, 6 yoshdan kichik bolalar haqiqat bilan xayol mahsuli o‘rtasidagi farqni aniq anglay olmagani sababli ayrim qahramonlar ularni qo‘rqitishi va uyqu tartibini buzishi mumkin. Ba’zan ular bu obrazlarning nomaqbul yoki qo‘rqinchli jihatlariga taqlid qilishga ham urinadilar. Kuchli qo‘rquvlar va salbiy xatti-harakatlar ortida ko‘pincha bolaning yoshiga yoki mazmunan mos kelmaydigan multfilm turganini ko‘ramiz. Multfilm qarshisida haddan tashqari ko‘p vaqt o‘tkazish bolalarning aqliy, hissiy va bilish qobiliyatlari rivojiga, shuningdek, ijtimoiylashuviga ham salbiy ta’sir ko‘rsatishi mumkin.') WHERE id = '204f1ab3-594f-4639-b9b4-a3571ef26185';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarning xavfsizligi va o‘zlarini himoyalangandek his qilishlari uchun muayyan chegaralar bo‘lishi hamda bu chegaralar nima sababdan qo‘yilgani ularga aniq tushuntirilishi juda muhim. Biroq bu tushuntirish inqiroz paytida emas, voqeadan oldin yoki siz ham, farzandingiz ham tinchlangandan keyin berilishi kerak. U ulg‘ayishi va tez yugura olishi uchun soat 21:00-da uxlashi yoki o‘ziga ko‘proq vaqt ajratishi hamda oilangiz bilan birga ovqatlana olishi uchun vazifalarini 15:00-da boshlashi kerakligini bilishi lozim. Qoidalarni yozma shaklga keltirish sizning ham, chaqalog‘ingizning ham ishingizni osonlashtiradi. Chegaralarni belgilashda "... qilmasang, televizor ko‘rmaysan" kabi tahdidlardan, "tez karavotingga kir" kabi baqiriq va buyruqlardan saqlanishingiz kerak. Bunday muloqot to‘siqlari vaziyatni yanada keskinlashtiradi. Farzandingiz bu chegaralarning sababini tushunishi qanchalik muhim bo‘lsa, siz ham ushbu cheklovlar nima uchun muhimligini anglashingiz shunchalik zarur. Qoidalar biz ota-ona bo‘lganimiz uchun istaklarimizni bajartirishga emas, bolalarning xavfsizligini ta’minlashga xizmat qilishi kerak.') WHERE id = '581c4ace-4612-4470-a608-3338a8a27acc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz o‘z his-tuyg‘ularini tanib olishi uchun ijodiy o‘yinlardan foydalanishingiz mumkin. Masalan, ko‘zgu oling va farzandingizdan biror hissiyotini yuz ifodasi orqali ko‘rsatishini so‘rang, siz esa "ko‘zgu" sifatida bu hissiyotni topishga harakat qiling. Bolalar bilan his-tuyg‘ular ustida ishlashdan oldin o‘z hislarimizni qay darajada anglashimizni baholash foydali bo‘ladi. Bolalar o‘z his-tuyg‘ularini ifodalashda kattalarga qaraganda erkinroq bo‘ladilar. Shu sababli siz u bilan qanchalik samimiy bo‘lsangiz, farzandingizning xayolida shunchalik kam savol paydo bo‘ladi. Har qanday vaziyatda farzandingizga o‘z hislarini siz bilan bo‘lishish imkonini bering. Shu tariqa chaqalog‘ingiz turli vaziyatlarda nimalarni his qilayotganini ifodalashni o‘rganadi.') WHERE id = '92b069a8-d682-4b32-84a6-aab5d12cd89b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Texnologiya allaqachon hayotimizning ajralmas qismiga aylangan. Texnologiyaga munosabatimiz bolalarni mikroblardan himoya qilishga o‘xshashi kerak. Farzandimizga toza va sog‘lom hayot taqdim etish uchun, albatta, zarur choralarni ko‘rishimiz lozim. Ammo bolani ulg‘aytirishda haddan tashqari ehtiyotkorlik qilib, uni hech qanday mikrob yoki bakteriya bilan aloqa qilishiga yo‘l qo‘ymasak, immun tizimining mustahkamlanishiga va kelajakda kasalliklarga qarshi kurashishiga to‘sqinlik qilamiz. Bolalarni texnologiyadan butunlay uzoq tutish ham ularni kelajakdagi hayotga tayyorgarliksiz qoldirish demakdir. Shu sababli texnologiyadan cheklangan va nazorat ostida foydalanish tavsiya etiladi. Nazorat ostida foydalanish deganda esa bolani hech qachon elektron qurilma bilan yolg‘iz qoldirmaslik nazarda tutiladi.') WHERE id = '728345bf-ef92-4c1c-af86-eddf7faece6d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘yin bola uchun juda muhim faoliyatdir. Bolalar o‘yin orqali ham o‘zlarini, ham tashqi dunyoni kashf etib, uni tanishga harakat qiladilar. Ayniqsa, maktabgacha bo‘lgan davrda o‘yin ovqatlanish va uyqu kabi bolaning eng asosiy ehtiyojlaridan biridir. Bolalar ko‘rgan va o‘rgangan narsalarini o‘yin orqali takrorlaydilar. Bu jarayonda ular o‘z ijodkorligini ishga solib, o‘zlari uchun mutlaqo yangi hikoyalar va dunyolar yaratadilar. O‘yinchoqlar esa bu dunyolardagi buyumlardir. Ularni har doim ham o‘yinchoqlar do‘konidan sotib olish shart emas. Bolalarning tasavvur kuchi shu qadar boyki, ba’zan o‘ynayotganda ularga hatto o‘yinchoq ham kerak bo‘lmasligi mumkin.') WHERE id = '47b06d03-5efa-4298-8f3b-6e73f0cf8e4e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning yolg‘on gapirishiga ota-onaning munosabati sabab bo‘lishi mumkin. Talablari yuqori bo‘lgan ota-onalar farzandi berilgan vazifani ular kutgandek bajara olmaydi deb o‘ylasa, bola oilasini ranjitmaslik uchun yolg‘on gapirishi mumkin. Oilasidan yetarlicha e’tibor va mehr ko‘rmayotgan yoki yangi tug‘ilgan ukasi yoxud singlisi tufayli unga avvalgidek ko‘p vaqt ajratilmayotgan bola oilasining e’tiborini jalb qilish uchun yolg‘onga murojaat qilishi mumkin. Agar ota-ona bolaning har qanday xatosi uchun uni qattiq jazolasa, bola jazodan qochish maqsadida yolg‘on gapirishi yoki aybni boshqalarga yuklab, o‘zini oqlashga urinishi mumkin. Ba’zan bolalar qilgan ishining sababini tushuntirib bera olmaganda ham vaziyatdan chiqish uchun yolg‘on gapiradilar. Ko‘rilgan barcha choralar va aralashuvlarga qaramay, yolg‘on gapirish doimiy tus olsa, mutaxassis bilan maslahatlashish foydali bo‘ladi.') WHERE id = 'a0df7747-9080-47dd-b5f1-105b7749b644';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni kichikligidan kuzatib borsangiz, uning qaysi sohalarga qiziqishi haqida tasavvurga ega bo‘lishingiz mumkin. Shu bilan birga, uni rivojlanishi uchun foydali bo‘lgan turli yo‘nalishlarni sinab ko‘rishga undashingiz va qiziqishlarini kashf etishiga imkon yaratishingiz mumkin. Masalan, tana harakatlarini muvofiqlashtirish uchun gimnastikaga, o‘zini ifodalash uchun ijodiy dramaga, strategik fikrlash va mulohaza yuritish qobiliyati uchun shaxmatga, jamoaviy ruhni rivojlantirish uchun esa basketbol va shunga o‘xshash mashg‘ulotlarga yo‘naltirishingiz mumkin. Agar u mashg‘ulotga ishtiyoq bilan qatnashsa va undan zavq olsa, uni qo‘llab-quvvatlashingiz hamda shu yo‘nalishda rivojlanishi uchun imkoniyatlarni o‘rganishingiz mumkin. Aksincha, farzandingiz doimo shikoyat qilsa va baxtli ko‘rinmasa, u bilan suhbatlashib, vaziyatni birgalikda baholashingiz mumkin. Agar u mashg‘ulotdan mamnun bo‘lmasa, nima bilan shug‘ullanishni xohlashini so‘rab, variantlarni birgalikda o‘rganishingiz mumkin. Bola dastlab hech bir sohada tajribaga ega bo‘lmagani uchun uning nimaga qiziqishini aniqlash maqsadida yangi imkoniyatlar yaratishda davom etishingiz kerak.') WHERE id = '68f978ea-5a44-4322-bd40-20cb94d0fbc1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz ilgari qor yog‘ganini ko‘rgan bo‘lsa, bu unga juda yoqqan bo‘lishi mumkin. Ammo qorli ob-havo har doim ham bo‘lavermaydi. Bunday paytlarda xayoliy qorbo‘ron o‘yinini o‘ynashingiz mumkin. Ishlatilgan qog‘oz parchalari, cheklar va gazetalarni yig‘ing. So‘ng ularning bir qismini g‘ijimlab, koptokcha shakliga keltiring, qolgan qismini esa mayda bo‘laklarga ajrating. G‘ijimlangan qog‘ozlar qor koptoklari, mayda parchalar esa qor parchalari bo‘ladi. Bir kuni kechqurun bir joyga to‘planib, qo‘lqoplaringizni kiying. Barcha mayda qog‘oz parchalarini qor kabi yog‘diring, qog‘oz koptokchalar bilan esa qorbo‘ron o‘ynang. Vaqtingizni maroqli o‘tkazishingizni tilaymiz!') WHERE id = 'a9056ba4-a954-4bc7-956a-5a7bad300b83';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'D vitamini suyak-mushaklar rivoji, miya faoliyati va immunitet tizimi uchun juda muhimdir. Quyosh organizmning D vitaminiga bo‘lgan ehtiyojining 90-95%ini ta’minlaydi. Qolgan qismi esa oziq-ovqatlardan olinadi. Istirohat bog‘ida kuniga atigi 10 daqiqa davomida qo‘llar va yuzga quyosh nuri tushishi D vitamini sintezi uchun yetarli bo‘ladi. Bundan ortiq vaqt quyoshda qolish farzandingizga zarar yetkazishi mumkin. Ayniqsa, quyosh nurlari eng tik tushadigan 10:00 bilan 14:00 oralig‘ida quyoshdan saqlanish kerak. Bu vaqtni yopiq joylarda o‘tkazish maqsadga muvofiqdir.') WHERE id = '325b0b4a-e376-48f0-a0fe-eb9238a52843';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Muammoning emas, yechimning bir qismi bo‘la oladigan bolani tarbiyalash uchun farzandingizni turli o‘yinlar orqali qo‘llab-quvvatlashingiz mumkin. Farzandingiz bilan “Yechim menda” o‘yinini o‘ynashingiz mumkin. Bu hatto mashinada ketayotganda ham o‘ynash mumkin bo‘lgan oddiy o‘yin. Har kim navbat bilan inson duch kelishi mumkin bo‘lgan biror muammoli vaziyatni aytadi va “Nima qilish kerak?” deb so‘raydi. Masalan, “Bozorda onasini yo‘qotib qo‘ygan bola nima qilishi kerak?” yoki “Ko‘chaga chiqdim-u, kalitimni unutganimni bildim, nima qilishim kerak?” kabi. Bunda asosiy maqsad imkon qadar ko‘proq yechim taklif qilishdir. Bu o‘yin farzandingizga “Har qanday yoshdagi inson muammoga duch kelishi mumkin” va “Har bir muammoning bir nechta yechimi bo‘lishi mumkin” degan tushunchalarni singdiradi.') WHERE id = 'cfd8fd4a-c967-4e98-ae2e-bee33b97219d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayniqsa, bolalar uchun nonushtaning ahamiyati juda katta bo‘lib, uning organizmimiz uchun ko‘plab foydalari bor. Nonushta uyg‘onganimizdan keyin yuzaga kelgan energiya tanqisligini to‘ldirib, qondagi qand miqdorini muvozanatlashtiradi. Shuningdek, moddalar almashinuvini tartibga soladigan nonushtani aslo o‘tkazib yubormaslik kerak. Nonushtada iste’mol qilinadigan foydali mahsulotlar o‘ziga xos energiya manbaidir. Chaqalog‘ingiz bu paytda iste’mol qiladigan meva va sabzavotlar ham ozuqaviy qiymati jihatidan juda muhim. Albatta, sut ham nonushtaning ajralmas qismidir. Farzandingizning rivojlanishi uchun nonushta dasturxonida sut albatta bo‘lishi kerak. Nonushtaga nima tayyorlasam ekan, deb o‘ylayotgan bo‘lsangiz, kashar pishloqli tost, turli pishloqlar qo‘shilgan omlet, qaynatilgan tuxum, zaytun va pishloqli bulochkalar, yangi siqilgan meva sharbati, yangi pomidor va sabzavotlardan tayyorlangan sendvich, iliq sut, asal va sariyog‘ kabi turli variantlardan foydalanishingiz mumkin.') WHERE id = 'd0a45b88-13a0-4c9d-a3d1-ee5237e9d55c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Biz “ichimdagini top” deb ta’riflaydigan kamgap bolalar o‘z fikrlarini so‘z bilan ifodalashda qiynalishi mumkin. Ular sekin gapirishi mumkin. Nima qilayotganini, nimalarni his qilayotganini yoki nimani xohlayotganini ifodalash uchun kerakli so‘zlarni topish ular uchun unchalik oson emas. Agar farzandingiz kamgap bo‘lsa, undan kuni qanday o‘tgani haqida so‘rab suhbatlashish sizni biroz charchatishi mumkin. Sizga nisbatan yopiq, atrofdagilarga nisbatan sust bo‘lgan bolangizga hech narsa bera olmayotgandek his qilishingiz mumkin. E’tiboringizga javob bermaydigan inson bilan doimo muloqot qilishga urinish qiyin. Aslida esa farzandingiz shunchaki tashqi dunyoga moslashishda qiynalmoqda. Tashqi dunyo bilan to‘g‘ri muloqot qila olishi uchun unga sizning yordamingiz kerak. Uni majburlamasdan, ko‘proq suhbatlashib va turli muhitlarda bo‘lishiga imkon yaratib, qo‘llab-quvvatlashingiz mumkin.') WHERE id = 'cc456fa9-05c6-4f38-af3f-116a66f4f31a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizda hech qanday shikoyat yoki bezovtalik bo‘lmasa ham, uni muntazam ravishda tibbiy ko‘rikdan o‘tkazish kasalliklarni erta aniqlash va davolashda muhim rol o‘ynaydi. Chaqaloqlik davrida har oylik muntazam ko‘riklardan o‘tgan va emlashlari o‘z vaqtida qilingan bolalarni maktabga chiqishidan oldin ham tibbiy ko‘rikdan o‘tkazish muhim. Ayniqsa, ko‘rish, eshitish, kamqonlik, og‘iz bo‘shlig‘i va tishlar salomatligiga jiddiy e’tibor qaratishimiz kerak. Rivojlanish jarayoni yaqindan kuzatilib, standart o‘sish jadvallari bilan taqqoslanishi, me’yordan og‘ishlar erta aniqlanib, bolada doimiy asorat qoldirmasidan oldin bartaraf etilishi kerak. Bolani ko‘rikdan o‘tkazish orqali ovqatlanish, rivojlanish va psixologik muammolar bor-yo‘qligini aniqlash, shuningdek, siydik, qon va najas tahlillari yordamida holsizlik, ishtahasizlik, kamqonlik, infeksiyalar va parazitar kasalliklarni aniqlash maqsad qilinadi. Bu tekshiruvlar farzandingiz tez o‘sayotgan davrda muammolarni erta aniqlash va davolashni tezlashtirishga yordam berib, uning maktabdagi muvaffaqiyatiga ijobiy ta’sir ko‘rsatadi. Ko‘rik vaqtida shifokorga bola boshdan kechirgan kasalliklar va oilada uchraydigan irsiy kasalliklar haqida ma’lumot berish, shuningdek, emlash kartasini albatta ko‘rsatish kerak.') WHERE id = 'cda4bc4e-2317-4abc-a999-700edd269e6b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz ko‘pincha nimalarni his qilayotganini to‘liq anglamaydi va his-tuyg‘ularini o‘zi bilgan yagona usul — xatti-harakatlari orqali namoyon qiladi. U o‘z tuyg‘ularini tanishi va o‘zini yaxshiroq ifodalay olishi uchun bu hislarni qanday boshqarish mumkinligini tushuntiring. His-tuyg‘ularni bolangiz oson tushunadigan so‘zlar bilan, kitoblar, filmlar yoki rasmlar yordamida izohlang. U tez-tez duch keladigan vaziyatlarni misol qilib, bunday paytlarda qanday munosabat bildirish mumkinligi haqida suhbatlashing. Masalan: “Kecha ukang mashinasi bilan o‘ynashingga ruxsat bermagani uchun xafa bo‘lganding. Shunday vaziyatda yana nima qilishing mumkin?” Farzandingiz o‘z his-tuyg‘ulari haqida gapira boshlaganida, uni albatta maqtang. Hislarimiz haqida gapirish tabiiy ekanini unga o‘z xatti-harakatlaringiz bilan ham ko‘rsatishga harakat qiling.') WHERE id = '89de6ef5-d3a0-485d-a9cf-b3777a44859f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizni yangi yotog‘ida ilk bor uxlatadigan kuni hamma narsa odatdagi tartibda bo‘lishiga e’tibor bering; agar uyquga tayyorgarlik odatlaringiz bo‘lsa, ularni avvalgidek bajaring. Uyqusi kelishi uchun sokin musiqa sadolari ostida u bilan birga kitob o‘qishingiz yoki unga biroz sut ichirishingiz mumkin. Bola uxlashdan 1 soat oldin ovqatlanmasligi va imkon qadar elektron qurilmalardan uzoq turishi kerak. Bolangizning yoniga yotib olmang, buning o‘rniga u sizni bemalol ko‘ra oladigan joyda, bosh tomonida o‘tiring va orqasi yoki boshini ohista silang. Farzandingiz uxlab qolganidan keyin xonadan sekin chiqib ketishingiz mumkin. U sizni har safar chaqirganida yoniga borishingiz yoki oldingizga kelganida uni yana yotog‘iga olib borishingiz kerak. Har gal yoniga borganingizda tinchlantiruvchi ohangda gapiring, hatto unga alla ham aytishingiz mumkin. Vaqt o‘tishi bilan u sizni kamroq chaqira boshlaydi.') WHERE id = 'b6382df9-f84f-4149-b53c-e70310da9e86';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz odamlar orasida diqqat markazida bo‘lganida gapirishdan uyalib, shu kabi tortinchoqlik belgilarini namoyon qilsa, unda ijtimoiy fobiya bo‘lishi mumkin. Uni hech narsaga majburlamang va aslo “qo‘rqoq”, “tortinchoq” yoki “uyatchan” degan so‘zlar bilan tamg‘alamang. Tortinchoqligi davom etsa, unga jahlingiz chiqmasin va bu masalaga ortiqcha urg‘u bermang. Muhitga ko‘nikishi uchun unga vaqt bering. Yangi yoki notanish joyga borishdan oldin farzandingizni bunga tayyorlang. Sizning boshqalar bilan erkin muloqot qilishingiz va bolangizning o‘rniga hayajonlanmasligingiz unga yaxshi namuna bo‘lib, o‘zini erkinroq his qilishiga yordam beradi. Farzandingizga xavfsiz muhitda yangi tajriba orttirish imkonini yarating va asta-sekin gavjumroq joylarga olib boring. Uni ruhlantiring, biroq buni amalga oshirayotganda “Sen uddalaysan, men senga ishonaman!” kabi iboralar bilan unga ko‘tara oladiganidan ortiq mas’uliyat yuklamang.') WHERE id = '6ec92942-7f5e-461d-a62e-0f93076b7c64';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ijodiy drama — bolalarning tajribalariga tayangan holda, guruh ichida muayyan mavzuni improvizatsiya va rolli o‘yin kabi usullar orqali jonlantirishdir. Ijodiy drama bolaning o‘zi, boshqalar va dunyo haqidagi tushunchalarini kengaytiradigan, tasavvurini rivojlantiradigan ajoyib ta’lim vositasidir. Bu guruh bo‘lib bajariladigan faoliyatdir. Bunday mashg‘ulotlar orqali bolalar fikrlash, gapirish, tinglash va tushunish ko‘nikmalarini egallaydilar. Guruh ichidagi muloqot natijasida nutq ko‘nikmalari tabiiy ravishda rivojlanadi. Bola guruhda hamkorlik qilish, baham ko‘rish, hamjihatlik va boshqalarni hurmat qilishni o‘rganadi. Voqealarni boshdan kechiradigan, kuzatadigan va yaratadigan bola ijtimoiy muloqot ko‘nikmalarining poydevorini mustahkamlaydi. O‘z his-tuyg‘ularini erkin ifodalash imkoniga ega bo‘lgani uchun ichki zo‘riqishdan ham xalos bo‘ladi.') WHERE id = '320de852-acf0-404e-a2a3-5e05210f0a3c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu oylarda bolangizning ijtimoiy rivojlanishida ko‘plab o‘zgarishlarni ko‘rishingiz mumkin. Farzandingiz avvalgi yillarga qaraganda ancha mustaqil bo‘lib qolgan. U kattalarning yordamiga kamroq ehtiyoj sezadi. Hazil tuyg‘usi shakllana boshlaydi va yaqin do‘stlari paydo bo‘ladi. Turli obrazlarga kirib o‘ynaladigan o‘yinlarni tengdoshlari bilan soatlab o‘ynashdan zavqlanadi. Ba’zan istaklari bir-biriga zid kelganida bolalar o‘rtasida tortishuvlar yuz berishi mumkin, ammo bu tabiiy holat. Baham ko‘rish, navbat kutish va hamkorlik qilish tushunchalari bu davrda jadal rivojlanadi.') WHERE id = '0b8e47f0-43bb-47d3-8d35-fa6211dcea40';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Butun oila bo‘lib o‘ynashingiz mumkin bo‘lgan o‘yinni taklif qilamiz! O‘yinni boshlash uchun biror rangni tanlang. Farzandingizga "ranglar bazmi" o‘tkazishingizni ayting va o‘sha rangdagi kiyimlarni kiying. Keyin uyda tanlangan rangdagi buyumlarni qidirishga chiqing. Oilaning barcha a’zolari belgilangan vaqt ichida shu rangdagi buyumlarni topib, bir joyga to‘plashlari kerak. Vaqt tugagach, har kim topgan buyumlarini sanasin. Eng ko‘p buyum topgan kishi yoki guruh g‘olib bo‘ladi. Vaqtingizni maroqli o‘tkazishingizni tilaymiz!') WHERE id = '361e8279-e73c-4364-8803-b9d9b51e4324';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizdan barcha sohada yuqori natijalarni kutish unda jiddiy xavotir va bezovtalikni keltirib chiqaradi. Unutmang, eng muhimi — farzandingiz shug‘ullanayotgan mashg‘ulotidan zavq olishidir. Ba’zan ota-onalar farzandlarini boshqalar bilan taqqoslayotganiga guvoh bo‘lamiz. Bunday vaziyatda bola na qilayotgan ishidan zavq oladi, na oilasini mamnun qila olayotganini his qiladi. Farzandingizning barcha sohada mukammal bo‘lishini istash haqiqatga mos kutish emas. Har bir bolaning o‘ziga xos dunyosi va "rangi" bor; ota-onalar va o‘qituvchilarning vazifasi ana shu o‘ziga xoslikni kashf etishdir. Vaqt o‘tishi bilan bola o‘zini yaxshiroq anglab, unga imkoniyatlar yaratilgan sari, tabiiy ravishda o‘z qiziqishlariga mos yo‘nalishlarni tanlayotganini ko‘rasiz.') WHERE id = '6f5f0110-056b-4dc9-95c9-abd1628f7493';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz gapira olgani uchun endi o‘yinchoqlarni birgalikda tanlashingiz mumkin. Uning aqliy rivojlanishiga yordam beradigan o‘yinchoqlar bilan birga (pazllar, legolar, moslashtirish kartochkalari va boshqalar), jismoniy rivojlanishini qo‘llab-quvvatlaydigan o‘yinchoqlarni ham (to‘p, kichik bouling to‘plami, velosiped, o‘yin xamiri va boshqalar) xarid qilishingiz mumkin. Shuningdek, uning qiziqishlariga mos ta’mirlash asboblari to‘plami, shifokor to‘plami yoki hayvon shakllari kabi qiziqarli variantlarni tanlashingiz mumkin. 4 yosh maktabgacha bo‘lgan davr hisoblangani uchun sopol buyumlarni bo‘yash, munchoq terish, musiqa asboblari va sodda konstruktorlar ko‘proq tavsiya etiladi. Bir necha kishi bilan o‘ynaladigan o‘yinlar (dart, basketbol savati va boshqalar) bola uchun qiziqarli yangilik bo‘ladi. Oilaviy stol o‘yinlariga ham vaqt ajratishingiz tavsiya etiladi; bu bolaga qoidalarga rioya qilish, baham ko‘rish va boshqalarni hurmat qilishni o‘rgatadi.') WHERE id = '395f9c40-970b-4110-a92d-ee8b61745023';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bola va texnologiya munosabatida eng muhim masala — kontentdir. Urush va jangovar o‘yinlar kabi zo‘ravonlik aks etgan kontentlardan, jinsidan qat’i nazar, maktabgacha yoshdagi bolalarni mutlaqo uzoq tutish kerak. O‘yin yoki video qaysi yosh toifasi uchun mo‘ljallanganiga alohida e’tibor berishingiz lozim. Bola bu kontentni tushunayotgandek ko‘rinsa-da, aslida undagi unsurlar uning idrok etish darajasidan yuqori bo‘ladi. Zo‘ravonlik aks etgan kontent bolaning ruhiyatiga salbiy ta’sir ko‘rsatishi mumkin, chunki u ko‘rganlarini hali to‘liq anglay olmaydi.') WHERE id = '5bc28c8f-5d2f-46f3-b3e0-13090b0518ec';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bugungi kunda tez sur’atlarda ko‘payib borayotgan surunkali kasalliklarning asosiy sabablaridan biri bolalik va o‘smirlik davridagi nosog‘lom ovqatlanish tufayli yuzaga keladigan ortiqcha vazndir. Maktablardagi sog‘lom ovqatlanish dasturlari farzandingizning ham jismoniy rivojlanishi, ham darslarni o‘zlashtirish qobiliyatiga samarali ta’sir ko‘rsatadi. Bu davrda bolaga singdirilgan sog‘lom va muvozanatli ovqatlanish odatlari voyaga yetganida ham saqlanib qoladi. Farzandingizda to‘g‘ri ovqatlanish odatlarini shakllantirish uchun, agar maktabda ovqat berilsa, taomnomani kuzatib boring. U bilan har kuni maktabda nima yegani haqida suhbatlashing va taomlar haqida ma’lumot bering. Bolaning qaysi mahsulotlarga moyilligi albatta kuzatilishi kerak. Unga foydali va zararli oziq-ovqatlar haqida tushuntiring, o‘zi yoqtirmaydigan foydali mahsulotlarni esa unga ma’qul bo‘ladigan shaklda taqdim eting.') WHERE id = '9f6d0d64-8534-4e87-96a0-bb91788dbecf';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Muammolarni hal qilishga qodir ekanini his qiladigan bolaning o‘ziga ishonchi yuqori va o‘zi haqidagi tasavvuri ijobiy bo‘ladi. Farzandingizni muammolarni hal qilishga intiladigan inson qilib tarbiyalash uchun unga murakkab vaziyatlar insonni kuchaytiradigan imkoniyat ekanini ko‘rsatishingiz mumkin. Muammolarga qanday munosabatda bo‘lishingiz farzandingiz uchun namuna ekanini unutmang. Muammosiz hayot bo‘lishi mumkin emas, shu sababli qiyinchiliklarga duch kelganda xavotirlanish, stressga tushish yoki shikoyat qilish o‘rniga samarali yechimlar topishga e’tibor qarating. Farzandingiz tengdoshlari bilan tez-tez birga bo‘lsin, shunda u turli muammoli vaziyatlarga duch keladi. Shu tariqa u tengdoshlarining turli yechim usullarini kuzatib, sizning yo‘l-yo‘riqlaringiz yordamida to‘g‘ri va noto‘g‘ri usullarni farqlashni o‘rganadi. O‘zini tayyor his qilganida esa muammolarini mustaqil hal qilish uchun qadam tashlaydi.') WHERE id = '8e3ea6cd-c010-4704-bb9d-bc67237f7778';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'O‘yin farzandingiz hayotida shunchalik muhim ekan, uni o‘yinchoq do‘konlaridan uzoq tutmang. Muayyan qoidalarni belgilab, ularning sababini tushuntirsangiz hamda muloyim, ammo qat’iy bo‘lsangiz, o‘yinchoq do‘koniga borish dahshatli sinovga aylanmaydi. Bu bolani televizor yoki kompyuter qarshisida ushlab turishdan ko‘ra yaxshiroq tanlovdir. Hatto o‘yinchoqlarni birgalikda tanlang. Albatta, sizning yo‘l-yo‘riq ko‘rsatishingiz muhim, chunki o‘yinchoqlar tasodifiy tanlanmasligi kerak. Ular bolaning yoshiga mos bo‘lishi lozim (ko‘plab o‘yinchoqlarda qaysi yosh uchun mo‘ljallangani ko‘rsatiladi). Bundan tashqari, to‘pponcha, miltiq va qilich kabi zo‘ravonlikni targ‘ib qiladigan o‘yinchoqlarni tanlamagan ma’qul.') WHERE id = '45bdf144-6065-4fb2-a745-392e89e7fa6e';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabgacha yoshdagi san’at ta’limi chaqalog‘ingizning ruhiy rivojlanishiga ijobiy ta’sir ko‘rsatadi. San’at orqali farzandingizga yaxshilik, to‘g‘rilik va go‘zallikni anglatib, uning ijtimoiylashuv yo‘lida katta qadamlar tashlashiga yordam berishingiz mumkin. San’at ta’limi orqali ma’naviy qoniqishga erishgan bola ham sog‘lom ruhiy rivojlanish, ham mustahkam xarakterga ega bo‘lish imkoniyatini qo‘lga kiritadi. Bu davrdagi san’at mashg‘ulotlari chaqalog‘ingizda boshqa bolalar bilan ahil va baxtli yashash ko‘nikmasini shakllantiradi. Bu farzandingizning hayotni anglash va talqin qilish qobiliyatini, ijodkorligi hamda tafakkurini rivojlantirishda juda samaralidir. Boy san’at ta’limini olgan bolalarning estetik tushunchasi va qobiliyatlari rivojlanadi, shuningdek, ular duch keladigan muammolarning sabablarini tushunishi osonlashadi. San’at orqali bola tabiat va inson o‘rtasidagi bog‘liqlikni anglaydi, hayotning rang-barangligini ko‘rib, o‘ziga xos ijodiy tafakkuri bilan kelajakdagi intellektual rivoji uchun zamin yaratadi.') WHERE id = 'a4e9140d-14c0-4a81-91a1-6495e44a4c8b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bir nechta katta quti, eski adyol yoki choyshab yordamida shahar, kosmik kema yoxud sirk maydonchasini qurishingiz mumkin. Uy ichida yoki hovlida biror joyni bo‘shating. Eski adyol va yopqichlarni to‘plang. Chodirga o‘xshash inshootlar yasash uchun ustini yopish mumkin bo‘lgan divan, arg‘imchoq yoki bog‘ mebelining suyanchiq yostiqlaridan foydalaning. Agar foydalanayotgan buyumlaringiz matodan bo‘lsa, yopqichlarni mahkamlashda to‘g‘nag‘ichlar yordam beradi. Hatto yopqichlarning chetlarini kesib, ularni ip yoki tasma bilan bir-biriga bog‘lab, yanada mustahkam "qal’a" yasashingiz mumkin. Shu usulda farzandingiz bilan birga qiziqarli o‘yin maydonchalarini yaratib, birgalikda o‘tkazgan vaqtingizdan zavqlanishingiz mumkin.') WHERE id = '7549a661-8c38-4421-b89c-b22ed99e82d2';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda bolalar jamiyatda "qizlarga xos xatti-harakat" yoki "o‘g‘il bolalarga xos xatti-harakat" deb qabul qilinadigan qoliplarga mutlaqo zid ish tutishlari mumkin. Masalan, o‘g‘il bolalar yubka kiyishni, qizlar esa mashinalar bilan o‘ynashni xohlashi mumkin. Bunday istaklar mutlaqo tabiiy bo‘lib, ko‘pincha sizning aralashuvingizdan qat’i nazar o‘zgarmaydi. Eng muhimi, qarama-qarshi jinsga xos xatti-harakatlarga taqlid qilib, aslida o‘z imkoniyatlari chegarasini o‘rganishga urinayotgan chaqalog‘ingizni cheklamang va unga qattiqqo‘l munosabatda bo‘lmang. Gender o‘zligini sinab ko‘rish holatlari aksariyat bolalarda vaqt o‘tishi bilan kamayadi. Hatto bu bosqichdan keyin bolalar faqat o‘z jinsidagi tengdoshlari bilan o‘ynaydigan nisbatan konservativ davrga o‘tadilar. Qisqacha aytganda, maktabgacha yoshda farzandingizning gender o‘zligini o‘rganishga qaratilgan xatti-harakatlaridan qo‘rqish kerak emas; yoshi ulg‘aygani sari bu qiziqish o‘z-o‘zidan yo‘qoladi.') WHERE id = 'a65af59e-6078-49d9-b24e-e31adb692908';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning tana koordinatsiyasi qanchalik yaxshi bo‘lsa, qo‘l ko‘nikmalari ham shunchalik yaxshi rivojlangan bo‘lishi ehtimoli yuqori. Shu sababli tana koordinatsiyasini ta’minlaydigan yirik motorika ko‘nikmalarini rivojlantirish katta ahamiyatga ega. Yirik motorikani rivojlantirish uchun birinchi tavsiya — farzandingizga park yoki bog‘chada o‘ynash, yugurish, tirmashish va sakrash uchun sharoit hamda imkoniyat yaratishdir. Unga velosiped, skuter, rolikli konki va skeytbord kabi muvozanatni rivojlantiradigan vositalardan foydalanish imkonini berishingiz mumkin. U bir oyoqda turish, bir oyoqda turgan holda yerdagi biror buyumni olish, to‘g‘ri chiziq bo‘ylab yurish, orqaga yurish, oyoq uchida yurish va arqonda sakrash kabi mashqlarni bajarishi mumkin. Voleybol va basketbol kabi harakatlanayotgan to‘p bilan muvofiqlashgan harakatlarni talab qiladigan o‘yinlarni ham o‘ynash mumkin. Oldinga va orqaga umbaloq oshish ham yirik motorikaning rivojlanishiga yordam beradi. O‘yinchoqlarni yig‘ishtirish jarayonini qiziqarli o‘yinga aylantirib, farzandingizdan qo‘llari o‘rniga yalangoyoq oyoqlaridan foydalanishini so‘rashingiz mumkin.') WHERE id = '726e9d06-259a-400d-a7f5-6b490b91ea18';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandlarimizni jamiyatdan ajratilgan muhitda ulg‘aytira olmaganimiz uchun tez-tez uchraydigan kasalliklarni bilish va ularga qarshi qanday oddiy choralar ko‘rish mumkinligini o‘rganish foydalidir. Gripp epidemiyasi ko‘pincha maktab yoshidagi bolalar orasida kuzatilgani sababli grippga qarshi emlash ayniqsa tavsiya etiladi. Grippni davolashda antibiotiklardan foydalanilmaydi. Ko‘p suyuqlik ichish, dam olish va burun bitishini kamaytirish uchun fiziologik eritmadan foydalanish tavsiya etiladi. Shamollash esa grippga qaraganda yengilroq kechadi. Ko‘pincha burundan quyuq ajralma keladi. Uni davolash grippdagidek bo‘lib, antibiotiklarni talab qilmaydi.') WHERE id = '6412b307-c910-4c3a-9e90-d2cf441a49d0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz uchun tushlik tayyorlayotganda yorqin rangli sabzavotlarga ko‘proq e’tibor berishingiz mumkin: brokkoli, pomidor, qalampir, sabzi va boshqalar. Sog‘lom tushlik tarkibida oqsil, meva va don mahsulotlari ham bo‘lishi kerak. Meva sharbati o‘rniga mevaning o‘zini tanlang. Shunda farzandingiz meva po‘stini ham iste’mol qilib, qo‘shimcha vitaminlar oladi. Agar u tushlikni mustaqil tanlab yesa, unga tarkibida tuz va yog‘ ko‘p bo‘lmagan sog‘lom mahsulotlarni tanlashni o‘rgatishingiz kerak. Tushlikka chaqirganingizda farzandingizdan “To‘qman” degan javobni eshitishingiz mumkin. Bunday paytlarda hatto kichik porsiya ham farzandingiz zarur vitamin va minerallarni olishi uchun yetarli bo‘ladi.') WHERE id = '513df970-25cf-4dca-baaf-582abc429420';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Yuqumli kasalliklarga qarshi shaxsiy gigiyena qoidalariga rioya qilish ko‘plab kasalliklarning oldini oladi. Qo‘l gigiyenasi mikroorganizmlar keltirib chiqaradigan infeksiyalarning oldini olishning eng samarali usulidir. Tadqiqotlar shuni ko‘rsatadiki, qo‘llarni shunchaki to‘g‘ri yuvishning o‘zi bolalarni ko‘plab yuqumli kasalliklardan himoya qiladi. Faqat sovundan foydalanish va qo‘l gigiyenasi bo‘yicha berilgan ta’lim teri infeksiyalarini 34%, diareya bilan kechadigan kasalliklarni 55%, pnevmoniyani esa 50% kamaytirishi kuzatilgan. Shu bilan birga, bu kasallik davomiyligini ham qisqartiradi. Farzandingizda har safar ovqatlanishdan oldin va keyin, ko‘chadan kelganda hamda hojatxonadan chiqqach qo‘l yuvish odatini shakllantirishingiz kerak. Unga qo‘llarini mustaqil yuvishga ruxsat bering, ayni paytda suvni isrof qilmasligiga ham e’tibor qarating.') WHERE id = '63c0a769-d0da-451c-88a4-2461e95014c4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ba’zan bolalar ilgari bunday muammoga duch kelmagan bo‘lsalar-da, to‘satdan tagini ho‘llay boshlaydilar. Ya’ni uzoq vaqt davomida tagi quruq bo‘lganidan keyin bu muammo yana paydo bo‘ladi. Agar buning sababi fiziologik bo‘lmasa, bola e’tiborni jalb qilishni istayotgani sabab bo‘lishi mumkin. Ayniqsa, hayotidagi biror o‘zgarish tufayli ota-onasidan avvalgidek e’tibor ko‘rmayotgan yoki e’tiborsiz qolishdan xavotirlanayotgan bolalar e’tiborni o‘zlariga qaratish uchun shunday qilishlari mumkin. Ba’zan ular buni anglagan holda, ba’zan esa beixtiyor tagini ho‘llay boshlaydi. Farzandingiz bu yo‘l bilan sizga qanday xabar yetkazmoqchi ekanini (menga e’tibor bermayapsiz, yangi maktabim menga yoqmadi, nega mening ikkita uyim bor, qo‘shnining itidan juda qo‘rqaman va boshqalar) tushunishingiz kerak. Shunga muvofiq, farzandingizni qo‘llab-quvvatlaydigan va uning xavotirlarini kamaytiradigan suhbat o‘tkazishingiz, albatta, yordam beradi.') WHERE id = '7891d564-4371-4763-ac8c-ce9411e6d6b6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bilan yaqin munosabat o‘rnatish uchun bola kabi fikrlay olishingiz kerak. Uning yoshida bo‘lganingizda nimalarni yoqtirganingiz, nimalarni yoqtirmaganingiz va boshingizdan qanday voqealar o‘tganini eslashga harakat qiling. Bu sizga farzandingiz bilan qanday yaqinlashish mumkinligi haqida tushuncha beradi. Uning o‘yinchoqlari va o‘yinlaridan qaysilari sizga yoqishini aniqlang. Farzandingizni diqqat bilan tinglang, uning qilayotgan ishlari va aytayotgan gaplariga e’tibor bering. O‘zi so‘ramaguncha biror ishni qanday bajarishni ko‘rsatmang, yordam so‘ramaguncha esa uning o‘rniga ishni bajarib qo‘ymang. Farzandingiz bilan mustahkam rishta o‘rnatish uning hayotdan zavq olishi va o‘ziga ishonadigan inson bo‘lib ulg‘ayishi uchun juda muhimdir.') WHERE id = '95abd014-39f4-4997-bebe-7dc583d1e9d6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabgacha bo‘lgan davrda kompyuter va televizor qarshisida o‘tkaziladigan umumiy vaqt 45 daqiqadan oshmasligini nazorat qiling. 4-9 yoshli bolalarda multfilm qahramonlariga taqlid qilish moyilligi yuqori bo‘lgani uchun, avval bu multfilmlarni o‘zingiz tomosha qiling va mazmuni mos bo‘lsa, bolangizga ko‘rsating. U qaysi multfilmlarga qiziqishini kuzating. Ulardagi zo‘ravonlik va voqealar haqida u bilan suhbatlashing. Bunday xatti-harakatlar haqiqiy hayotda og‘riqli bo‘lishi va qanday muammolarga olib kelishi mumkinligini muhokama qiling. Tajovuzkorlik multfilmlardagidek "oson" emasligini, u qayg‘u va tuzatib bo‘lmaydigan oqibatlarga sabab bo‘lishi mumkinligini tushuntiring. Multfilmlardagi muammolar uchun birgalikda muqobil va tinch yo‘l bilan hal etish usullarini topishga harakat qiling.') WHERE id = '5f57fd0b-030a-4208-a0d6-e6c994ab83de';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning tildan foydalanishni o‘rganishi uning rivojlanishidagi eng muhim ko‘rsatkichlardan biridir. Dastlabki davrlarda gapirishiga ko‘maklashish, turli vositalar bilan ta’minlangan qulay muhit yaratish va qiziqarli mashg‘ulotlar tashkil etish nutq rivojlanishini rag‘batlantiradi. Chaqalog‘ingizning nutq rivojlanishiga ta’sir qilishi mumkin bo‘lgan sog‘liq muammolarini albatta shifokor nazorati ostida davolating. Uning so‘z boyligini oshiring, chunki so‘z boyligi keng bolalar aqliy rivojlanishda muvaffaqiyatliroq bo‘lishi ma’lum. Chaqalog‘ingiz uchun yaxshi suhbatdosh bo‘ling, u bilan ko‘p va e’tibor bilan suhbatlashing. Uning ekran qarshisida cheklanmagan vaqt o‘tkazishiga yo‘l qo‘ymang. Ayniqsa, dastlabki to‘rt yoshda televizorni uzoq vaqt tomosha qilish nutq rivojlanishiga salbiy ta’sir ko‘rsatishi ma’lum. Uni tez aytishlar, topishmoqlar va qo‘shiqlar o‘rganishga undang.') WHERE id = '695f2126-31cf-4126-8efd-18188b066023';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yoshdagi bolaning rasm chizish va tasviriy faoliyat ko‘nikmalari ancha rivojlangan bo‘ladi. U endi qo‘llari, oyoqlari va boshi bor "tayoqcha odamlar"ni chiza oladi. Chizgan rasmlarida kattalar tushunib, taniy oladigan obyektlar tasvirlanadi. Qog‘ozlarni qirqish, yopishtirish va bo‘yash orqali turli qo‘l mehnati buyumlarini yarata oladi. Boshqa rasmga qarab, uning aynan o‘xshashini chizishga harakat qiladi. X, V, H, T, O kabi oddiy belgilarni namunaga qarab chizadi. To‘rtta asosiy rang va oddiy geometrik shakllarni taniydi, ularni moslashtiradi hamda so‘ralganda nomlarini aytadi.') WHERE id = '611641cd-aa10-4e5b-8d69-e8204d31ef3b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz qornining chap pastki qismida to‘satdan og‘riq boshlangan bo‘lsa, bunga ichakdagi gaz sabab bo‘lishi mumkin. Avval uni hojatxonaga yuborib, gaz chiqarishiga imkon bering. Agar og‘riq o‘tib ketsa, shifokorga murojaat qilmasdan holatini kuzatishingiz mumkin; buning uchun hojatga muntazam chiqish odatini shakllantirish kifoya. Ammo qorin og‘rig‘i bilan birga qusish boshlansa yoki qornining o‘ng pastki qismidagi og‘riq ishtahasizlik bilan kechsa, bu appenditsit bo‘lishi mumkin. Qorin og‘riganda shifokor tavsiyasisiz aslo og‘riq qoldiruvchi dori bermang, chunki bu kasallikni erta aniqlashga xalaqit berishi mumkin. Chaqalog‘ingiz sariq-yashil rangda qusayotgan bo‘lsa, bu jiddiy kasallik alomati bo‘lishi mumkin.') WHERE id = 'ae78e1ed-f739-4d46-afb0-6ad241013fa8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bilan o‘ynaganda o‘yinni imkon qadar siz boshlamaslikka va boshqarmaslikka harakat qiling. Faqat u xursand bo‘lsin deb o‘yinlarda ataylab yutqazmang, halol bo‘ling. Natijani emas, uning sa’y-harakatini qadrlang: “Juda yaxshi bajarding” deyish o‘rniga “Buni bajarish uchun haqiqatan ham juda ko‘p harakat qilding” jumlasini tez-tez ishlating; shunda u biror narsani uddalay olmaganida ham uni ruhlantira olasiz. Qoidalarga hamma amal qilishini ta’minlang: qoidalarni o‘zgartirish mumkin, ammo ular qo‘llanilsa, hamma uchun bir xil bo‘lishi kerak. Uning o‘yin sherigi bo‘lishingiz zarur paytda chegara qo‘yishingizga to‘sqinlik qilmaydi. Agar u nomaqbul xatti-harakat qilsa, uni to‘xtating. Har kuni kamida yarim soatingizni faqat u bilan o‘ynashga ajrating.') WHERE id = '3d6d5afc-b0b7-45af-a0ab-f196aaca2127';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu davrda chaqalog‘ingiz o‘z tanasi va qarama-qarshi jins vakillarining tanasiga qiziqib, savollar beradi. U qiz va o‘g‘il bola bo‘lish o‘rtasidagi farqlarni bilishni xohlaydi. Jinsiy rivojlanish mavzularida suhbatlashish siz uchun taqiqlangan mavzu bo‘lmasligi, aksincha, bu haqda bemalol gaplasha olishingiz kerak. Chaqalog‘ingizga shaxsiy chegaralarini o‘rgatish juda muhim. Unga intim a’zolariga faqat o‘zi tegishi mumkinligini va boshqalar oldida bu joylari yopiq turishi kerakligini tushuntiring. Agar kimdir unga nisbatan shunday xatti-harakat qilsa, bu haqda darhol sizga aytishi kerakligini bildiring. Bu mavzularda gaplashganda baqirmaslik yoki koyimaslik, balki odatdagi, tabiiy suhbat ohangida so‘zlashish muhim.') WHERE id = '614d55f8-67cd-4224-a622-14041bad2022';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi ijtimoiy faoliyatlardan zavqlanadigan va jamiyat qoidalariga moslashish qobiliyati oshib borayotgan farzandingiz bilan bolalar teatrlariga yoki musiqali tomoshalarga borishni boshlashingiz mumkin. Bu uning yoshligidanoq madaniy tadbirlarga qiziqishiga, shuningdek, ushbu tomoshalar orqali yangi qadriyatlarni o‘zlashtirishiga yordam beradi. Bundan tashqari, birgalikda kitob do‘konlarini aylanib chiqish ham juda qiziqarli bo‘lishi mumkin. Bu davrda yirik shriftlarda chop etilgan ensiklopediyalar uning e’tiborini tortadi. Tarix, san’at va madaniyat mavzularini qamrab olgan ensiklopediyalarni xarid qilishdan tortinmang. Hatto birgalikda mutolaa qilish va rasmlarni tomosha qilish ham uning qiziqishini oshiradi. Shu yoshda farzandingizda madaniyatga qanchalik ko‘p qiziqish uyg‘otsangiz, bu kelajakda shunchalik ijobiy natija beradi.') WHERE id = '50a2dfe1-2ca8-419f-a0a0-d061a2e569b7';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda diqqatning tarqoqligi yoki yetishmovchiligi turli belgilar bilan namoyon bo‘lishi mumkin. Ulardan eng birinchisi — ota-ona yoki o‘qituvchi bergan ko‘rsatmalarga rioya qilishda qiynalishdir. Darsda zerikkandek yoki qiziqmayotgandek ko‘rinish, xayol surish va unutuvchanlikka moyillik kuzatilishi mumkin. Uyda va maktabda buyumlarini yo‘qotish, oddiy xatolarga yo‘l qo‘yish, maktab partasi yoki javonining tartibsizligi, ijtimoiy munosabatlardagi qiyinchiliklar ham ushbu belgilar qatoriga kiradi. Agar farzandingizda shunday holatlarni ko‘rsangiz, sababini aniqlash uchun shifokorga murojaat qilishingiz kerak. Chunki bunday xatti-harakatlarni namoyon qiladigan har bir bolaga bir xil tashxis qo‘yib bo‘lmaydi. Bolada ko‘proq "diqqatsiz tip" belgilari kuzatilgan taqdirda ham, bu buzilishning sababi nevrologik bo‘lishi mumkinligi uchun mutaxassis xulosasi albatta zarur.') WHERE id = 'fc9707a2-8033-42a0-a859-2dccd4c84f58';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshli farzandingiz endi oilada uning fikri tinglanishi muhim deb hisoblaydi. Ayrim masalalarda uning ham fikrini so‘rash va nima uchun bunday o‘ylashiga qiziqish unga oilada qadrlanishini his qildiradi hamda o‘ziga bo‘lgan ishonchini oshiradi. Bu, shuningdek, fikr yuritish, muhokama qilish va xatolarini baholash kabi yuqori darajadagi tafakkur ko‘nikmalarining rivojlanishiga yordam beradi. Farzandingiz tengdoshlari bilan birga bo‘lganida, muammolarini gaplashib, mustaqil hal qilishiga imkon bering. Keyinchalik bu muammolarni qanday hal qilgani haqida oila davrasida suhbatlashishingiz mumkin. Oiladagi muloqot juda qadrlidir; tez-tez birga yig‘ilib suhbatlashish oilaviy rishtalaringizni yanada mustahkamlaydi.') WHERE id = '1e12d6d2-62b1-4db3-a264-b793ae07104a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda vaqt tushunchasi, asosan, 4 yosh atrofida shakllana boshlaydi. Albatta, bu kattalar tushunadigan taqvim tushunchasi bilan bir xil emas. Masalan, farzandingiz bugun yakshanba ekanini bilishi mumkin, ammo bu kecha shanba bo‘lganini, ertaga esa dushanba bo‘lishini yoki bugungi aniq sanani biladi degani emas. U shunchaki otasi uyda bo‘lgani uchun bugun yakshanba deb o‘ylashi mumkin. Xuddi shuningdek, 4 yoshda ekanini bilishi 3 yoshli bola undan kichikroq ekanini to‘liq tushunishini anglatmaydi. U yoshini tez-tez takrorlagani uchun biladi, biroq undan ''5 yoshda bo‘lish nimani anglatadi?'' deb so‘rasangiz, ehtimol, shunchaki 5 yoshda ekanini yana bir bor takrorlaydi.') WHERE id = '692f9786-05ee-4a06-925c-e91c4c28f381';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Rivojlanish davrida bolalarning aqliy, jismoniy va ijtimoiy-hissiy rivojlanishini qo‘llab-quvvatlaydigan, ijodkorlik va fikrlash qobiliyatlarini boyitadigan eng muhim vositalar o‘yin va o‘yinchoqlardir. 4 yoshli bolalar uchun eng asosiy ehtiyoj, albatta, birga o‘ynaydigan tengdoshdir. Shu sababli farzandingizning tengdoshlari bilan vaqt o‘tkazishi juda muhim. Har qanday yoshda bo‘lgani kabi, hissiy jihatdan shifobaxsh ta’siri hamda tarbiyaviy ahamiyati eng yuqori bo‘lgan o‘yin vositalari suv, qum va loydir. Bundan tashqari, turli xomashyo va chiqindi materiallardan foydalanib, farzandingizga yangi buyumlar yaratishi va kashf qilishni o‘rganishi uchun sharoit yaratishingiz mumkin. Bunday materiallar bilan o‘ynash tengdoshlari bilan birga bo‘lganda yanada qiziqarli kechadi. Kattalar aralashuvisiz tayyorlagan ishlarini namoyish etish unga katta faxr tuyg‘usini baxsh etadi.') WHERE id = 'd24de719-13dc-42c4-a222-71b09555098c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingizda diqqat yetishmovchiligi bo‘lsa, qo‘lingizdan keladigan eng muhim ish — unga diqqat tarqoqligi ko‘pchilikda uchrashini va bundan uyalish kerak emasligini tushuntirishdir. Farzandingizga: “Diqqatingni jamlashga harakat qilayotganingni bilaman, yaxshiroq diqqatni jamlashingga nima yordam beradi deb o‘ylaysan?” yoki “Nimalar diqqatingni chalg‘itadi?” kabi savollarni berib, ko‘p narsaga oydinlik kiritishingiz mumkin. “Maktabda yoki uyda bo‘lganingda seni bezovta qiladigan biror narsa bormi?” deb so‘rash orqali diqqat tarqoqligining sababi xavotir ekaniga oid belgilarni aniqlashingiz mumkin. Farzandingizga ketma-ket juda ko‘p topshiriq bermang, chunki diqqati tarqoq bola ularning barchasini eslab qola olmasligi mumkin. Buning o‘rniga, ko‘ziga qarab, bir vaqtning o‘zida ko‘pi bilan 2 ta topshiriq bering. Farzandingiz diqqatini jamlashi uchun maxsus vaqt oralig‘ini belgilang. Shunda bola faqat muayyan vaqtda diqqatini jamlashi kerakligini biladi va bu uning uchun osonroq bo‘ladi.') WHERE id = 'b6dbd0d2-966c-469b-a877-20ef3f5d6779';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshli bolalarning bo‘yi o‘sishi bilan birga, yirik va mayda motorikasi ham rivojlanishda davom etadi. Endi u fazoni yaxshiroq idrok etadi va harakatlanayotganda atrofdagi narsalar yoki odamlarga kamroq uriladi. Yugurish qobiliyati yaxshilanadi, oyog‘i bilan to‘pni tepishi va qo‘li bilan otishi mumkin. Zinadan yordamsiz chiqib-tusha oladi, tirmashadi, qisqa vaqt bir oyoqda tura oladi hamda mustaqil kiyinib-yechina oladi. Bu yoshga kelib ko‘z va qo‘l harakatlari muvofiqlashgan bo‘lishi kerak. Shu rivojlanish tufayli u ipga munchoq tizish, pazl yig‘ish va chiziqlar ichini bo‘yash kabi mashg‘ulotlarni bajara oladi. Uchburchak, doira, kvadrat va boshqa shakllardan nusxa ko‘chira oladi, tana qismlari tasvirlangan odam rasmini chizadi, 8-9 ta kubikni ustma-ust qo‘ya oladi.') WHERE id = 'ed367477-46cb-4c06-b9d7-23d99cb4ee19';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Endi farzandingiz suhbatni uzoqroq davom ettira oladi, uning fikrlash jarayonlari rivojlanadi. U oddiy savollarga osonroq va mantiqiy javob bera boshlashi bilan birga, his-tuyg‘ularini ham yaxshiroq ifodalay oladi. Vaqt tushunchasini va kundalik mashg‘ulotlar qachon bajarilishini yaxshiroq anglaydi. Masalan, ertalab nonushta, tushda tushlik, kechqurun esa kechki ovqat yeyilishini biladi. Diqqatini jamlash muddati uzayadi, bajarayotgan ishiga yaxshiroq va uzoqroq e’tibor qarata oladi. Jahli chiqqanini jismoniy harakatlar bilan ko‘rsatish o‘rniga, har doim bo‘lmasa-da, endi so‘z bilan ifodalay boshlaydi. Muammolarni hal qilish borasida ham sezilarli rivojlanadi.') WHERE id = '49c8b800-b882-48a6-9f24-05e4d2f08e6f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshli bolalar odatda 10-20 gacha sanay oladi. Sanash ko‘nikmasini rivojlantirish uchun tashqarida sayr qilayotganda mashinalar, daraxtlar va boshqa narsalarni birgalikda sanashingiz mumkin. Pechenye kabi yeguliklarni yeyayotganda, har biri yeyilgach, nechta qolganini topish o‘yinini o‘ynashingiz mumkin. Ranglar va shakllarni farqlash ko‘nikmasi uchun biror rangni tanlab, bolangizdan uy ichidan shu rangdagi 4-5 ta buyumni topib kelishini so‘rashingiz mumkin. Rangli qalamlarni o‘rtaga qo‘yib, undan har bir rangga bittadan his-tuyg‘uni moslashtirishni, hayotida eng ko‘p his qiladigan tuyg‘ulariga mos ranglar bilan qog‘ozni bo‘yashni yoki shakllar chizishni so‘rang. Keyin chizgan rasmi asosida uning his-tuyg‘ulari haqida suhbatlashishingiz mumkin. Bu mashg‘ulot rang va shakl tushunchasini, shuningdek, his-tuyg‘ularni anglash va o‘zini ifodalash ko‘nikmalarini mustahkamlaydi.') WHERE id = '98e7ba77-79e8-4221-9e64-49ca676c7cd8';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning o‘zini ifodalash qobiliyati va his-tuyg‘ularini boshqarish ko‘nikmasi rivojlangani sari uning keskin munosabati va qaysarligi vaqt o‘tishi bilan kamayib, yo‘qoladi. Biroq bu jarayonda ota-onaning yondashuvi juda katta ahamiyatga ega. Chunki bolalar qiyin vaziyatlarda o‘zini tinchlantirish va to‘g‘ri ifodalashni ota-onasining yordami bilan o‘rganadi. Bunday paytlarda unga biror narsa o‘rgatishga yoki mantiqiy tushuntirishlar berishga urinmang, chunki o‘sha onda bolaning sizni tushunishi odatda qiyin bo‘ladi va bunday yondashuv inqirozni yanada kuchaytirishi mumkin. Agar uydan tashqarida bo‘lsangiz, tarang muhitdan uzoqlashib, imkon qadar tinch joyga o‘tishga harakat qiling. Agar uyda bo‘lsangiz, uning o‘z xonasi kabi tinchlana oladigan joyga o‘ting. Unutmang, farzandingiz eng qayg‘uli va qiynalgan paytlari aslida sizga eng ko‘p muhtoj bo‘ladi. Unda rad etilgani, tushunilmagani va qadrsizligi hissini uyg‘otadigan "jazo gilamchasi" yoki "o‘ylash stuli" kabi usullardan foydalanmang.') WHERE id = 'fb77510f-fdfd-4080-9579-84655a9754fe';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ko‘ngil aynishi va qusish bolalik davrida eng ko‘p uchraydigan shikoyatlardan biridir. Ko‘ngil aynishi qusish bilan kechsa, bu bola uchun juda holdan toydiruvchi bo‘lishi mumkin va tabiiyki, siz vaziyat tezda yaxshilanishini istaysiz. Biroq ko‘pincha o‘z-o‘zidan o‘tib ketadigan bunday holatlarda qo‘llanadigan dorilar har doim ham xavfsiz bo‘lmasligi mumkin. Shu sababli sabrli bo‘lish va albatta shifokoringiz bilan maslahatlashish lozim. Eng muhim masalalardan biri degidratatsiya, ya’ni suvsizlanishdir. Bolalar kattalarga qaraganda tezroq suvsizlanishi mumkin. Bolani suyuqlik ichishga undang. U oz-ozdan, tez-tez suyuqlik ichishi kerak. Kichik porsiyalarda oson hazm bo‘ladigan ovqatlar bering. Qusish kamaygani sari suyuqlik miqdorini oshirishingiz mumkin.') WHERE id = '23ae0863-ca91-425e-9102-2694822c45d5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tengdoshlar bilan o‘ynaladigan o‘yinlar foydaliroqdir. Shu tariqa bolalarning ijtimoiy ko‘nikmalari rivojlanadi. Bolalar tengdoshlari bilan o‘ynash orqali guruhga qo‘shilish, qabul qilinish va o‘zini shu guruhga tegishli his qilish tuyg‘ularini boshdan kechiradi. Shuningdek, o‘yin bolalar hayotni sinab ko‘radigan maydondir. Ba’zan o‘z navbatini kutishiga to‘g‘ri keladi, ba’zan esa hafsalasi pir bo‘lishini yengishni o‘rganadi... Qayta urinib ko‘rishga jur’at topadi, tushkunlikka tushmaydi, maqsadiga erishadi va shu tariqa o‘ziga bo‘lgan hurmati hamda ishonchi ortadi. O‘z his-tuyg‘ularini ifodalaydi, boshqalarning tuyg‘ularini tushunadi va hamdardlik ko‘rsatishni o‘rganadi. Siz uning eng yaxshi o‘yin sherigi ekaningizni bilamiz, ammo turli muhitlarda yangi do‘stlar orttirish ham u uchun juda qiziqarli bo‘ladi. :)') WHERE id = 'cd983b90-05fa-4d49-84f1-0ca9941425d4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshli farzandingiz do‘stlariga o‘xshashni xohlaydi. Do‘stlari uning fikrlari va xatti-harakatlariga ta’sir qiladi, u ham ularga o‘xshashga intiladi. Boshqa oilalarda qadriyatlar va qoidalar boshqacha ekanini bilib olgach, bu yangi ma’lumotlarni uyda ayrim narsalarni talab qilish orqali sinab ko‘radi. Masalan, taqiqlangan ko‘rsatuvlarni tomosha qilishni yoki o‘z uyida ruxsat berilmaydigan mahsulotlarni iste’mol qilishni xohlashi mumkin. 4 yoshli bolalar uchun do‘stlari o‘zgacha turmush tarzi va xatti-harakatlarning namunasidir. Farzandingiz oilasi, o‘yinchoqlari va uyini ko‘rsatish uchun do‘stlarini mehmonga taklif qiladi. Ularni xursand qilishga intiladi va shunga mos ravishda yangi xatti-harakatlarni namoyon etadi. Do‘stlariga juda katta ahamiyat beradi va yolg‘iz qolishni aslo yoqtirmaydi.') WHERE id = '8d3e994b-abbd-4e43-bcfa-877fe6b1fa96';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshga yaqinlashgan sari farzandingizda oddiy axloqiy tushunchalar shakllanadi. U yaxshilik va yomonlik tushunchalarini anglashga harakat qiladi. Ota-onasini xursand qilish va jazodan qochish uchun qoidalarga qat’iy amal qiladi. Uning uchun oqibatlar hamma narsadan muhimroq. Qimmatbaho buyumni sindirib qo‘ysa, bu tasodifan yuz bergan bo‘lsa ham, o‘zini yomon deb hisoblaydi. Unga tasodifan qilingan harakat bilan qasddan qilingan yomon xatti-harakat o‘rtasidagi farqni tushunishga yordam berishingiz kerak. Shunda u qilgan ishlari uchun o‘zini ayblab, ichiga yutib yurmaydi.') WHERE id = 'd503315a-9bc7-4dae-b063-882f785b1c35';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz bu davrda goh talabchan, goh hamkorlik qilishga moyil bo‘lishi mumkin. U kutilmagan hissiy reaksiyalarini endi boshqara oladi, ammo norozilik va qarshilik ko‘rsatish tuyg‘ularini jilovlashda hali ham qiynaladi. Oilaviy qoidalarga bo‘ysunmasligi, onasini yoki enagasini bezovta qilish uchun ataylab qo‘pol gapirishi va sho‘xlik qilishi mumkin. Kichik yoshdagi chegaralarni sinab ko‘rishdan farqli ravishda, bu davrdagi nomaqbul xatti-harakatlar ongliroq ravishda amalga oshiriladi. Bu o‘zgarishlarga qaramay, farzandingiz hali ham onasini yoki unga qaraydigan kishini xursand qilishga intiladi. Buning uchun muayyan qoidalarga amal qilishi va o‘zini to‘g‘ri tutishi kerakligini tushunadi.') WHERE id = 'aaab67cd-2783-4da3-a197-a84694c06429';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning so‘z boyligini oshirish uchun unga yangi so‘zlarni o‘rganish imkonini yarating. Aka-uka, opa-singillari yoki do‘stlarining ism-familiyalarini, shuningdek, o‘z manzilini o‘rganishiga yordam bering. Unga savollar bering va javoblarni takrorlashini so‘rang. Kun davomida rejalashtirgan ishlaringiz haqida gaplashishingiz mumkin. Masalan: “Ovqatdan keyin nima qilishimiz haqida gaplashgandik, eslaysanmi? Ha, bugun bog‘ga boramiz. Bog‘ga qanday boramiz?” kabi suhbatlar qiling. Avval o‘qigan hikoyangiz haqida savollar berib, xotirasini mustahkamlang. Kitobdagi rasmlarni tomosha qilishiga imkon bering. O‘qish va yozish kundalik hayotda qanchalik muhimligini ko‘rsating. Atrofdagi yozuvlarga (lavhalar, yorliqlar) e’tiborini qarating va ular nima maqsadda yozilganini tushuntiring. Televizorni birga tomosha qiling va ko‘rganlaringiz haqida suhbatlashing. Kitoblarni sevishi uchun uning qo‘li yetadigan balandlikda kitob javoni tashkil qiling. Kitob o‘qish, qo‘shiq kuylash, so‘z o‘yinlarini o‘ynash va bola bilan ko‘p suhbatlashish uning so‘z boyligi rivojlanishiga katta yordam beradi.') WHERE id = '87189795-ea46-436e-8cfa-53184b24452b';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz 4 yoshga qadam qo‘yar ekan, sizni yangi bir bosqich — 4 yosh sindromi kutishi mumkin. Bu davrda bolalar, ayniqsa, o‘z harakatlarida erkinlikni istagani sababli ko‘plab kichik noxush hodisalar yuz berishi mumkin. Bolaning ishlarni mustaqil bajarish istagiga salbiy munosabatda bo‘lish o‘rniga, nazoratingiz ostida mashg‘ulotlar bilan shug‘ullanishi va o‘ynashi uchun sharoit yarating. Chunki faqat shu yo‘l bilan uning harakat ko‘nikmalari va ma’naviy rivojlanishi ijobiy tarzda takomillashishi mumkin. U o‘zini ulg‘aygan deb his qilgani uchun sizga taqlid qila boshlaydi. Natijada oshxona buyumlari bilan o‘ynashga ko‘proq qiziqishi mumkin. Agar farzandingiz o‘g‘il bola bo‘lsa, otasiga taqlid qilib, uning xatti-harakatlarini o‘zlashtiradi. Qiz bola bo‘lsa, e’tibori ko‘proq onasida bo‘ladi. Shuningdek, bu davrda qarama-qarshi jinsdagi tengdoshlari bilan chiqisha olmaslik muammosi ham yuzaga kelishi mumkin.') WHERE id = 'cfed4a34-1a98-42d4-ad49-38a939cc4921';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yoshda farzandingizning uyquga ketishida turli qiyinchiliklarga duch kelishingiz mumkin. Har kecha bir xil vaqtda uxlashiga e’tibor bering va boshqa mashg‘ulotlar uyqu vaqtini buzishiga yo‘l qo‘ymang. Uyqudan oldin muayyan tartib yarating. Tishlarni yuvish, hojatxonaga borish va pijama kiyish kabi odatlarni har kecha bir xil ketma-ketlikda bajaring. Yotoqda yoqimli suhbatlar qiling; kun davomida nimalar qilgani, nimadan eng ko‘p xursand bo‘lgani yoki xafa bo‘lganini so‘rang. Bu farzandingiz bilan orangizda ishonchli muloqot rishtasini yaratadi. Xonasidagi o‘yinchoqlarga e’tibor bering; juda katta yoki uni qo‘rqitishi mumkin bo‘lgan o‘yinchoqlarni bir muddatga olib qo‘yishingiz mumkin. Ota-onasi uyg‘oq bo‘lib, uyda hayot davom etayotgan paytda bolaning yotishi qiyin bo‘lishi mumkin. Shu sababli uyqu tartibini yo‘lga qo‘yishda uy chiroqlarini o‘chirishingiz va o‘zingiz ham uxlashga tayyorlanayotgandek pijamangizni kiyib, uni qo‘llab-quvvatlashingiz mumkin.') WHERE id = '3d6cfe38-d47f-4e23-9455-bc71c0715956';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Kun davomida bolalarning manfaati uchun aytadigan ayrim gaplarimiz aslida salbiy ta’sir ko‘rsatishi mumkinligini bilarmidingiz? Tadqiqotlar shuni ko‘rsatadiki, bola biror ishni bajarganida tez-tez aytiladigan "Barakalla", "Sen zo‘rsan" kabi so‘zlar uning ichki motivatsiyasidan ko‘ra, faqat sizning ma’qullashingizga e’tibor qaratishiga olib keladi. Buning o‘rniga "Rasmda ishlatgan ranglaringning uyg‘unligi menga juda yoqdi" kabi batafsil maqtovlar uning rivojlanishiga yaxshiroq ta’sir qiladi. Shuningdek, biror joyga shoshayotganingizda farzandingizga "Tez bo‘l", "Shoshil" deyish zo‘riqish va yig‘i xurujlariga sabab bo‘lishi mumkin. Zo‘riqish yuzaga kelmasligi uchun vaziyatni o‘yinga aylantiring: "Qani, ko‘ramiz, pishlog‘ini kim birinchi tugatarkin?" kabi yondashuvlar jarayonni maroqli qiladi.') WHERE id = 'ddd0692a-3a59-4255-984a-d8a0b7fa3830';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2-6 yoshdagi bolalar o‘zini markazga qo‘yib fikrlaydi va odatda atrofdagi hamma narsa ularga xizmat qilishini kutadi. Bu davrda farzandingiz boshqalarning fikr va his-tuyg‘ularini inobatga olmasligi mumkin. Bo‘lishishni bilmagani uchun hech kimga o‘yinchoqlari bilan o‘ynashga ruxsat bermasligi mumkin. Hatto o‘z buyumlarini bermasa-da, boshqalarning buyumlariga ega bo‘lishni istashi mumkin. Farzandingizdan birdaniga bo‘lishishni o‘rganishini kutmasligingiz kerak. Bo‘lishish vaqt o‘tishi bilan o‘rganiladigan ko‘nikmadir va buning uchun bolaga vaqt berish lozim. Har bir bola ulg‘ayadigan muhit turlicha bo‘lgani sababli, bu ko‘nikmani egallash muddati ham farq qilishi mumkin.') WHERE id = '30d6a7c7-dd03-4c28-8bfd-4d04e2d06182';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Tadqiqotlar shuni ko‘rsatadiki, televizor ko‘rishga ajratiladigan o‘rtacha vaqt uyqu va maktabdan tashqari barcha boshqa mashg‘ulotlarga sarflanadigan vaqtdan ko‘proq. Televizor qarshisida ko‘p vaqt o‘tkazadigan bolalarda uni kam ko‘radigan bolalarga qaraganda vazn bilan bog‘liq muammolar ko‘proq uchrashi aniqlangan. Shuningdek, ovqatlanish bilan bog‘liq muammolari bor bolalarning aksariyati chaqaloqligida televizor qarshisida ovqatlantirilgani ma’lum bo‘lgan. Reklamalardagi yog‘ va shakar miqdori yuqori mahsulotlar esa bolalarning nosog‘lom ovqatlanishiga sabab bo‘ladi. Televizor nafaqat ovqatlanishga, balki uyqu tartibiga ham salbiy ta’sir qiladi. Uxlashdan oldin televizor ko‘radigan bolalar uxlab qolishga qiynalishi va uyqu sifati past bo‘lishi kuzatiladi. Cheklovlarga rioya qilinishini ta’minlash uchun bolalar xonasidan televizorni olib tashlash juda muhim.') WHERE id = '6c7a6bcb-ff6b-4874-bd17-f84276093048';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ota-ona sifatida farzandingizga yetarlicha vaqt ajrata olmayotganingizni yoki kamchiliklaringiz borligini o‘ylashingiz mumkin. Ammo shuni bilishingiz kerakki, "yetarli" vaqtning aniq formulasi yo‘q. Bu jarayonda farzandingiz bilan o‘tkazgan vaqtingizning miqdori emas, sifati muhim. Farzandingiz bilan vaqtni yanada mazmunli o‘tkazish uchun har ikki tomonga ham yoqadigan mashg‘ulotlarni tanlash lozim. Bolalar odatda yangi o‘yinchoqdan 15-20 daqiqadan keyin zerikadi va unga qiziqishi pasayadi. Ammo siz o‘sha o‘yinchoq bilan birga o‘ynasangiz, bu vaqt qanchalik uzayishini ko‘rasiz. Chunki chaqalog‘ingiz uchun eng muhimi nima bilan o‘ynayotgani emas, ayni damda "siz bilan" birga ekanidir.') WHERE id = 'c91fbfe5-d2ab-4e49-af9d-4a6651e84084';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz tortinchoqlik qilayotganini ko‘rganingizda, bunga qanday munosabat bildirishingiz juda muhim. Masalan, mehmon kelganida bolangiz salomlashish o‘rniga orqangizga yashirinsa, "Kechirasiz, u biroz uyatchan" deyish o‘rniga, unga "Hozir biroz tortinganga o‘xshaysiz, hechqisi yo‘q. Istagan vaqtingizda salomlashishingiz mumkin" deb, uni xotirjam qilishingiz mumkin. Kirishimlilik borasida unga namuna bo‘ling. Farzandingiz xatti-harakatlaringizga taqlid qilishni yaxshi ko‘radi, shuning uchun sizning boshqalar bilan bemalol gaplashayotganingizni ko‘rishi uning qo‘rquvini kamaytiradi. Uni muloqot qilishga majburlamasligingiz, ayni paytda haddan tashqari himoyachi ham bo‘lmasligingiz kerak. Agar u qiynalayotgan bo‘lsa, "Men ham yoningizdaman" deb qo‘llab-quvvatlang, lekin uning o‘rniga gapirib yubormaslikka e’tibor bering.') WHERE id = '654b2eea-2901-44dc-a0c2-15d66d812f41';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar 4 yoshga to‘lgan farzandingiz hali ham sakray olmasa, qog‘ozga chizgilar chizishda qiynalsa, interaktiv o‘yinlarga qiziqish bildirmasa, boshqa bolalarni e’tiborsiz qoldirib, faqat oila a’zolari bilan gaplashsa, kiyinish, uxlash yoki hojatxonaga borishga qat’iy qarshilik ko‘rsatsa, oddiy topshiriqlarni bajara olmasa, "bir xil" va "har xil" tushunchalarini anglamasa, men, siz, biz kabi so‘zlarni to‘g‘ri ishlata olmasa hamda avval bajara olgan ishlarini endi qila olmay qolsa, albatta pediatr bilan maslahatlashishingiz kerak. Farzandingizning rivojlanishini yaqindan kuzatishingiz va zarur bo‘lganda vaqtni boy bermay mutaxassisga murojaat qilishingiz lozim.') WHERE id = 'c8e84d4c-705c-4807-8598-eeefbb760a42';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar siz 4 yosh sindromini boshdan kechirayotgan bo‘lsangiz, avvalo farzandingiz bilan endi katta odamdek gaplashishingiz mumkinligini bilishingiz kerak. Voqealarni u tushunadigan tilda izohlab, xatti-harakatlarining oqibatlarini muloyimlik bilan tushuntirishingiz lozim. Bu davrda bolada doimiy o‘jarlik va sizga qarshilik ko‘rsatish holatlari kuzatilishi mumkin. U ona va ota o‘rtasidagi munosabatni qizg‘angani uchun shunday tutishi mumkin. Bunday xatti-harakatlarni to‘g‘rilash uchun farzandingizni tushunishga harakat qiling. Bu davr o‘tkinchi ekanini unutmang va sabrli bo‘ling. Sizning sabringiz uning sizga bo‘lgan ishonchini oshiradi. Hamkorlik qilishga undash uchun uni qiziqarli o‘yinlar yordamida “ko‘ndirishga” harakat qiling. Masalan, biror ishni navbat bilan bajaring: “Kel, stolni birga yig‘ishtiramiz, buyumlarni bittadan olib boramiz. Birinchi bo‘lib sen boshlashni xohlaysanmi?” yoki bir maqsad qo‘ying: “Kel, otang/onang uyga kelguniga qadar xonani yig‘ishtirib, uni hayratda qoldiramiz”. Farzandingiz ulg‘aygani sari muammolarni hal qilish yo‘llari haqida ko‘proq suhbatlashishingiz va unga o‘z hayoti bilan bog‘liq kichik mas’uliyatlarni topshirishingiz mumkin.') WHERE id = 'c36022d1-4912-4893-a17f-9e3be09bee79';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarimizda tabiatga mehr va ekologik ongni shakllantirish uchun ularni kichik yoshidanoq tabiat bilan tanishtirishimiz kerak. Tabiatni asrash, tirik mavjudotlarning yashash muhitiga zarar yetkazmaslik va atrof-muhitga ehtiyotkorona munosabatda bo‘lish bu tarbiyaning asosini tashkil etadi. Bolalarning hayvonlar va o‘simliklarga bo‘lgan tabiiy qiziqishini hisobga olsak, bu jarayon ular uchun juda maroqli kechadi. Tuproq bilan o‘ynash, daraxtlarga chiqish va turli o‘simliklarni o‘rganish bolalarning eng sevimli mashg‘ulotlaridandir. Ularda tabiatga mehr uyg‘otish uchun kuzatish imkonini yarating. Masalan, o‘rmonda sayr qilayotganda o‘zingiz bilan kattalashtiruvchi oyna olib, unga atrofni o‘rganishga ruxsat bering. Atrof-muhitni asrash uchun qilayotgan har bir harakatingiz sababini farzandingizga tushuntirib, unga o‘rnak bo‘ling.') WHERE id = '782daa87-3be8-4609-ae44-9ef72cd59434';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabga endigina borgan yoki borish arafasida turgan farzandingiz moslashish jarayonida qiynalishi mumkin. Barcha tayyorgarlik va umidlarga qaramay, moslashish bilan bog‘liq muammolar yuzaga kelishi tabiiy. Anacan oilasi sifatida shuni ta’kidlamoqchimizki, ota-onalarning to‘g‘ri yondashuvi bilan bu bosqichdan sog‘lom tarzda o‘tish mumkin. Muammo aynan qachon yuz berayotganini kuzating: uydami, eshik oldidami yoki xayrlashayotgandami? Tayyorgarlik boshlanishidan oldin ko‘rilgan choralar bolaning his-tuyg‘ularini muvozanatda saqlashga yordam berishi mumkin. U ilk bor yig‘laganida yoki ovozi titraganida vaziyatni bo‘rttirmang; vahima yuzaga kelmasligi uchun o‘qituvchisidan ham xotirjamlikni saqlashni so‘rang. Maktabning ilk kunlarida yaqin atrofda bo‘lishingiz, hovlida yoki tashqarida kutishingiz bolangizni tinchlantiradi. Sizni juda sog‘inganini aytgan bolajoningizning cho‘ntagiga suratingizni solib qo‘yishingiz mumkin; sog‘inganida unga qarash bolaga kuch beradi.') WHERE id = '19cc624e-7756-4818-b419-54e639b9f0af';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'To‘g‘ri muloqot farzandingizning o‘ziga bo‘lgan ishonchiga ijobiy ta’sir ko‘rsatadi. Uning xatti-harakatlari sababini tushunish uchun har bir yosh davriga xos o‘zgarishlardan xabardor bo‘lishingiz kerak. Uning dunyosiga kirib, muloqot qilganingizda orangizda yanada mustahkam rishta paydo bo‘ladi. Unutmang, muloqot shunchaki gaplashish emas, balki his-tuyg‘ularni tushunishdir. Farzandingiz o‘z fikrlarini siz kabi aniq ifodalay olmasligi mumkin. Uni yaxshi bilish va tana tilidan nimalarni his qilayotganini anglash muhim. Bolalikdagi xotiralaringizni u bilan bo‘lishing; faqat yutuqlaringiz haqida emas, qiyinchiliklardan nimalarni o‘rganganingizni ham aytib bering. Qadriyatlarni unga shunchaki tushuntirmang, balki kichik o‘yinlar orqali o‘rgating.') WHERE id = '02c1c3a8-5b3e-40d6-94fa-15af563477e1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolani to‘xtatish uchun ishlatiladigan "yo‘q" so‘zi ta’sirini yo‘qotmasligi uchun kam va lo‘nda qo‘llanishi kerak. Doimiy va qisqa ogohlantirishlar berish o‘rniga, vaziyatni qisqacha tushuntirish lozim. Biroq tushuntirishni ham juda cho‘zib yubormang. Masalan, "Yo‘q, bunday qilma!" deyish o‘rniga, "Likopchani yerga tashlasang, ovqatimiz to‘kiladi va pol ham iflos bo‘ladi, shuning uchun likopcha stol ustida turishi kerak" deyish to‘g‘riroq. Shu tariqa siz dasturxon atrofida o‘tirish qoidalarini ham o‘rgatgan bo‘lasiz. Unutmang, miya har doim ijobiy ifodalarga yaxshiroq javob beradi. Biror narsani taqiqlamoqchi bo‘lsangiz, "qilma" deb ta’kidlagan harakatni emas, uning o‘rniga bajarishini istagan harakatni ayting.') WHERE id = '7349c0d0-efa6-4d5a-8508-d577646dbb46';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tug‘ilgan kundan beri eng ko‘p sizni — onasini ko‘rishga o‘rgangan, ammo unga turli ijtimoiy muhitlar ham kerak. Bobo, ota, amaki yoki oiladagi boshqa erkaklar bilan birga o‘tkazadigan maxsus kunlarni tashkil qilishingiz mumkin. Ota va bolaning birga vaqt o‘tkazishi uchun sharoit yarating; dam olish kunlari kino, teatr yoki istirohat bog‘iga borishlarini rag‘batlantiring. Kundalik ishlarda, masalan, oziq-ovqat xarid qilishda otasiga yordam berishga uni ruhlantiring. Kitob o‘qish vaqtini birga o‘tkazishingiz mumkin; ba’zan ona, ba’zan esa ota o‘qib berishi bu odatni yanada qiziqarli qiladi. Bolaning ehtiyojlari va parvarishi bo‘yicha vazifalarni bo‘lib olib, bir-biringizni qo‘llab-quvvatlashingiz juda muhim.') WHERE id = '697be98b-1f89-4c20-b93a-c838aed35dbc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bola bilan birga o''tkaziladigan vaqt, ayniqsa, oldindan rejalashtirilgan bo''lsa, har ikki tomon uchun ham maroqli bo''lishi juda muhim. Cheklangan vaqtga ko''plab mashg''ulotlarni sig''dirishdan ko''ra, kamroq, ammo qiziqarli va zavq bilan bajariladigan faoliyatlarni tanlagan ma''qul. Farzandingiz bilan o''tkazadigan vaqtingizni rejalashtirishingiz yoki voqealar rivojiga qarab erkin o''tkazishingiz mumkin. Biroq haftaning muayyan kunlarini "maxsus" vaqt sifatida ajratish bolaga o''zini muhim his qilishiga yordam beradi va oilaviy rishtalarni mustahkamlaydi. Kun davomida ko''p vaqt ajrata olmasangiz ham, kichik imkoniyatlardan foydalaning. Masalan, uyga oziq-ovqat kerak bo''lsa, uni bola bilan birga xarid qilish yoki charchatadigan kun oxirida birga sut va qahva ichish yoqimli lahzaga aylanishi mumkin. Farzandingiz bilan sifatli vaqt o''tkazish oila a''zolariga bir-birini yaxshiroq tushunishga yordam beradi hamda bolaning ijtimoiy-emotsional rivojlanishiga ijobiy ta''sir ko''rsatadi.') WHERE id = 'c6c8fb11-1f84-4d93-bc2b-bbdb69021b35';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz sog''lom o''sishi uchun ayrim vitamin va minerallarga ehtiyoj sezadi. Ulardan ba''zilarini quyidagicha sanab o''tish mumkin: kalsiy suyaklar va tishlarni mustahkamlashga yordam beradi, asab hamda mushaklar faoliyatini qo''llab-quvvatlaydi. Omega-3 va Omega-6 hujayralar hosil bo''lishiga yordam beradi, asab tizimini tartibga soladi, miya va ko''z faoliyati uchun zarurdir. Magniy suyaklarni mustahkamlaydi, yurak ritmini tartibga soladi va immunitet tizimini qo''llab-quvvatlaydi. A vitamini ko''zlar va suyaklarning rivojlanishi uchun juda muhim bo''lib, organizmni infeksiyalardan himoya qiladi. D vitamini organizmning kalsiyni o''zlashtirishiga yordam beradi va tishlar mustahkamligi uchun zarurdir. Rux esa moddalar almashinuvida ishtirok etuvchi ko''plab fermentlarning asosini tashkil qiladi va bolaning bo''yi o''sishi uchun katta ahamiyatga ega.') WHERE id = '23a0fd1e-ea5f-49f5-aacf-24ca65d87de4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Niqoblar bilan o''yin o''ynab, farzandingiz bilan maroqli vaqt o''tkazishingiz mumkin. Uydagi bir nechta niqobga qalam bilan xursand, g''amgin va jahldor kabi yuz ifodalarini chizing. Ularni chizish davomida bolangiz bilan his-tuyg''ular haqida suhbatlashishingiz mumkin. So''ng niqoblarni oila a''zolariga tarqating. Farzandingiz boshchiligida har bir kishiga “O''zingizni qanday his qilyapsiz?” degan savolni bering. Niqobni taqqan kishi esa, masalan, “Bugun bog''ga borganim uchun o''zimni xursand his qilyapman”, deb o''z hissini bir jumla bilan tushuntirsin. Bu o''yinni navbat bilan davom ettiring. Anacan oilasi sifatida butun oilangiz bilan o''ynashingiz mumkin bo''lgan ushbu qiziqarli o''yindan zavqlanishingizni tilaymiz.') WHERE id = 'e680b3c8-68d3-4b9f-bffd-d682fa74d0b9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning kognitiv rivojlanishini qo''llab-quvvatlash uchun u o''rgangan tushunchalarga oid o''yinlar tashkil qilishingiz mumkin. Masalan, doskaga o''zingizning va bolangizning ismini yozib, jadval tuzing. Katta va kichik tushunchalarini mustahkamlash uchun unga “Katta to''pni qutiga sol” yoki “Kichik mashinani stol ustiga qo''y” kabi topshiriqlar bering. Bola topshiriqni to''g''ri bajarganda, jadvalga bitta yulduzcha qo''ying. Shu tariqa tushunchalarni ham, sanashni ham mashq qilgan bo''lasiz. O''yinni navbat bilan o''ynang, ammo bola yutishi uchun ataylab yutqazishdan saqlaning. Farzandingiz buni sezsa, har doim g''alaba qozonishni talab qilishi mumkin. Haqiqiy raqobat muhiti uning rivojlanishi uchun foydaliroqdir.') WHERE id = '41e1c28b-f6fa-4151-9135-15d7818fc948';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar nomaqbul xatti-harakat qilganda, bu noto''g''ri ekanini tushuntirish uchun eng ko''p qo''llaniladigan usullardan biri "tanaffus" usulidir. Bu usulda bola salbiy xatti-harakat qilganidan so''ng, uning oqibati sifatida bir muddat yolg''iz qolishi mumkin bo''lgan xona yoki joyda hech qanday faoliyat bilan shug''ullanmay kutadi. Shu tariqa bolaga uning xatti-harakati nomaqbul ekani haqida tushuncha beriladi. Avvalo, farzandingiz bilan tanaffus usuli nima ekanini muhokama qiling. Bu uning o''z xatti-harakati haqida o''ylashi, tinchlanishi va yangi xulq-atvor usulini shakllantirishi uchun imkoniyat ekanini tushuntiring. Qancha vaqt va qayerda kutishini, shuningdek, qaysi xatti-harakatlardan keyin tanaffus berilishini oldindan belgilab, unga ayting. Farzandingiz tanaffus paytida yolg''iz qolishi kerak, shuning uchun har ikki daqiqada uning yoniga bormang. Unutmang, bolaning o''zini o''zi tinchlantirish ko''nikmasini o''rganishi asosiy maqsadlarimizdan biridir.') WHERE id = '93d4efd0-8678-4cd0-b1ec-9612e7a0c85c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ota-ona sifatida, avvalo, bolani mulk tushunchasi bilan tanishtirishingiz kerak. Mulk, tegishlilik va egalik kabi tushunchalarni anglamagan bolaga bo''lishish kabi yuqoriroq darajadagi xatti-harakatga o''tish qiyin bo''ladi. Shuning uchun dastlab bola o''ziga tegishli buyumlarni anglab yetishi va ularga nisbatan tegishlilik hissini shakllantirishiga yordam berishingiz kerak. Bu yoshdagi bola uchun o''yinchog''i yoki buyumini boshqa birov bilan bo''lishish uni yo''qotish bilan barobar. Agar o''yinchoq uning qo''lida va nazoratida bo''lmasa, uni butunlay yo''qotdim, deb o''ylaydi. Bolani bezovta qiladigan narsa aynan shu yo''qotish qo''rquvidir. Kundalik hayotingizda "qarzga berish", "qaytarib olish", "bo''lishish" va "qaytarish" kabi so''zlardan tez-tez foydalanish hamda bularni xatti-harakatlaringiz bilan ko''rsatish bolaga ushbu tushunchalarni osonroq anglashga yordam beradi.') WHERE id = 'c20ae6c1-3ea1-42a3-94ba-f3d5d43252dc';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning rivojlanishini qo‘llab-quvvatlash uchun u bilan uycha o‘yinini o‘ynang. O‘yinni uning o‘zi boshqarishiga imkon bering va uning harakatlarini siz ham takrorlang. Buvisinikida qolish yoki bog‘chaga qatnay boshlash kabi farzandingizda xavotir uyg‘otadigan holatlar bo‘lsa, bu qo‘rquvni o‘yin orqali yengishga harakat qiling. Nima kiyishi yoki qaysi o‘yinni o‘ynashi kabi oddiy qarorlarni o‘zi qabul qilishiga sharoit yarating. Do‘stlari bilan o‘ynayotganda yuzaga keladigan muammolarni o‘zi hal qilishiga imkon bering, ammo yordamga ehtiyoji bo‘lishi mumkinligi uchun uni yaqindan kuzating. "Keyin", "avval", "oxirida" kabi ketma-ketlikni bildiruvchi so‘zlardan foydalanib, voqealar tartibini tushunishiga yordam bering. Uning "Nega?" degan savollariga javob berishga e’tibor qarating. Agar javobni bilmasangiz, kitob yoki internetdan birgalikda izlang. Ranglar, tez-tez ishlatiladigan asboblar va rasmlarda ko‘rayotgan buyumlaringiz nomini birgalikda ayting.') WHERE id = '73787f75-075a-4741-af86-ccb8d137e83d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yosh — qarshilik ko‘rsatish va gapga kirmaslik davri. Istagi rad etilganda bola kattalar bilan noo‘rin va qo‘pol gaplashishi, o‘rtoqlari bilan urishib qolishi mumkin. U chegaralarni sinab ko‘radi va kattalarning obro‘siga qarshi chiqadi. Jahli chiqarilsa, urishi, tepishi va o‘zini baxtsiz his qilayotgan joydan ketishni xohlashi mumkin. Shovqin solib kuladi, baland ovozda yig‘laydi, his-tuyg‘ularida keskin o‘zgarishlar kuzatiladi. Qo‘pol so‘zlarni ishlatishni yoqtiradi. Bu yoshda bola, ayniqsa, o‘zi bilan bir jinsdagi oila a’zosi bilan ziddiyatga boradi. Endi unga to‘g‘ri va noto‘g‘ri tushunchalarini singdirish kerak. Zarur bo‘lganda uni o‘z xonasiga yuborish yoki TV dasturini ko‘rishni taqiqlash kabi oddiy jazo choralarini qo‘llash mumkin. Biroq farzandingiz nima sababdan jazolanganini albatta bilishi kerak. Chunki u jazoning sababiga qiziqadi; agar bu tushuntirilmasa, o‘ziga nisbatan adolatsizlik qilingan deb o‘ylashi mumkin.') WHERE id = '032b690d-3849-44c8-ae6b-5cc63b6a8ddb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingiz noroziligini arazlash orqali namoyon qilsa, u arazlagan paytda xohlagan narsasini qilib bermasligingiz kerak. Agar uning istaklari arazlagani uchun bajarilsa, u bu usulni samarali yo‘l deb qabul qiladi va arazlash unda odatga aylanadi. Bola his-tuyg‘ulari va fikrlarini ifodalaganida unga jahldor munosabat bildirmaslik kerak; aks holda, o‘zini tushuntira olmagan paytda yana arazlashi mumkin. Unga his-tuyg‘ularini boshdan kechirishiga imkon bering. Ba’zida esa bolalar shunchaki e’tiborni jalb qilish uchun arazlaydi. Ular hech qanday sababsiz ham arazlashlari mumkin. "Nega arazlading? Nima bo‘ldi?" kabi savollar unga yoqadi va sizning qiziqish bildirayotganingizni ko‘rib, buni odatga aylantirishi mumkin.') WHERE id = '64c55cb1-55ee-4499-904d-c4c1c752bd76';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar odatda rang-barang taomlarni yoqtiradilar. Shu sababli, agar farzandingizga go‘sht yedirishda qiynalayotgan bo‘lsangiz, kotletni sabzavotlar bilan aralashtirib pishirishingiz yoki uning likopchasini rangli bulg‘or qalampiri va sabzi bilan bezashingiz mumkin. Bolalar ko‘pincha oilaning ovqatlanish odatlaridan o‘rnak olishini unutmang. Masalan, kechki ovqatga unga go‘shtli no‘xat taomi tayyorlab, o‘zingiz bu taomni yoqtirmasligingizni aytsangiz, u ham yemaydi. Shuning uchun, ayniqsa, ovqat tanlaydigan farzandingiz bilan birga dasturxon atrofida o‘tirishga va bir xil taomni yeyishga e’tibor bering. Hammaga bir xil taom torting va uni ovqatlanishga rag‘batlantiring. Porsiya miqdoriga e’tibor bering, farzandingiz yeyishi mumkin bo‘lganidan ortiq taomni likopchasiga solmang.') WHERE id = '0821bceb-2f87-4c42-8bc9-c1a1e94cd15d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar bilan uyda o‘tkazish mumkin bo‘lgan mashg‘ulotlar orasida, ehtimol, eng ma’rifiylaridan biri barchamiz sevadigan bilimlar bellashuvidir. Biroq e’tibor berishingiz kerak bo‘lgan muhim jihat bor: juda qiyin savollar bilan farzandingizni o‘yindan bezdirib qo‘ymasligingiz kerak. Savollarni tayyorlashda uning yoshi va bilim darajasini hisobga oling. 4 yosh uchun bilimlar bellashuvi qiziqarli bo‘lishi mumkin, ammo savollar albatta shu yoshga mos tanlanishi kerak. Shu bilan birga, haddan tashqari oson savollar berish xatosiga ham yo‘l qo‘ymang, chunki bunda u to‘g‘ri javob berish zavqi va qiyinchiligini his qilmaydi. Biroz o‘ylagach javob bera oladigan savollarni tayyorlash unga muvaffaqiyat hissini tuyish imkonini beradi. Faqat ma’lumot so‘rash o‘rniga, uning ko‘nikmalarini rivojlantiradigan savollarni ham berishingiz mumkin.') WHERE id = 'e164832a-dcb2-4221-994b-d1966e1702f1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar farzandingizga kiyim tanlashda erkinlik bermasangiz, unda o‘ziga ishonchsizlik, uyatchanlik, odamovilik, qat’iyatsizlik va doimo kimdir yo‘l-yo‘riq ko‘rsatishini kutish kabi fe’l-atvor muammolari paydo bo‘lishi mumkin. Bolaga o‘zi xohlagan kiyimni tanlashiga va bu erkinlikni his qilishiga sharoit yaratish kerak. Faqat shu yo‘l bilan u kelajakda o‘z qarorlarini qabul qila oladigan, atrofdagilar ta’siriga berilmaydigan, ongli shaxs bo‘lib ulg‘ayishi mumkin. U tanlagan kiyimlar uyg‘unligi muvaffaqiyatsiz deb o‘ylasangiz ham, hech qachon salbiy fikr bildirmasligingiz kerak. Agar bola vaziyatga mos bo‘lmagan kiyimni tanlasa, unga muqobil variantlarni taklif qiling va ular orasidan tanlashini so‘rang. Farzandingiz unga imkon berilganini his qilganida, o‘ziga ham, ota-onasiga ham bo‘lgan ishonchi mustahkamlanadi. Har bir qadami taqiqlanadigan va ota-onasidan salbiy fikrlar eshitadigan bolalarning rivojlanishi sog‘lom tarzda to‘liq kecha olmaydi.') WHERE id = 'e0981ee6-c555-49e7-9bc4-ad0b8d24e258';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda uchraydigan ko‘z kasalliklari orasida miopiya, gipermetropiya kabi ko‘rish nuqsonlari, ambliopiya («dangasa ko‘z») va g‘ilaylik eng ko‘p kuzatiladi. Erta tashxis qo‘yish esa davolash jarayonini ancha osonlashtiradi. Ota-onalar farzandlarini 1 yoshdan boshlab har yili ko‘z tekshiruvidan o‘tkazishlari kerak. Farzandingizning ko‘zlari sog‘lom bo‘lishi sizning e’tiboringizga bog‘liq. Bolangiz televizorni kamida 2-3 metr masofadan ko‘rishini, kompyuter va elektron o‘yinlarga haddan tashqari ko‘p vaqt sarflamasligini ta’minlang. U uxlayotganda xona qorong‘i bo‘lishiga e’tibor bering. Maktabgacha bo‘lgan davrda farzandingizni albatta ko‘z tekshiruvidan o‘tkazing.') WHERE id = '1c782aed-0528-4b86-ab5d-711c85f9c8ef';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ba’zi bolalar uy ishlariga yordam berishni juda yaxshi ko‘radi. Ota-onasi ularni maqtaganida esa bu mashg‘ulotlar ular uchun chinakam bayramga aylanadi. Kiyimlarni osishni 4 yoshli bolalar uyda bajarishi mumkin bo‘lgan eng oddiy va foydali ishlardan biri deb hisoblash mumkin. Bu mashg‘ulot bolaning yirik motorika ko‘nikmalarini rivojlantirishga ham, unda mas’uliyat hissini shakllantirishga ham katta hissa qo‘shadi. Agar uyingizda yetarlicha joy bo‘lsa, ikkita stul orasiga ip tortib, farzandingizga haqiqiy tajriba orttirish imkonini berishingiz mumkin. Bunday imkoniyat bo‘lmasa, siz kiyimlarni osayotganingizda undan rangli qisqichlarning rangini aytib, sizga uzatishini so‘rashingiz mumkin. Bu kabi oddiy uy ishlari uning ham ko‘ngil ochishiga, ham vaqtini unumli o‘tkazishiga yordam beradi.') WHERE id = '2a191d55-3beb-4691-9233-97ec0fcde1ca';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalarda o‘sish jarayoni davom etayotgani sababli ularning oqsilga (proteinga) ehtiyoji yuqori bo‘ladi. Oqsillar o‘sish va rivojlanish davrida organizmda kechadigan ko‘plab jarayonlarda muhim rol o‘ynaydi. Agar tanamiz yetarli miqdorda oqsil olmasa, hujayralar yangilana olmaydi. Oqsilga bo‘lgan ehtiyoj har bir yosh guruhida turlicha. Iste’mol qilinadigan oqsil manbalari organizm oson o‘zlashtira oladigan turlardan bo‘lishi kerak. Shu sababli ratsionda o‘simlik oqsillari bilan bir qatorda hayvon oqsillari ham bo‘lishi lozim. Oqsil yetishmasligi bolalarning bo‘yi o‘sishi va aqliy rivojlanishiga salbiy ta’sir ko‘rsatishi, o‘sish bilan bog‘liq muammolarga olib kelishi mumkin. Bundan tashqari, oqsil organizmdagi ko‘plab muhim reaksiyalarda ishtirok etishini hisobga olsak, ushbu jarayonlarda ham buzilishlar yuzaga kelishi mumkin.') WHERE id = '9cc989fa-9fcc-4747-9ab8-8d7ee4996fa1';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar qanchalik kirishimli bo‘lmasin, ba’zan gavjum muhitda o‘zlarini noqulay his qilishlari mumkin. Uyatchan bola uchun doim baqirib-chaqiradigan bolalar bilan to‘la joy yanada qo‘rqinchli tuyulishi mumkin. Shu sababli, avval farzandingiz o‘zini erkin his qiladigan 2-3 kishilik kichik do‘stlar guruhidan boshlagan ma’qul. Tadqiqotlar ota-onasi kirishimli bo‘lishga majburlagan bolalar yanada ko‘proq odamovi bo‘lib qolishini ko‘rsatadi. Agar farzandingiz biror narsani qilishni istamasa, uni majburlash o‘rniga, o‘zini xavfsiz his qilishi uchun yonida ekaningizni unutmang. Bolaning o‘ziga ishongan inson bo‘lib voyaga yetishining eng asosiy omillaridan biri — ota-onasi bilan o‘rnatilgan mehrli rishtadir. Kerak bo‘lganda yordam berish uchun yonida ekaningizni bilishi farzandingizning o‘zini erkinroq his qilishiga yordam beradi. Farzandingizni ko‘p quchoqlashni va doimo uning yonida ekaningizni eslatib turishni unutmang.') WHERE id = '9e83e717-03f9-48ad-8599-e9b3f6b74810';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabgacha yoshdagi bolalar uchun kitoblarda rasmlar ko‘p, matn esa kam bo‘lishi kerak. Bu yoshdagi bolalar hali o‘qish va yozishni bilmagani uchun rasmlardan keng foydalanish juda muhim. Shu tariqa farzandingiz rasmlarga qarab o‘z hikoyasini tuzishi mumkin. Bu esa kitobning har bir sahifasi haqida uzoq suhbatlashish va bolangizning tasavvurini boyitish imkonini beradi. Kitob o‘qish kundalik odatga aylanishi va ma’lum vaqtlarda bajarilishi lozim. Kitoblarni farzandingizning qo‘li yetadigan va ko‘zga tashlanadigan joyga qo‘yish uning kitoblarga bo‘lgan qiziqishini oshiradi. Unutmang, kitoblar farzandingizning xayolot olamini boyitadigan eng muhim vositadir.') WHERE id = '64e5e154-bafe-4ba9-8c71-d21bdc7456e5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Egiluvchanlik bolalarda tug‘ma jismoniy xususiyatdir, ammo muntazam mashq qilinmasa, vaqt o‘tishi bilan yo‘qolishi mumkin. Sport bilan shug‘ullanish harakatlarni yanada chaqqon bajarish, mushaklar va bo‘g‘imlarning yaxshiroq shakllanishiga yordam beradi. Bu esa kelajakda yuzaga kelishi mumkin bo‘lgan muammolarning oldini oladi. Egiluvchanlikni oshiradigan mashqlar kamharakat turmush tarzi, shuningdek, jismoniy faollik va to‘g‘ri ovqatlanish yetishmasligi tufayli kelib chiqadigan yurak kasalliklaridan himoyalanishga yordam beradi. Agar farzandingizning kichik yoshidan boshlab bu masalaga e’tibor qaratsangiz, u ulg‘ayganda ham tanasining egiluvchanligi tufayli hayot sifatini yaxshilashingiz mumkin. Bolalikda mashq qilinmasa, bu qobiliyat yo‘qoladi. Shu bois farzandingizni har kuni jismoniy mashqlar bilan shug‘ullanishga undash juda muhim.') WHERE id = '8daede29-43de-4cc2-b936-3eabf9151ee9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'To‘rt yoshda bolani emlash va umumiy tibbiy ko‘rikdan o‘tkazish kerak. To‘rt-olti yosh oralig‘ida kombinatsiyalangan vaksina (difteriya-qoqshol-ko‘kyo‘tal-poliomiyelit), shuningdek, qizamiq, qizilcha va epidemik parotitga qarshi emlashlar albatta yakunlanishi lozim. Bundan tashqari, bir yoshdan keyin birinchi dozasi qilingan suvchechakka qarshi vaksinaning ikkinchi dozasi oila bilan maslahatlashgan holda berilishi kerak. Vaksinalarni ishlab chiqarishda yuqori texnologiyalar qo‘llanayotgani tufayli hozirda nojo‘ya ta’sirlar avvalgi yillarga qaraganda ancha kam kuzatiladi. Emlashdan keyin yuzaga kelishi mumkin bo‘lgan umumiy nojo‘ya ta’sirlarga isitma, bezovtalik, ukol qilingan joyda qizarish va qattiqlashish hamda toshmalar kiradi. Bolalik davridagi emlashlar go‘yo 4-6 yoshda tugaydigandek ko‘rinadi, ammo bu jarayon maktab yoshidagi bolalar va kattalar uchun mo‘ljallangan vaksinalar bilan davom etadi. Sog‘lig‘imiz uchun butun umr davomida bunga e’tiborli bo‘lishimiz, yangiliklar va rivojlanishlarni kuzatib borishimiz kerak.') WHERE id = '14296ec3-0bb3-4c1d-b05b-6b38f4e1856a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu yoshdagi bolalarning ishtahasizligi va ovqat yeyishni istamasligi onalarni eng ko‘p xafa qiladigan va tashvishga soladigan masalalardan biridir. Ishtahasiz deb hisoblangan bola aslida ovqatlanish tartibi noto‘g‘ri bo‘lgani sababli ovqat yemasligi mumkin. Bolalar ishtahasiga ta’sir qiluvchi asosiy omillardan biri — ovqatlanish oralig‘ida turli zararli yeguliklarni yeb, qornini to‘ydirib olishidir. Natijada o‘zini to‘q his qilgan bola asosiy taomlarni yeyishdan bosh tortadi. Uni tinchlantirish uchun asosiy ovqatdan oldin bergan bir bo‘lak shokolad yoki keks bolaning ishtahasini bo‘g‘ib, dasturxondagi taomlarni rad etishiga sabab bo‘ladi. Farzandingizga ehtiyojini qondiradigan yengil tamaddilar yoki mevalarni nonushta bilan tushlik yoxud tushlik bilan kechki ovqat oralig‘ida berishingiz mumkin. Biroq bu tamaddilar ishtahani bo‘g‘adigan miqdorda va asosiy ovqatlanish vaqtiga juda yaqin paytda berilmasligi kerak.') WHERE id = 'ae163783-e98e-4f90-a211-90fa0def0173';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizda arazlash odati bo‘lsa, bunday paytlarda uning e’tiborini boshqa narsaga yo‘naltirish kerak. U arazlaganida yig‘lashi va jahl xurujlari kuzatilishi mumkin. Bunday holatlarda bolaning istagini aslo bajarmasligingiz kerak. Agar u shu yo‘l bilan istagiga erisha olsa, buni doimiy odatga aylantiradi va kelajakda sizni yanada qiyin vaziyatlar kutadi. Hatto eng kichik istagi bajarilmaganida ham vaziyatni keskinlashtirib, soatlab yig‘lashi va o‘ziga zarar yetkazishi mumkin. Bir muddat sabrli va izchil bo‘lib, uning istagini bajarmasangiz, bola bunday xatti-harakat noto‘g‘ri ekanini tushunadi. Shuningdek, oila kattalarining ham bu jarayonga aralashmasligi juda muhim.') WHERE id = '2d13d9c9-bb17-4082-9f50-12d59ae41bd4';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshdan boshlab bolalarda istaklariga qarshi chiqilganda kattalar va tengdoshlariga qo‘pol munosabatda bo‘lish, qoidalarga rioya qilishda qiynalish davri boshlanadi. Qisqa vaqt ichida xatti-harakatlarning bunchalik o‘zgarishi bolaning tashqi olam bilan aloqasi kengayishi va mustaqil, ya’ni alohida shaxs bo‘lishga intilishi bilan bog‘liq. Farzandingiz tartibli hayotga muhtoj va u qoidalar bilan ilk bor uyda tanishadi. Ammo unutmang, bola kutilmaganda joriy etilgan qoidalarga salbiy munosabat bildirishi mumkin. Shu sababli uydagi qoidalar oldindan belgilanishi kerak. Qoida o‘rnatish uchun bolaning noto‘g‘ri ish qilishini kutmang. Eng muhim shart — ota-onaning bu qoidalar borasida yakdil bo‘lishi va izchil yo‘l tutishidir. Farzandingiz ota-onaning munosabatini sinab ko‘rib, qoidalarni buzishga urinishi mumkin. Bunday vaziyatda yon bermaslik va o‘z pozitsiyangizda qat’iy turish juda muhim.') WHERE id = 'b1d3577e-af5f-48bb-808f-1582a526b07c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingiz uyda o‘ziga tegishli narsani boshqalar bilan bo‘lishishni istamasa, jahli chiqishi yoki xafa bo‘lishi mumkin. Bunday holatda bolaning his-tuyg‘ularini tushunish va u bilan suhbatlashish uni tinchlantiradi. Uni tushunishayotganini his qilgan bola o‘jarlikni bas qilib, his-tuyg‘ularini erkinroq ifodalaydi. Mehmonga borayotganda o‘yinchoqlarni bo‘lishish bilan bog‘liq kelishmovchiliklarning oldini olish uchun bolaning sevimli o‘yinchoqlaridan bir nechtasini o‘zingiz bilan olib borish foydali. Uyingizga mehmonlar kelishidan oldin esa uning eng sevimli o‘yinchoqlarini birgalikda olib qo‘yishingiz mumkin. Uni o‘yinchoqlarini bo‘lishishga majburlamang, fikrini oldindan so‘rang. Bolalar o‘yin paytida tortishib qolsa, vaziyat jiddiylashmaguncha aralashmaslikka harakat qiling.') WHERE id = '44edf3db-c049-4ceb-9fd5-20d650c22cef';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Maktabgacha davr hisoblangan 4-5 yosh bolalarda to‘g‘ri ovqatlanish odatlariga asos solinadigan muhim bosqichdir. Bu davrda shakllangan odatlar kelajakdagi salomatlikka ham bevosita ta’sir qiladi. Ota-ona va oila kattalari bu borada bolaga o‘rnak bo‘lishlari kerak. Bolaning kundalik ratsioniga sut mahsulotlari, go‘sht, sabzavot va mevalar, yog‘lar hamda donli mahsulotlar kiritilishi lozim. Ayniqsa, nonushta qilish odatini shakllantirishga e’tibor berish kerak. Nonushta menyusiga pishloq, butun donli non, zaytun, pekmez yoki asal, sut, haftasiga 2-3 marta tuxum, yangi mevalar yoki uyda tayyorlangan quruq mevali kekslar kiritilishi mumkin. Bu yoshdagi bolalar juda faol bo‘lgani uchun ularga ham to‘yimli, ham sevib iste’mol qiladigan taomlar kerak.') WHERE id = 'c755e705-bd03-47e3-bce9-e59e4c48f874';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz bilan birga mazmunli vaqt o‘tkazishingiz uchun bir mashg‘ulot taklifimiz bor! Kerakli narsalar: shaffof qo‘lqop, 5 ta rangli pompon va qalam. Qo‘lqop barmoqlarini ketma-ket 1 dan 5 gacha raqamlab chiqing. So‘ng farzandingizdan siz tanlagan ranglarni raqamlarga mos ravishda joylashtirishini so‘rang (masalan, 1-barmoqqa sariq pompon, 2-barmoqqa ko‘k va hokazo). Ranglarning nomini ham ovoz chiqarib aytishini so‘rang. Bu mashg‘ulot bolaning sanash va ranglarni tanish ko‘nikmalarini mustahkamlaydi, shu bilan birga qo‘l motorikasini rivojlantiradi. Mashg‘ulot davomida uning yonida bo‘ling va oxirida vazifani qanchalik muvaffaqiyatli bajarganini ta’kidlab, uni ruhlantiring.') WHERE id = '7968b317-d8e5-40c3-af2c-ca78747307c5';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayniqsa, muayyan yosh davrlarida farzandingizda yangi xususiyatlar paydo bo‘layotganini ko‘rishingiz mumkin. Har bir rivojlanish bosqichida u tushunib olishi kerak bo‘lgan ko‘plab yangi tushunchalar borligini ham unutmasligingiz lozim. Yangi ko‘nikmalar bilan birga uyqu va ovqatlanish tartibi kabi asosiy masalalarda ham turli talab va istaklarga duch kelishingiz mumkin. "Bugun erta uxlashni xohlamayman!", "Bugun tuxum yeyishni xohlamayman!" – tanish holat, shunday emasmi? :) Bunday vaziyatlarda vahimaga tushmaslik va xotirjamlikni saqlash eng to‘g‘ri yo‘ldir. Siz uchun bir nechta maslahat… Uxlashni istamayotgan farzandingizni yotishga ko‘ndirish uchun bir-biringizga ertak o‘qishni taklif qilishingiz mumkin. Ertak oxiriga yetganda, ko‘zlar o‘z-o‘zidan yumila boshlaydi. Foydali mahsulotlarni taomnomaga kiritish uchun esa har bir luqmani yeganida qanchalik kuchli bo‘lishini harakatlaringiz bilan ko‘rsatishingiz mumkin. Quvnoq ovqatlanish vaqti bola uchun yanada ishonarli bo‘lishi mumkin. :)') WHERE id = 'c24494e2-2c33-41c4-ac7a-276ef9b4a65c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bolalar 4 yoshdan keyin qalamni 3 barmoq bilan ushlay boshlashi kutiladi. Albatta, buning vaqti hali kelmagan yoki bola o‘zini bunga tayyor his qilmayotgan bo‘lishi mumkin. Oldinda u qalam ushlaydigan judaaa ko‘p yillar bor. :) Shu sababli, farzandingiz hali qalamni 3 barmoq bilan ushlashga o‘tmagan bo‘lsa, xavotir olmang. Mushaklarini mustahkamlash uchun ko‘p narsa qilishingiz mumkin! Bo‘sh qog‘ozga uzuq-uzuq chiziqlar chizib, undan bu chiziqlarni birlashtirishini so‘rashingiz mumkin. Avvaliga oddiy tik yoki yotiq chiziqlardan boshlash va har bir muvaffaqiyatidan so‘ng uni tabriklash keyingi bosqichlar uchun ruhlantiruvchi bo‘ladi. Keyin doira, uchburchak va kvadrat kabi shakllarni uzuq chiziqlar bilan chizib, ularni birlashtirishini so‘rang. Bu juda samarali usul; biroz vaqt o‘tgach, to‘g‘ri yo‘naltirish yordamida farzandingiz qalamni bemalol ushlay boshlaganini ko‘rasiz.') WHERE id = 'ab3ed8b9-4614-4f45-be6c-955b461e9cf3';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '4 yoshga to‘lish arafasidagi farzandingiz har kuni o‘zini kashf etishga yanada ishtiyoqmand bo‘lib bormoqda! Ayrim oddiy mashqlarni o‘yinga aylantirib, uni qo‘llab-quvvatlashingiz mumkin. Keling, biroz o‘tmishga qaytamiz va sizda ham yoqimli xotiralarni uyg‘otadigan "klassik" (klass-klass) o‘yini bilan farzandingizni tanishtiramiz. Uni uyda eski bir yopqich ustiga chizib yoki ob-havo yaxshi bo‘lsa, tashqaridagi xavfsiz joyda yerga chizib o‘ynashingiz mumkin. Bir oyoqda turish, bir yoki ikki oyoqda sakrash kabi harakatlar farzandingizning yirik motorikasini rivojlantirishga yordam beradi. Albatta, avval bu o‘yinni unga siz o‘rgatishingiz kerak bo‘ladi. :) Bunda sabrli bo‘ling va birga o‘tkazadigan ushbu mazmunli vaqtingizni qoidalarga haddan tashqari bog‘lanib qolmasdan, maroqli mashg‘ulotga aylantiring!') WHERE id = 'da851837-93b4-4189-a1f5-c7b4993f4df9';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Mana, katta kun ham keldi! Farzandingiz 4 yoshga to‘lmoqda! 😊 Chaqalog‘ingiz hayotining to‘rtinchi yilini ortda qoldirmoqda. Bu tug‘ilgan kun uning do‘stlari bilan quvnoq o‘tkazadigan unutilmas xotirasiga aylanadi. Unga tengdoshlari bilan o‘yinlar o‘ynash, yugurib ko‘ngil ochish, hatto karaokedan tortib turli ijodiy mashg‘ulotlargacha bo‘lgan faoliyatlarda qatnashib, tug‘ilgan kunini nishonlash imkonini yaratishingiz mumkin — bu unga ajoyib sovg‘a bo‘ladi. Agar ob-havo yaxshi bo‘lsa, bayramni ochiq havoda o‘tkazish, eng avvalo, farzandingizga va qolgan barchaga yoqimli taassurot bag‘ishlaydi! Ushbu ajoyib kunda ko‘plab suratga tushishingiz kelajak uchun go‘zal xotira bo‘lib qoladi. Eng muhimi esa farzandingizni shu yoshga yetkazguningizcha qilgan barcha mehnatingizdir… Eng katta olqishga aynan siz loyiqsiz! Ajoyib ona ekaningizni aslo unutmang! <3') WHERE id = 'e9115fcf-1d07-412a-b5e2-14fb5de565de';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu oyda siz va chaqalog‘ingizni yangi tajribalar hamda o‘zgarishlar kutmoqda. Chaqaloqni kasalliklardan himoya qilish uchun tug‘ilganidan boshlab emlashlarni o‘z vaqtida qildirish juda muhim. Emlash orqali chaqaloq organizmiga oldini olish ko‘zda tutilgan kasallikning zaiflashtirilgan bakteriyasi yoki virusi kiritiladi. Bu jarayon immunitet hosil qilishga qaratilgan bo‘lib, chaqaloq organizmi ushbu kasalliklarga qarshi antitanachalar ishlab chiqara boshlaydi. Shunday qilib, kelajakda chaqalog‘ingiz bu mikroblarga duch kelganida, uning organizmi allaqachon kuchli himoya mexanizmiga ega bo‘ladi. 6-oylik emlash taqvimiga Gepatit B vaksinasining uchinchi dozasi, besh komponentli kombinatsiyalangan vaksinaning uchinchi dozasi va OPA (oral poliomiyelit) vaksinasining birinchi dozasi kiradi. Shuningdek, chaqaloq ilk bor oladigan bolalar falaji (poliomiyelit) vaksinasi ham ushbu ro‘yxatga kiritilgan. Shu bilan chaqalog‘ingizning dastlabki 6 oylik emlash taqvimi yakunlanadi.') WHERE id = '95f9ad1b-63d6-45ba-b708-bf282b104620';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Shu oydan boshlab chaqaloqning bir sutkadagi uyqu davomiyligi taxminan 13 soatni tashkil etadi. Kunduzi ikki marta uxlashi kutiladi. Kechasi esa 6-7 soat uzluksiz uxlashi mumkin. Chaqalog‘ingiz ulg‘aygani sari uning uyquga bo‘lgan ehtiyoji biroz kamayadi. Buning sababi o‘sishni ta’minlaydigan gormonlar aynan tungi uyqu vaqtida ajralib chiqishidir. Bu bosqichda chaqaloqning mustaqil uxlashga odatlanishi ham kutiladi. Ya’ni, agar siz uni hali ham tebratib, emizib yoki ko‘tarib yurib uxlatayotgan bo‘lsangiz, qisqa vaqt ichida buni kamaytirib, keyin to‘xtatishingizni tavsiya qilamiz. Ayrim mutaxassislar chaqaloqda sog‘lom tungi uyqu tartibini shakllantirish uchun u har yig‘laganida darhol aralashmaslikni maslahat berishadi. Shu nuqtai nazardan, chaqaloqning qorni to‘q, tagligi toza va hech qanday muammosi yo‘qligiga ishonchingiz komil bo‘lsa, u har yig‘laganida darhol aralashmasligingiz kerak. Har yig‘laganida bag‘riga olinadigan chaqaloq mustaqil uxlashi kerakligini o‘rgana olmaydi.') WHERE id = '790745e1-b64b-4611-b8ea-ced2bd5bd141';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tez sur’atda o‘sish va rivojlanishda davom etmoqda. Bu davrda uning har qachongidan ham harakatchan bo‘lib qolganini kuzatishingiz mumkin. Haqiqiy o‘yinchiga aylangan chaqaloq sog‘lom rivojlanishi uchun uning nutqi, aqliy rivojlanishi, mayda va yirik motorikasi, shuningdek, ijtimoiy ko‘nikmalari yoshiga mos bo‘lishi kutiladi. Chaqalog‘ingiz bilan har bir davrda uning yoshiga mos ravishda bajaradigan mashg‘ulotlaringiz bu rivojlanishni qo‘llab-quvvatlovchi eng muhim omillardan biridir. Chaqalog‘ingizni juda yaxshi ko‘rishingizni va uni har qanday ehtimoliy xavfdan himoya qilishni istashingizni bilamiz. Ammo ota-onaning haddan tashqari himoyachi munosabati chaqaloq rivojlanishiga katta to‘siq bo‘ladi. Masalan, ko‘chaga chiqqaningizda yiqilib tushishidan qo‘rqib, chaqaloqning erkin harakatlanishiga yo‘l qo‘ymasligingiz uning rivojlanishini sekinlashtiradi va bir muddatdan keyin o‘zini ojiz his qilishiga sabab bo‘ladi. Shu sababli, chaqaloqning rivojlanishiga mos ko‘nikmalarni egallashiga yordam beradigan mashg‘ulotlarga ruxsat berishingiz va zarur bo‘lmasa, aralashmasligingiz kerak.') WHERE id = '037a24b5-120f-42ab-b763-b5da751da157';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz tez yurgan yoki yugurgan paytlarda ko‘p yiqilishini kuzatishingiz mumkin. Bu holat odatda ota-onalarni xavotirga soladi. Aslida, chaqalog‘ingizning tez-tez yiqilishiga yurayotganda qadam bosayotgan joyiga emas, ko‘proq atrofga qarashi sabab bo‘ladi. Diqqati qadamlari yoki yerda bo‘lmagan chaqaloq har doim ham qayerga ketayotganiga e’tibor bermasligi mumkin. Muvozanat va harakatlar muvofiqligini kattalardek samarali boshqara olmaydigan chaqalog‘ingiz uchun yo‘lidagi to‘siqlar yiqilish xavfini tug‘diradi. Rivojlanish bosqichlari nuqtai nazaridan me’yoriy hisoblangan bu holatning oldini olish ko‘pincha imkonsiz. Shunga qaramay, ayrim xavfsizlik choralarini ko‘rishingiz muhim. Masalan, chaqalog‘ingizni qattiq va sirpanchiq yuzalarda emas, asosan gilam bilan qoplangan joylarda yurgizishingiz mumkin. U yashaydigan joydagi o‘tkir burchakli mebellarga himoya vositalarini o‘rnatishingiz, tayanish uchun ushlaydigan buyumlarini esa devorga mahkamlashingiz mumkin.') WHERE id = '2a1076da-9d2a-4614-8f87-b9105c907fbb';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning tagini tozalashda, ko‘rpa-to‘shaklari, tagliklari va kiyimlari uchun asosan paxta tarkibli mahsulotlardan foydalanishingizni va ularni afzal ko‘rishingizni bilamiz. Biroq bir muhim jihatni bilishingiz kerak: paxta yetishtirishda yiliga taxminan 40 ton kimyoviy vosita ishlatiladi. Bu miqdor butun dunyo qishloq xo‘jaligida yil davomida ishlatiladigan hasharotlarga qarshi vositalarning 25% aynan paxta uchun sarflanishini ko‘rsatadi. Bundan tashqari, qo‘llanadigan kimyoviy vositalarning ayrimlari ammiak, ftalatlar, parafin, formaldegid va og‘ir metallar kabi saratonni keltirib chiqarishi ma’lum bo‘lgan moddalardir. Shu sababli chaqalog‘ingiz uchun sanoat usulida yetishtirilgan paxta o‘rniga organik paxta va undan tayyorlangan mahsulotlarni tanlashingiz kerak. Organik paxta sanoat paxtasiga qaraganda tozaroq va barqarorroq mahsulotdir. Shuningdek, uni yetishtirishda genetik jihatdan o‘zgartirilgan organizmlarga ega urug‘lardan foydalanilmaydi. Organik paxta yetishtirishda sintetik qishloq xo‘jaligi vositalari, hatto o‘g‘it ham ishlatilmaydigan maydonlarga ustunlik beriladi. Bu chaqalog‘ingiz uchun qilishingiz mumkin bo‘lgan eng sog‘lom tanlovdir.') WHERE id = '86b8a2a1-5cc2-43a1-a0d3-0f8c36702077';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ayniqsa yoz oylarida chaqalog‘ingiz quyosh nuridan samarali va to‘g‘ri foydalanishi muhim. D vitaminining yaxshi manbai bo‘lgan quyosh nuri chaqalog‘ingizning tishlari va suyaklari rivojlanishi uchun katta ahamiyatga ega. Har kuni o‘rtacha yarim soat quyoshda bo‘lish chaqalog‘ingizga zarur D vitamini sintezlanishi uchun yetarli. Shunga qaramay, quyosh nurlari ostida uzoq vaqt qolish chaqalog‘ingiz uchun jiddiy salbiy oqibatlarga olib kelishi mumkin. Bu bosqichda chaqalog‘ingizning terlash funksiyasi faol bo‘lsa-da, uning organizmi hali katta odamnikidek chidamli emas. Shu sababli, chaqalog‘ingiz uzoq vaqt davomida kuchli quyosh nurlari ostida qolsa, terlash orqali organizmning ichki muvozanatini to‘liq saqlay olmasligi mumkin. Quyoshda bo‘lgan paytda chaqalog‘ingizga bosh kiyim kiydirish va ko‘zoynak taqishga e’tibor berish uni quyoshning zararli ta’siridan himoya qilishning yaxshi usuli bo‘ladi. Shuningdek, tarkibida rux bo‘lgan va chaqaloqlar uchun maxsus ishlab chiqarilgan quyoshdan himoyalovchi kremlardan foydalanishga e’tibor berishingiz kerak.') WHERE id = 'a261dbd0-eed1-46cd-8f75-71d0a2300d15';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqlar tug‘ilgandan keyin ma’lum haftalarda tez o‘sish va rivojlanish davrlarini (rivojlanish sakrashlarini) boshdan kechiradi. Siz hozir bo‘lgan 5-hafta ham ana shunday o‘sish sakrashlari yuz beradigan ilk haftadir. Shu sababli bu kunlarda chaqaloqning odatdagidan ko‘proq yig‘lashi, injiq bo‘lishi, uyqu bilan bog‘liq muammolarga duch kelishi yoki ishtahasi o‘zgarishi mutlaqo tabiiy. Ishtahasining oshishi ham o‘sish uchun ko‘proq energiyaga muhtojligi, ham bu ehtiyojni qondirish maqsadida ko‘proq emib, sut ishlab chiqarishni kuchaytiruvchi gormonlarni faollashtirishga intilishi bilan bog‘liq. 5-haftadagi ushbu rivojlanish sakrashi paytida chaqalog‘ingiz sezgi a’zolaridan faol foydalanib, atrofidagi hamma narsani anglay boshlaydi. Qisqacha aytganda, chaqalog‘ingiz endi o‘z dunyosi faqat ovqatlanish va uyqudan iborat emasligini kashf etmoqda. Natijada ko‘proq qo‘zg‘atuvchilarga duch kelgani uchun ba’zan bezovtaligi ortishi mumkin. Atigi bir necha kun davom etadigan bu davrni imkon qadar sabr bilan o‘tkazing va uning vaqtinchalik ekanini unutmang.') WHERE id = '3c3db532-5b9a-41a9-8a5e-67563130c5c0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqlarda «beshik qalpog‘i» deb ataladigan, bosh terisida qobiqli va tangachasimon dog‘lar paydo bo‘lishiga olib keladigan seboreyali qipiqlanish dastlabki oylarda tez-tez uchraydigan teri holatidir. Bu qizil va qipiqlanuvchi toshmalar peshona, quloq orqasi, bo‘yin va qo‘ltiq ostigacha tarqalishi mumkin. Agar chaqalog‘ingizda bunday qipiqlanish paydo bo‘lsa, xavotirlanishga hojat yo‘q. Odatda u qichishmaydi va chaqaloqni bezovta qilmaydi. Ba’zan tagligini almashtirayotganda qipiqlanish taglik sohasiga ham tarqalganini ko‘rishingiz mumkin. Kamdan-kam hollarda taglik sohasidagi bu holat zamburug‘li infeksiya bilan birga kechishi mumkin. Uning aniq sababi noma’lum bo‘lsa-da, irsiy moyillik, terida tabiiy ravishda yashovchi achitqi zamburug‘lari, ta’sirlantiruvchi moddalar, quruq va sovuq havo kabi omillar bunga sabab bo‘lishi mumkin.') WHERE id = 'dc08af3a-ac5d-4bd3-9ab0-537157d76301';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'To‘g‘ri emizish holatini topish chaqaloqning sutdan maksimal foyda olishi hamda sizning jismoniy salomatligingiz uchun juda muhim. Emizayotganda qulay holatni egallab, orqa va belingizni yostiq bilan tayanch qilishingiz kerak. Shuningdek, emizayotgan tomondagi qo‘lingiz ostiga balandroq tayanch qo‘yib, butun jarayon davomida qo‘lingizni havoda tutib turishdan saqlanishingiz lozim. Emizish vaqtida chaqaloqni imkon qadar o‘zingizga yaqin va yuzini sizga qaratgan holda tuting. Chaqaloqning tanasini bilagingizning ichki tomoniga, boshini esa tirsak bukilmasiga joylashtirish eng maqbul holatdir. To‘g‘ri holatni tanlash chaqaloqning rivojlanishi uchun ham hal qiluvchi ahamiyatga ega. Chunki chaqaloqni noto‘g‘ri holatda tutib emizishda davom etsangiz, uning bo‘yni tezda og‘riy boshlaydi va u emishni ertaroq to‘xtatadi.') WHERE id = '4be7fa1f-7739-407d-aa85-d7577ebd4d3a';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqaloqni muntazam cho‘miltirish uning immuniteti va teri salomatligi uchun juda muhim. Biroq cho‘miltirish jarayonida e’tibor berishingiz kerak bo‘lgan ayrim jihatlar bor. Ulardan eng muhimi — suv harorati. Chaqaloqni cho‘miltirish uchun suv taxminan 37 daraja bo‘lishi kerak. Bundan sovuqroq yoki issiqroq suv chaqaloqning terisiga zarar yetkazishi, shuningdek, uning kasallanishiga sabab bo‘lishi mumkin. Xona haroratini esa 22-24 daraja oralig‘ida saqlashingiz kerak. Yana bir muhim masala — vannadagi suv sathi. Bir lahzalik ehtiyotsizlikda chaqaloq qo‘lingizdan sirg‘alib ketishi mumkin, shuning uchun suv chuqurligi 15 sm-dan oshmasligi kerak. Yuvintirish vaqtida chaqaloqning boshi va tanasini bir paytda ho‘llamaslikka harakat qiling. Bosh sohasi orqali issiqlik juda tez yo‘qoladi. Chaqaloq sovqotishining oldini olish uchun avval uning tanasini yuving, tanasini yuvib bo‘lgach esa boshini yuvib, cho‘miltirishni yakunlang.') WHERE id = '9a3356cb-31bb-4c91-8c4b-755f5e18597d';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning miyasi alla, qo‘shiq, musiqa va hatto tashqaridan kelayotgan tovushlarga ham javob bera oladigan darajada rivojlangan. Chaqaloqning miyasi sog‘lom va to‘g‘ri rivojlanishi uchun kundalik hayotingizda musiqaga ham o‘rin ajratishingiz kerak. Bundan tashqari, chaqalog‘ingizga qo‘shiq yoki alla aytishingiz orangizdagi mehr rishtalarini ham mustahkamlaydi. Tadqiqotlarga ko‘ra, erta davrdan boshlab musiqa eshittirilgan chaqaloqlarda miya va nutq rivojlanishi boshqa chaqaloqlarga qaraganda tezroq kechadi. Shuningdek, bu bolalarning kelajakda musiqa asboblariga qiziqish bildirish ehtimoli oshishi ham kuzatilgan. Chaqalog‘ingiz hali qorningizdaligidayoq ovozingizni boshqa insonlarning ovozidan ajrata olgani uchun unga qo‘shiq va allalar aytish birgalikda mazmunli va quvnoq vaqt o‘tkazishingizga yordam beradi, shuningdek, chaqaloqning so‘z boyligi va til ko‘nikmalari shakllanishini tezlashtiradi. Ayniqsa, chaqalog‘ingiz uxlashga qiynalsa, klassik yoki sokin ohangdagi musiqa uni tinchlantirib, uxlab qolishini osonlashtiradi.') WHERE id = '161206e9-2801-48d5-bf23-ba2c2a393a9f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu kunlarda chaqalog‘ingiz doimiy bezovta bo‘lishi, o‘zini tinchlantirish uchun tez-tez emishni xohlashi, hatto ko‘krakdan ajralishni istamasligi mumkin. Bu belgilar chaqalog‘ingizda gaz bilan bog‘liq muammo borligini ko‘rsatadi. Fiziologik jihatdan tabiiy bo‘lgan bu holat ayrim chaqaloqlarda yengil kechsa, boshqalarida kolik og‘riqlariga sabab bo‘lishi mumkin. Ayniqsa, 8-haftadagi rivojlanish sakrashi yakunlanib, miya rivojlanishi tezlashishi bilan chaqaloq miyasi tanasidagi mushaklar, bo‘g‘imlar va nervlarni anglay boshlaydi. Bu anglash jarayonidan oldin chaqaloq gazni beixtiyor va oson chiqarardi. Ammo endi chaqalog‘ingiz bu mushaklarni ongli ravishda boshqarishga urinmoqda. Gaz chiqarish uchun zarur mushaklarni qanday qisib va bo‘shashtirishni o‘rganishiga biroz vaqt kerak. Chaqalog‘ingiz dastlabki oylarda bu mushaklarni to‘liq boshqara olmagani va ularni doimo tarang tutgani uchun gazni oson chiqara olmaydi, natijada gaz og‘riqlari yuzaga keladi. Bunday qiyin paytlarda chaqaloqni tinchlantiring va bu vaqtinchalik davr ekanini qabul qiling. Keyingi haftalarda miyasi rivojlanishda davom etar ekan, chaqalog‘ingiz bu mushaklarni boshqarishni o‘rganadi va gazni osonroq chiqara oladi.') WHERE id = 'f2315e81-cb4e-4e16-ad43-3687f3cbaef0';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz ma’nosini biladigan va faol ishlata oladigan 4-5 ta so‘zni birlashtirib, gap tuza oladi. Bu gaplar uning o‘zi, yoqtiradigan va yoqtirmaydigan holatlar, istaklari hamda savollari haqida bo‘lishi mumkin. Siz gapirayotganingizda u diqqat bilan tinglaydi va ilgari eshitmagan so‘zini takrorlay oladi. Shu tariqa u lug‘at boyligiga yangi so‘zlarni qo‘shadi. Hatto chaqalog‘ingiz tez-tez tinglaydigan, sodda so‘zlardan iborat qo‘shiqlarni kuylashga urinayotganini ham kuzatishingiz mumkin! 😊 Tug‘ilganidan boshlab doimiy ravishda eshitib kelayotgan tilni va unga xos tovushlarni o‘rganayotgan chaqalog‘ingiz gapirish ko‘nikmasini egallashi uchun hali ko‘p narsani o‘rganishi kerak. Chaqalog‘ingizning til va nutq ko‘nikmalarini rivojlantirish uchun unga tez-tez qo‘shiq kuylashni, kun davomida qilayotgan ishlaringiz haqida so‘zlab berishni va kuningiz qanday o‘tgani haqida suhbatlashishni unutmang. Ayniqsa, uni ijtimoiylashishi va tengdoshlari bilan muloqot qilishi mumkin bo‘lgan muhitlarga olib borishingiz til ko‘nikmalarini sezilarli darajada rivojlantiradi.') WHERE id = '0cd3469d-8d4a-4f4e-bc31-4c507bf9612c';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Bu bosqichda bolalarning aksariyati nutq jihatidan ancha faol bo‘ladi va ulardan 3-4 ta so‘zdan iborat gaplar tuzishi kutiladi. Agar farzandingizning nutqi yetarlicha rivojlanmaganidan shubhalansangiz, nutq rivojlanishining kechikishi haqida batafsilroq ma’lumot olishingiz foydali bo‘ladi. Kech gapiradigan bolalar — 18-36 oylik, tushunish bilan bog‘liq muammosi bo‘lmagan, ammo gapirmaydigan yoki yoshiga nisbatan kutilganidan kamroq gapiradigan bolalardir. Bunday bolalar o‘yin, harakat ko‘nikmalari va tafakkur kabi boshqa sohalarda tengdoshlari bilan bir xil rivojlanadi. Har bir bolaning o‘ziga xos o‘rganish sur’ati va uslubi mavjud, shu bois til rivojlanishidagi individual farqlar tabiiydir. Biroq bolalar ma’lum yosh oralig‘ida muayyan ko‘nikmalarni egallashi kutiladi. Nutq va til ko‘nikmalari haqida gap ketganda, bolalar o‘rtasidagi individual farq 3-4 oydan oshmasligi muhim.') WHERE id = 'acc902b1-927f-42d0-8f73-ca7698f89eab';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ko‘p qirrali intellekt nazariyasiga ko‘ra, insonda faqat bitta intellekt (IQ) emas, balki ko‘plab intellekt yo‘nalishlari va qobiliyatlar uyg‘unligi mavjud. Bu davrda chaqalog‘ingiz qaysi intellekt yo‘nalishiga ko‘proq moyilligini kuzata boshlashingiz mumkin. Masalan, unda sabab-oqibat aloqasini aniqlash, savol berish va mavhum fikrlash qobiliyati rivojlangan bo‘lsa, matematik-mantiqiy qobiliyati kuchliroq bo‘lishi mumkin. Agar u ko‘rish orqali o‘rganish, farqlarni sezish va xayoliy o‘xshatishlar yaratishga moyil bo‘lsa, vizual-fazoviy qobiliyati kuchliroqdir. Musiqiy shakllarni tushunsa, ularni bir-biridan ajrata olsa va o‘zini musiqa orqali ifodalasa, musiqiy-ritmik yoki eshitish intellekti yaxshiroq rivojlangan hisoblanadi. Bundan tashqari, chaqalog‘ingiz his-tuyg‘ulari va fikrlarini tushuntirish uchun tanasi hamda qo‘llaridan ko‘p foydalansa, tana-kinestetik intellekti ustunligini aytish mumkin. Bu qobiliyat qo‘llaridan doimo faol foydalanib, yangi narsalar yaratish, model yasash yoki muntazam ravishda o‘yin xamiriga shakl berish istagida namoyon bo‘lishi mumkin.') WHERE id = '9eabf6e3-daca-46d0-9e1c-7b73da5a85a6';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Agar chaqalog‘ingiz bu davrda o‘zini tayyor his qilsa va yaqinda ko‘chib o‘tish, ajralish yoki emizishdan chiqarish kabi keskin o‘zgarishlarni boshdan kechirmagan bo‘lsa, hojatxonaga o‘rgatishni boshlashingiz mumkin. Bu jarayonning eng nozik tomoni shundaki, u bolaning "egosentrik" (o‘zini markazda deb bilish) davriga to‘g‘ri keladi. Shu sababli unga yangi narsani o‘rgatish qiyin kechishi mumkin. 3 yosh inqirozining belgilari ham aynan shu davrda kuzatilgani uchun orangizdagi vakolat chegaralari sinovdan o‘tishi mumkin. Bir tomondan qoidalar belgilash, ikkinchi tomondan esa uning yig‘lashiga chiday olmaslik vaziyatni yanada murakkablashtiradi. Bu davrda haddan tashqari bosim o‘tkazish bolada o‘ziga ishonchning pasayishi va his-tuyg‘ularini bostirish kabi muammolarga olib kelishi mumkin. Buning oldini olish uchun chaqalog‘ingizga qum bilan o‘ynash, suv bilan o‘ynash va tabiat qo‘ynida yalangoyoq yugurish imkonini berishingiz mumkin. Bu mashg‘ulotlar uning zo‘riqishini kamaytirib, bo‘shashishiga yordam beradi.') WHERE id = '56eba127-0922-4581-82f1-54a03ed676ef';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning ushlash qobiliyati rivojlangani sababli u endi qalamni yaxshiroq ushlaydi va tennis to‘pi kabi kichik to‘plar bilan o‘ynay oladi. Farzandingiz bu harakatlarni bajarayotganda o‘ziga qulay bo‘lgan qo‘lni tanlaydi. Bunday paytda ayrim ota-onalar bola chapaqay bo‘lsa, uni o‘ng qo‘li bilan ishlashga majburlashi mumkin. Biroq bu mutlaqo noto‘g‘ri yondashuvdir. Qaysi qo‘ldan foydalanish miyaning ishlash tizimiga ko‘ra shakllanadi, shu sababli bu bola uchun tabiiy va sog‘lom jarayondir. Bundan tashqari, bu davrda chaqalog‘ingiz turli jismoniy ko‘nikmalarni ham rivojlantirishi kutiladi. Masalan, u bir oyoqda turishga urinishi va buning uddasidan chiqishi mumkin. Endi u qo‘llarini o‘zi yuvishni va kiyimlarini o‘zi kiyishni xohlaydi, chunki jismonan rivojlanayotganini his qiladi. Unga keng va qulay kiyimlar berishingiz bu istagini amalga oshirish jarayonida muvaffaqiyat hissini tuyishiga yordam beradi.') WHERE id = 'b96b8dee-7314-45ef-8935-c7aceece6b06';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, '2 yoshdan maktab davrigacha onalar eng ko‘p shikoyat qiladigan masalalardan biri — bolalarning doimo shirin oziq-ovqatlarni so‘rashidir. Shakar ozuqaviy qiymatga ega bo‘lmagan, ammo kaloriyasi yuqori moddalar qatoriga kiradi. Farzandingizning bu davrda bunday oziq-ovqatlarni iste’mol qilishi kelajakda turli kasalliklarga moyilligini oshirishi mumkin. Shu sababli uyda shirin oziq-ovqatlarni imkon qadar kamroq saqlashingiz kerak, shunda bola ularni oson topib yeya olmaydi. Shirinlikka bo‘lgan ehtiyojini qondirish uchun mevalarni uning qo‘li yetadigan joyga qo‘yishingiz mumkin. Ayrim ota-onalar tez-tez qilganidek, shokolad va konfetlarni mukofot sifatida ishlatmasligingiz kerak. Farzandingizning salomatligi uchun uyda tayyorlaydigan keks va pechenyelarga shakar o‘rniga meva qo‘shib, ularni foydaliroq qilishingiz mumkin.') WHERE id = 'da4edbe5-0e9f-475e-b94c-678be057a584';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingiz, ayniqsa, kechalari uxlab qolganidan biroz vaqt o‘tgach, qichqirib uyg‘onishini kuzatishingiz mumkin. Tungi qo‘rquv yoki boshqacha aytganda, uyqu dahshati — uyqu buzilishining bir turi. Bu holat odatda uyquning nREM bosqichida, bola uxlab qolganidan taxminan 90 daqiqa o‘tib yuz beradi. 2.5-3 yoshdan o‘smirlik davrigacha uchraydigan bu holatni ota-onalar ko‘pincha qo‘rqinchli tushlar bilan adashtiradilar. Agar farzandingizda tungi qo‘rquv xurujlari kuzatilsa, avvalo xotirjamlikni saqlang. Bunday xurujlar bir necha daqiqadan 20 daqiqagacha davom etishi mumkin. Bola tinchlangach, asta-sekin yana odatdagi uyqu holatiga qaytadi.') WHERE id = '076a6ccb-3a8e-4030-a673-d4b097978807';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Farzandingizning buyumlarni bir-biriga moslashtirish, muammolarni hal qilish va teginish orqali his etish qobiliyatini rivojlantiradigan qiziqarli mashg‘ulotni taklif qilamiz! 😊 Bugungi o‘yinimizning nomi: Xaltaning ichida nima bor?. Buning uchun sizga ichi ko‘rinmaydigan xalta, bolaning o‘yinchoqlari va uydagi ayrim kichik buyumlar kerak bo‘ladi. Buyumlarni xaltaga solib, og‘zini yoping. Xaltaning ichi ko‘rinmasligi juda muhim. Farzandingizdan qo‘lini xaltaga solib, undagi buyumlarning shaklini paypaslab ko‘rishini so‘rang. Undan nimani his qilayotgani va bu qanday buyum bo‘lishi mumkinligini so‘rang. Agar qiynalsa, buyum nima uchun ishlatilishi haqida kichik maslahatlar berishingiz mumkin. Anacan oilasi sifatida ushbu mashg‘ulot yordamida farzandingiz bilan ham mazmunli vaqt o‘tkazishingiz, ham juda yaxshi hordiq chiqarishingizga kafolat beramiz! 😊') WHERE id = 'ebefcc6f-edb8-4dbf-a46a-4627d454ebec';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Chaqalog‘ingizning maktabgacha bo‘lgan davrdagi rivojlanishini qo‘llab-quvvatlash uchun turli qiziqarli Montessori mashg‘ulotlaridan foydalanishingiz mumkin. Ko‘plab onalar ona bo‘lishdan oldin eshitmagan Montessori usulini uyda bemalol qo‘llash mumkin. Buning uchun qimmatbaho jihozlar kerak emas. Aksincha, Montessori mashg‘ulotlarida atrofingizdan oson topiladigan buyumlardan foydalaniladi. Bu usul chaqalog‘ingiz ulg‘ayish jarayonida kundalik hayotda uchratadigan, qiziqish bildiradigan va qanday ishlashini tushunishni istaydigan buyumlarni o‘yinga aylantiradi. Chaqalog‘ingiz bu buyumlar bilan o‘ynar ekan, aslida unga butun umri davomida kerak bo‘ladigan asosiy ko‘nikmalarni o‘rganadi. Masalan, oshxonada kundalik ishlaringizni bajarayotganda polga toza mato yozing va uning ustiga turli o‘lchamdagi choy, desert va ovqat qoshiqlarini qo‘ying. Chaqalog‘ingizdan bu qoshiqlarni kichigidan kattasiga, so‘ng aksincha tartibda terib chiqishini so‘rang. Mana, shunchalik oson! 😊') WHERE id = 'da312752-586a-4921-9553-2181d873da6f';
UPDATE public.baby_daily_info SET info_uz = COALESCE(info_uz, 'Ota-onalarni eng ko‘p chalg‘itadigan masalalardan biri — qo‘rqinchli tushlarni tungi qo‘rquvdan (uyqu dahshatidan) qanday farqlashdir. Uyqudagi qo‘rquv buzilishi deb tavsiflanadigan bu holat odatiy qo‘rqinchli tushlardan farq qiladi. Bunda bola uxlab qolganidan taxminan 90 daqiqa o‘tib, to‘satdan uyg‘onadi va qichqira boshlaydi. Chaqalog‘ingiz uyqu dahshatini boshdan kechirayotganini quyidagi belgilar orqali bilishingiz mumkin: u karavotida o‘rnidan turishi yoki maqsadsiz ravishda yugurishga urinishi mumkin. U juda qo‘rqib ketgan va hayratlangan ko‘rinadi, qichqirib, ma’nosiz tovushlar chiqaradi. Uni tinchlantirishga urinsangiz ham, u sizni tanimaydi, aytilgan gaplarni tushunmaydi va savollarga javob bermaydi. Yurak urishining tezlashishi, tez nafas olish va terlash kuzatilishi mumkin. Uyqu dahshati bolaga jismonan zarar yetkazmasa-da, muntazam takrorlansa, ruhiy ta’sir ko‘rsatishi mumkin. Bunday vaziyatda sizning vazifangiz bolaning o‘ziga jismoniy zarar yetkazishiga yo‘l qo‘ymaslikdir. Unga tegish yoki uni quchoqlash xurujning yanada kuchayishiga sabab bo‘lishi mumkin.') WHERE id = '649c5984-28bb-41d3-857b-4e0043a7b040';

