UPDATE public.first_aid_scenarios SET title_uz = COALESCE(title_uz, 'Cho‘kish'), description_uz = COALESCE(description_uz, 'Bola suvda cho‘kish xavfiga duch kelganda hayotini saqlab qoluvchi choralar. Har bir soniya muhim - darhol yordam ko‘rsating.') WHERE id = '3ffb8633-9a4a-4a5d-89c3-eef04f595887';
