UPDATE public.first_aid_scenarios SET title_uz = COALESCE(title_uz, 'Yiqilish'), description_uz = COALESCE(description_uz, 'Chaqaloq yoki bola yiqilib, jarohat olganida vaziyatni xotirjamlik bilan baholang. Bosh bilan urilgan hollarda alohida e’tibor talab etiladi.') WHERE id = 'e08bd13a-ef13-4cbd-9cbf-ae890a86ddd8';
