UPDATE public.maternity_guidelines SET title_uz = COALESCE(title_uz, 'Talab qilinadigan hujjatlar'), content_uz = COALESCE(content_uz, 'Dekret nafaqasini olish uchun zarur hujjatlar:

1. **Shifokor ma’lumotnomasi** - Tibbiyot muassasasidan homiladorlik to‘g‘risidagi ma’lumotnoma
2. **Vaqtinchalik mehnatga layoqatsizlik varaqasi** - Kasallik varaqasi
3. **Shaxsni tasdiqlovchi hujjat nusxasi**
4. **Mehnat daftarchasi nusxasi**
5. **Ariza** - Ish beruvchiga yozma murojaat') WHERE id = '0991ca4b-05cc-4d8d-a501-ba4395c57650';
UPDATE public.maternity_guidelines SET title_uz = COALESCE(title_uz, 'Muhim eslatmalar'), content_uz = COALESCE(content_uz, '**Bilishingiz kerak bo‘lgan ma’lumotlar:**

⚠️ O‘zini o‘zi band qilgan yoki norasmiy ishlaydigan shaxslar dekret to‘lovini ololmaydi, biroq ular 600 AZN miqdoridagi bir martalik nafaqani olish huquqiga ega.

⚠️ Dekret ta’tili davomida ish joyingiz saqlanadi.

⚠️ Bola 3 yoshga to‘lguniga qadar uni parvarishlash uchun ish haqi saqlanmaydigan ta’til olish huquqiga egasiz.

⚠️ Dekret ta’tili davomida sizni ishdan bo‘shatish mumkin emas.

📞 Qo‘shimcha ma’lumot uchun: DSMF ishonch telefoni - 142') WHERE id = '368a0305-9307-43d8-ada3-6c6cb95629e3';
UPDATE public.maternity_guidelines SET title_uz = COALESCE(title_uz, 'Kim murojaat qilishi mumkin?'), content_uz = COALESCE(content_uz, 'Dekret nafaqasini olish uchun quyidagi shartlar bajarilishi kerak:

• Ishlaydigan ayol bo‘lishingiz kerak (mehnat shartnomasi asosida)
• Kamida 12 oy davomida ijtimoiy sug‘urta badallarini to‘lagan bo‘lishingiz kerak
• Homiladorlik to‘g‘risida tibbiy ma’lumotnomangiz bo‘lishi kerak
• Ish beruvchida rasman ro‘yxatdan o‘tgan bo‘lishingiz kerak') WHERE id = '3e4b256c-52b8-482a-a8cb-0dc60e515146';
UPDATE public.maternity_guidelines SET title_uz = COALESCE(title_uz, 'Murojaat qilish jarayoni'), content_uz = COALESCE(content_uz, 'Dekret to‘lovini olish uchun bajariladigan qadamlar:

**1. Tibbiy ma’lumotnoma oling**
Homiladorlikning 30-haftasida (ko‘p homilali homiladorlikda 28-haftasida) shifokordan kasallik varaqasini oling.

**2. Ish beruvchiga murojaat qiling**
Kasallik varaqasi va arizani ish beruvchiga taqdim eting.

**3. Ish beruvchi DSMFga yuboradi**
Ish beruvchi hujjatlarni Davlat ijtimoiy himoya jamg‘armasiga taqdim etadi.

**4. To‘lovni oling**
Nafaqa 10 ish kuni ichida bank kartangizga o‘tkaziladi.') WHERE id = '45e9ae48-5d3e-47dc-a41d-0aece955a920';
UPDATE public.maternity_guidelines SET title_uz = COALESCE(title_uz, 'Bola tug‘ilganda beriladigan bir martalik nafaqa'), content_uz = COALESCE(content_uz, '**600 AZN miqdoridagi bir martalik tug‘ruq nafaqasi**

Bu nafaqa tug‘ruqdan keyin har bir bola uchun beriladi.

**Kim olishi mumkin:**
• Ozarbayjonning barcha fuqarolari
• Ishlash yoki ishlamasligidan qat’i nazar

**Qanday olish mumkin:**
1. ASAN xizmatiga murojaat qiling
2. Tug‘ilganlik haqidagi guvohnomani taqdim eting
3. Shaxsni tasdiqlovchi hujjatingiz nusxasini bering
4. Bank hisob raqamingiz ma’lumotlarini ko‘rsating

**Muddat:** Tug‘ruqdan keyin 12 oy ichida murojaat qilish kerak.') WHERE id = '5f8ed8eb-e323-498e-95d7-5c63d9a1ae79';
UPDATE public.maternity_guidelines SET title_uz = COALESCE(title_uz, 'Hisoblash tartibi'), content_uz = COALESCE(content_uz, 'Dekret to‘lovi quyidagicha hisoblanadi:

**Formula:**
To‘lov = O‘rtacha kunlik ish haqi × Ta’til kunlari

**O‘rtacha kunlik ish haqi:**
Oxirgi 12 oydagi jami ish haqi ÷ 365

**Ta’til muddati:**
• Me’yorda kechayotgan homiladorlik: 126 kun (70+56)
• Og‘ir tug‘ruq: 140 kun (70+70)
• Ko‘p homilali homiladorlik: 194 kun (84+110)

**Eslatma:** To‘lov to‘liq miqdorda, soliq ushlab qolinmasdan beriladi.') WHERE id = 'd271f9d1-fb1c-4607-ad1e-186f4b2de9e3';

