-- ── mommy_daily_messages → uz (1460 sətir) ──
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, ona bo‘lganingizga bir hafta bo‘ldi va qiyinchiliklarga qaramay, bu kunlarni muvaffaqiyatli yengib o‘tdingiz! Oynaga qaraganingizda qorningiz hali to‘liq qaytmaganini, sochlaringiz taralmaganini ko‘rishingiz mumkin, ammo siz bir mo‘jizani ulg‘aytiryapsiz va shu holatingizda ham juda go‘zalsiz. Bugundan boshlab chaqaloq uyg‘oq paytida, nazoratingiz ostida uni qisqa muddatga (1-2 daqiqa) qorni bilan yotqizishni (tummy time) boshlashingiz mumkin. Bu kichik mashq uning bo‘yin va orqa mushaklarini mustahkamlaydi, gaz sanchiqlarini yengillashtirishga yordam beradi hamda kelajakdagi jismoniy rivojlanishiga zamin yaratadi.') WHERE id = '33d098f8-b80c-478c-bb61-a7d57cd72e57';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning terisi yoki ko‘z oqi biroz sarg‘ayganini sezishingiz mumkin; bu fiziologik sariqlik bo‘lib, aksariyat hollarda tez-tez emizish orqali organizmdan chiqib ketadi. Ammo sariqlik oyoqlar tomon tarqalsa va chaqaloq juda holsiz bo‘lib qolsa, albatta shifokoringiz bilan maslahatlashing. Shuningdek, xonani shamollatishdan qo‘rqmang; "qirqi chiqmagan, havo tegishi mumkin emas" degan fikr shunchaki afsona, toza havo sizning ham, chaqaloqning ham miyasi uchun muhim. Derazani ochib, xonani shamollating yoki imkon bo‘lsa, chaqaloqni ob-havoga mos kiyintirib, qisqa muddatga toza havoga olib chiqing (agar shifokor ruxsat bergan bo‘lsa).') WHERE id = '55de4073-ef7d-4cff-84f4-bf2b8f830118';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Buvilarimiz "bola to‘g‘ri o‘ssin" deb uni qattiq yo‘rgaklashni ma’qul ko‘rishlari mumkin, ammo zamonaviy tibbiyot chaqaloqning chanoq-son bo‘g‘imlari sog‘lom rivojlanishi uchun oyoqlari erkin harakatlanishi kerakligini isbotlagan. Agar chaqaloq o‘z qo‘l-oyoqlarining harakatidan cho‘chib uyg‘onsa, faqat qo‘llarini yengilgina yo‘rgaklashingiz mumkin (yarim yo‘rgak), lekin oyoqlari "qurbaqa" holatida erkin turishi uchun albatta sharoit yarating. Chaqaloqni qattiq o‘rab, harakatsiz saqlash uning qon aylanishi va mushaklarining rivojlanishiga salbiy ta’sir qilishi mumkin. Uni erkin qo‘ying, qo‘l va oyoqlari bilan dunyoni kashf etsin.') WHERE id = '94a133da-1fcc-4ffe-a24b-b9755a414c0b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mana 10 kundirki, butun diqqatingiz va xayolingiz chaqaloqda, ammo bugun hech bo‘lmasa 15-20 daqiqani faqat o‘zingizga ajratishga harakat qiling. Iliq dush qabul qiling, sevimli musiqangizni tinglang, teringizni parvarish qiling yoki shunchaki derazadan qarab, xayol suring. Tiklanish jarayoni tezlashishi uchun chanoq tubi mushaklarini asta-sekin his qilishga harakat qiling (Kegel mashqlarining eng yengil shakli), ammo og‘ir jismoniy mashqlar uchun hali juda erta. Tanangizga quloq tuting, uni qadrlang va unutmang: siz farzandingiz uchun eng katta tayanchsiz, sog‘lom va ruhan kuchli bo‘lishingiz esa unga beradigan eng katta sovg‘angizdir.') WHERE id = '4ba69869-3aaa-471c-bba8-3e9678c5f231';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning kindik qoldig‘i qurib tushgan yoki tushish arafasida bo‘lishi mumkin; bu mutlaqo tabiiy jarayon va kindik o‘rnida ozgina qon dog‘ini ko‘rsangiz, qo‘rqmang. Kindik qoldig‘i tushgach ham bu sohani quruq va toza saqlash muhim, chunki nam muhit bakteriyalar ko‘payishi uchun qulaydir. Ba’zan onalar kindikning "tashqariga bo‘rtib" qolishidan xavotirlanishadi, ammo qorin mushaklari mustahkamlangani sari u ko‘pincha o‘z holiga keladi; shu sababli kindikka tanga bog‘lash yoki uni qattiq bosib qo‘yish kabi eski usullardan saqlaning. Agar kindik atrofida qizarish, yoqimsiz hid yoki yiringni sezsangiz, darhol shifokoringizga xabar bering, aks holda tabiat o‘z ishini bajarishiga imkon bering.') WHERE id = '4412d0c9-03dd-43c8-bb46-87b4fecadda2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Shu kunlarda chaqaloq go‘yo hech to‘ymayotgandek tinimsiz, ba’zan har soatda emishni xohlayotganini sezishingiz mumkin; tibbiyotda bu "jadal o‘sish davri" (growth spurt) deb ataladi. Onalar ko‘pincha buni "sutim kamaydi, bolam och qoldi" deb o‘ylab, xavotirga tushadilar va sun’iy oziqlantirishga o‘tishga shoshiladilar. Aslida esa bu chaqaloqning ortib borayotgan ehtiyojini qondirish uchun tanangizga "ko‘proq sut ishlab chiqar" degan signal berish usulidir. Sabrli bo‘ling, bu vaqtinchalik holat va odatda bir-ikki kun davom etadi; shunchaki chaqaloqning talabiga ko‘ra uni tez-tez emizing va bag‘ringizga bosing. Bu davrda ko‘proq suv ichish va dam olish sizga kuch beradi. Unutmang, sut miqdori chaqaloqning ehtiyojiga mos ravishda tabiiy ravishda ko‘payadi.') WHERE id = '8aab5133-1153-4e9f-bfa1-1ddc76290148';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kechki payt chaqaloqning hech qanday sababsiz yig‘lashi, oyoqlarini qorniga tortib olishi va qizarib ketishi qorin dam bo‘lishi bilan bog‘liq og‘riqlar (kolika) boshlanganini ko‘rsatishi mumkin; bu uning ovqat hazm qilish tizimi hali to‘liq shakllanmaganidan darak beradi. Xavotir olmang, bu og‘riqlar chaqaloqning sog‘lig‘ida muammo borligini anglatmaydi, unga shunchaki biroz yordam kerak; qornini soat mili yo‘nalishida sekin uqalash yoki oyoqlarini "velosiped" harakatidek qildirish uning yengil tortishiga yordam beradi. Chaqaloqni qorni bilan bilagingiz ustiga yotqizib ko‘tarib yurish (yo‘lbars usuli) ham og‘riqlarni yengillashtirishi mumkin. Sabrli bo‘ling, bu davr "tugamaydigan tunlar"dek tuyulishi mumkin, ammo 3-4 oydan keyin bu og‘riqlar butunlay yo‘qoladi.') WHERE id = 'bcbaede0-1b13-4f10-af2e-89c520ee8eac';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, chaqalog‘ingiz roppa-rosa 2 haftalik bo‘ldi! Bu davrda shifokorlar odatda chaqaloqlarga D vitamini tomchilarini buyuradilar, chunki ona suti juda foydali bo‘lsa-da, undagi D vitamini miqdori odatda yetarli bo‘lmaydi va quyosh nuri ham har doim kifoya qilmasligi mumkin. Suyaklar to‘g‘ri rivojlanishi va raxitning oldini olish uchun vitaminni shifokoringiz buyurgan dozada berishni unutmang. Shuningdek, bu shifokorning dastlabki ko‘rigi uchun ayni muddao; chaqaloqning vazn qo‘shishini tekshirtirish va uning rivojlanishi haqidagi savollaringizni berish uchun pediatr qabulini rejalashtirishingiz mumkin. Siz hammasini a’lo darajada uddalayapsiz, dastlabki qiyin bosqichni ortda qoldirdingiz!') WHERE id = '6f0bc18f-ecc7-4ad9-915b-db7cdf9694f7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bugun e’tiborni biroz yana o‘z tanangizga qarataylik; tug‘ruqdan keyingi ajralmalar (loxiya) rangini o‘zgartirib, ochroq, sarg‘ish yoki oq tusga kira boshlashi kerak. Agar qon ketishi to‘satdan kuchaysa yoki yoqimsiz hid paydo bo‘lsa, bu tanangizning sizga "juda ko‘p charchayapsiz" yoki "infeksiya bor" degan ishorasi bo‘lishi mumkin; shu sababli og‘ir narsalarni ko‘tarishdan qat’iyan saqlaning. Shaxsiy gigiyenangizga alohida e’tibor bering, tez-tez dush qabul qilish ham jismoniy tozalik, ham ruhiy tetiklik uchun muhim. To‘liq tiklanishingizga hali bir necha hafta ketishini unutmang, shuning uchun o‘zingizni hali butunlay tetik his qilmasangiz ham, tanangizga vaqt bering va mehr bilan munosabatda bo‘ling.') WHERE id = '924b5e58-de0f-4e99-ae9e-3a1b97775596';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsiz uyqu qoidalari chaqaloq hayoti uchun nihoyatda muhim; chaqaloqni doimo chalqancha, qattiq to‘shakda uxlatishingiz kerak. Buvilar tavsiya qiladigan yumshoq yostiqlar, qalin ko‘rpalar yoki beshik ichidagi o‘yinchoqlar chaqaloq uchun bo‘g‘ilib qolish xavfini tug‘dirishi mumkin, shuning uchun beshikni imkon qadar sodda va bo‘sh saqlang. "Boshlari tekis bo‘lsin" deb ishlatiladigan maxsus ortopedik yostiqlar ko‘pincha kerak emas, chunki chaqaloq boshini erkin harakatlantira olishi lozim. Xona haroratini nazorat qilib turing (20-22 daraja ideal), chaqaloqni haddan tashqari qalin kiyintirmang, chunki ortiqcha qizib ketish ham uyqu paytida xavf tug‘diradi.') WHERE id = '00815f0c-e81b-4156-a3e1-eda10e9b02f3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni uyg‘oq paytida qorni bilan yotqizish (tummy time) muhimligini eshitgan bo‘lsangiz kerak, ammo chaqalog‘ingizga bu umuman yoqmasligi va u darhol yig‘lab yuborishi mumkin. Bu tabiiy holat, lekin taslim bo‘lmang; kuniga bir necha marta, har safar atigi 1-2 daqiqadan mashq qildirish uning bo‘yin, yelka va qo‘l mushaklarini mustahkamlash uchun juda muhim. Shuningdek, bu boshning orqa qismi yassilashishining (plagiosefaliya) oldini olishning eng tabiiy usulidir. Mashg‘ulotni qiziqarli qilish uchun uning oldiga ko‘zgu yoki oq-qora kartochkalar qo‘yishingiz, hatto o‘zingiz ham yoniga yerga yotib, u bilan ko‘z orqali aloqa qilishingiz mumkin.') WHERE id = '442f3095-2fe9-4071-b81b-22bb923583fd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Chillasi chiqmagan bola tashqariga olib chiqilmaydi" degan gap shunchaki eskirgan afsona; agar ob-havo yaxshi bo‘lsa va chaqaloq sog‘lom bo‘lsa, toza havo har ikkingizga ham doridek ta’sir qiladi. Uydagi dim havo, chang va bakteriyalar tashqaridagi toza havodan ko‘ra zararliroq bo‘lishi mumkin; faqat odam gavjum savdo markazlari va yopiq joylardan uzoqroq yuring. Chaqaloqni kiyintirganda, o‘zingiz kiyganingizdan atigi bir qavat ko‘proq kiyim kiydirish kifoya, uni "karamdek" o‘rab tashlash terlashiga va kasal bo‘lishiga sabab bo‘lishi mumkin. Qisqa sayr kayfiyatingizni ko‘taradi, chaqaloqning esa yanada qattiqroq uxlashiga yordam beradi.') WHERE id = '0f0e26dc-de3c-4b42-ba38-4351bd00e821';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xush kelibsiz, aziz ona! Hayotingizning eng yangi va, ehtimol, eng hayajonli sahifasi bugun ochilmoqda. Hozir siz uchun eng muhimi — dam olish va chaqalog‘ingiz bilan ilk jismoniy aloqani o‘rnatish; uy ishlari, telefon qo‘ng‘iroqlari va mehmonlar kutib turishi mumkin. Shuni bilingki, dastlab keladigan quyuq, sarg‘ish sut (og‘iz suti) miqdoran oz bo‘lsa-da, uning tarkibi mo‘jizaviy bo‘lib, chaqalog‘ingiz uchun ilk emlash vazifasini bajaradi. Sutim kam deb xavotir olmang, chunki chaqalog‘ingizning oshqozoni hozircha gilosdek va shu tomchilar unga to‘liq yetadi. O‘zingizni qahramondek tutishga urinmang, og‘riq va charchoq his qilishingiz mutlaqo tabiiy. Shunchaki yoting, chaqalog‘ingizning hidini tuyib, iliqligini his qiling va bu ondan zavqlaning, chunki orangizdagi rishtaning poydevori aynan hozir qo‘yilmoqda.') WHERE id = 'ced035b3-8303-4f5d-95fd-7e29e2539509';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tanangiz 9 oy davomida ajoyib ishni bajardi, endi esa ichki a’zolaringiz asta-sekin o‘z joyiga qayta boshlaydi. Ayniqsa, emizish paytida qorinning pastki qismida sanchiqlarni his qilishingiz mumkin. Xavotir olmang, bu bachadon qisqarib, avvalgi hajmiga qaytayotganining ijobiy belgisidir. Jamiyatda tarqalgan "sutim kam, bola to‘ymayapti, shuning uchun yig‘layapti" kabi noto‘g‘ri fikrlarga berilmang. Chaqalog‘ingiz faqat och bo‘lgani uchun emas, balki hidingizni tuyish, yurak urishingizni eshitish va o‘zini xavfsiz his qilish uchun ham tez-tez ko‘krak so‘rashi mumkin. Unga shu ishonchni bering: bag‘ringizga bosing va tez-tez emizing. Unutmang, chaqaloq qancha ko‘p emsa, sutingiz shuncha ko‘payadi.') WHERE id = 'f5dc2c0a-cfb4-4205-ad61-5a643545c576';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Shu kunlarda sut bezlaringiz sutga to‘la boshlashi (sutning ko‘p kelishi) mumkin, bu esa ko‘krakda og‘irlik va issiqlik hissini keltirib chiqaradi. Shu bilan birga, tanangizdagi gormonlar darajasi keskin o‘zgargani sababli hech qanday sababsiz o‘zingizni g‘amgin, yig‘loqi yoki jahldor his qilishingiz mumkin; tibbiyotda bu holat "Baby blues" deb ataladi. Bunday hislar sizning "yomon ona" yoki uquvsiz ekaningizni anglatmaydi, bu shunchaki fiziologik va vaqtinchalik jarayon. Ko‘z yoshlaringizni tiymang, yig‘laggingiz kelsa, yig‘lab yengil torting va bu haqda yaqinlaringiz bilan gaplashishdan tortinmang. Siz yolg‘iz emassiz, minglab onalar bu o‘tish davrini xuddi siz kabi boshdan kechiradi. Chuqur nafas oling va shunchaki vaqtga qo‘yib bering.') WHERE id = '04d25f7c-e375-4514-ac39-dc2728da56e3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Quvvatingizni tiklash uchun ovqatlanishingizga alohida e’tibor berishingiz kerak, ammo "sovuq bo‘ladi", "meva yemang", "suv ichmang" kabi eskirgan taqiqlarni bir chetga suring. Rang-barang, vitaminlarga boy ovqatlanish va ko‘p suyuqlik ichish sutingiz sifatidan ko‘ra, o‘z jismoniy kuchingizni tiklash va ruhiy tetikligingiz uchun muhimroqdir. Chaqaloqning kindigiga kelsak, uni spirt bilan kuydirish yoki o‘rab qo‘yish shart emas. Shunchaki quruq va toza turishiga e’tibor bering, taglikni taqayotganda kindik qismini ochiq qoldiring, shunda unga havo tegadi; havo bilan aloqa bitishni tezlashtiruvchi eng yaxshi vositadir.') WHERE id = '5cdec801-b16c-449e-bf65-9a37a9e133f1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kecha bilan kunduz almashib, uyqusizlik sezila boshlaydigan kunlarga xush kelibsiz, kuchli ona! Atrofdagilar orasida "bolani qo‘lga o‘rgatmang" deydiganlar bo‘lishi mumkin, ammo shuni bilingki, dastlabki oylarda chaqaloqni "erkalatib yuborish" mumkin emas. U sizga muhtoj, uni bag‘ringizda ko‘tarib yurish va teri bilan teri aloqasi ham uning miyasi rivojlanishi, ham sutingiz ko‘payishi uchun eng samarali usullardandir. Uy ishlari qochib ketmaydi, idishlar yuvilmay qolsa ham mayli, ammo sizning uyqu va dam olishingiz hamma narsadan muhimroq. Chaqalog‘ingiz uxlashi bilan siz ham ko‘zingizni yumib, dam olishga harakat qiling. Hatto 15 daqiqalik uyqu ham sizga quvvat beradi.') WHERE id = '726dd7ee-a857-41fc-aad0-622f7b5ddf29';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hamma ishni yolg‘iz bajarishingiz va "super ona" obrazini yaratishingiz shart emas; yordam so‘rash zaiflik emas, aksincha, kuchlilik belgisidir. Turmush o‘rtog‘ingiz, onangiz yoki yaqinlaringizdan muayyan ishlarda yordam so‘rang, masalan, ovqat olib kelishlarini yoki siz dush qabul qilayotganingizda chaqaloqqa qarab turishlarini iltimos qiling. O‘zingizga qarash, yuvinib-taranish va bir piyola issiq choy ichish xudbinlik emas, balki onalik vazifalaringizni yanada yaxshiroq bajarishingiz uchun zaruratdir. Unutmang, baxtli va dam olgan ona — baxtli chaqaloq demakdir. Shuning uchun zimmangizdagi yukni boshqalar bilan bo‘lishishdan tortinmang.') WHERE id = '1ddced84-3654-418b-9996-21c50802a72f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ikkinchi oyga xush kelibsiz! Endi siz va chaqalog‘ingiz bir-biringizni yaxshiroq taniyapsiz, hayotingizda muayyan bir "ritm" shakllana boshladi. E’tibor bering, biz "rejim" emas, "ritm" deyapmiz, chunki chaqaloq hali soat bo‘yicha yashashga tayyor emas, ammo uxlash, ovqatlanish va uyg‘oq qolish ketma-ketligi shakllanmoqda. Bu davrda qat’iy jadvallar tuzishga urinmang, shunchaki chaqaloqning uyqu belgilarini (esnash, ko‘zlarini ishqalash) kuzating va uni haddan tashqari charchatmasdan uxlatishga harakat qiling. Agar hammasi hali ham tartibsizlikdek tuyulsa, xavotir olmang; bu tartibsizlik ichida ham katta bir qonuniyat bor va siz hammasini a’lo darajada uddalayapsiz.') WHERE id = '014f9c15-8f59-4b13-b689-2c5db7a165c4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni qorni bilan yotqizganingizda (tummy time), u boshini bir necha soniyaga bo‘lsa ham ko‘tarishga urinayotganini ko‘rishingiz mumkin; bu uning bo‘yin mushaklari kuchayayotganining ilk belgisidir. Bu mashqlarni yanada qiziqarli qilish uchun uning oldiga rangli o‘yinchoq qo‘ying yoki shunchaki ro‘parasiga yotib, u bilan gaplashing. Agar u hali boshini ko‘tara olmasa, vahimaga tushmang, har bir bola o‘z sur’atida rivojlanadi. Shunchaki sabr bilan davom eting, bu kichik urinishlar kelajakda uning emaklashi va yurishi uchun poydevor bo‘ladi.') WHERE id = 'edef290e-ee82-45c6-adef-de36a35e9688';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Shu paytgacha chaqalog‘ingizning uyqusida jilmayganini ko‘rgan bo‘lishingiz mumkin, buni xalq orasida "farishtalar bilan o‘ynayapti" deyishadi (aslida bu refleks), ammo endi "ijtimoiy tabassum" davri yaqinlashmoqda. Chaqalog‘ingiz sizga qarab, ovozingiz yoki yuz ifodangizga ongli ravishda jilmayishi mumkin; bu shunchaki yuz ifodasi emas, balki uning sizga "sizni taniyman va yaxshi ko‘raman" deyishining ilk usulidir. U bilan gaplashayotganda ko‘zlariga qarang va jilmaying, u ham sizga javob berishga harakat qiladi. Bunday o‘zaro muloqot uning hissiy intellekti rivojlanishi uchun eng kuchli rag‘batdir.') WHERE id = '33d46eab-d81b-465a-acf9-3431f678ba0a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ba’zan xonaga kirib, "men bu yerga nega kelgandim?" deb o‘ylab qolasizmi yoki eng oddiy so‘zlarni eslay olmay qolasizmi? Buni hazil tariqasida "Ona miyasi" (Mom brain) deb atashadi va bu mutlaqo real fiziologik holatdir. Uyqusizlik va gormonal o‘zgarishlar miya diqqat markazini o‘zgartiradi, go‘yo miya barcha resurslarini chaqaloqqa yo‘naltirib, boshqa "ahamiyatsiz" narsalarni o‘chirib tashlaydi. O‘zingizni "aqlim pasayib qoldi" deb his qilmang, bu vaqtinchalik xiralikdir. Muhim ishlarni yon daftaringizga yoki telefoningizga yozib borish orqali bu davrni yengilroq o‘tkazishingiz mumkin; miyangiz tez orada avvalgi teranligiga qaytadi.') WHERE id = 'd8c08c2a-72db-44c1-9834-75d63110369c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning ko‘rish qobiliyati rivojlanmoqda va u endi harakatlanayotgan narsalarni ko‘zlari bilan kuzatishni (tracking) boshlashi mumkin. Barmog‘ingizni yoki rangli o‘yinchoqni uning yuzidan 20-30 sm masofada tutib, asta-sekin o‘ngga va chapga harakatlantiring; u nigohi bilan kuzatishga harakat qiladi. Bu oddiy o‘yin uning ko‘z mushaklari va miya-ko‘z muvofiqligini rivojlantiradi. Agar u darhol javob bermasa, charchagan bo‘lishi mumkin, uni majburlamang va boshqa payt yana sinab ko‘ring.') WHERE id = '8bc192a0-eebe-4dd4-8ce3-ca56d11958b8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz hali gapira olmasa-da, u ajoyib tinglovchidir; kun davomida qilayotgan har bir ishingizni unga aytib turishingiz ("hozir tagligingizni almashtiramiz", "qarang, bu deraza") uning kelajakdagi nutq rivoji uchun juda muhimdir. Tadqiqotlar shuni ko‘rsatadiki, ota-onasi ko‘p gaplashadigan bolalarning kelajakda so‘z boyligi kengroq bo‘ladi. Unga savollar bering va go‘yo javob berayotgandek biroz jim turib kuting (masalan: "Sutingizni ichdingizmi? Barakalla!"). Bu "dialog" unga muloqot qoidalarini o‘rgatadi va orangizdagi rishtani mustahkamlaydi.') WHERE id = '99451123-a037-4f29-a96e-5e981ce03fe5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jamiyatimizda keng tarqalgan "pomidor yema, chaqaloqning badaniga toshma chiqadi", "yasmiq yema, chaqaloqning qorni dam bo‘ladi" kabi ovqatlanish taqiqlari sizni charchatgan bo‘lsa, bilingki, zamonaviy tibbiyot bu fikrlarni tasdiqlamaydi. Siz iste’mol qilgan ovqatdagi gaz bevosita sutga o‘tmaydi; sut oshqozondagi gazdan emas, qondan hosil bo‘ladi. Agar muayyan mahsulotni iste’mol qilganingizdan keyin chaqaloqda haqiqatan ham bezovtalik kuzatilmasa (bu juda kam hollarda, sigir suti oqsiliga allergiya bo‘lganda uchraydi), o‘zingizni behuda parhezga solmang. Vitaminlar va oqsilga boy, xilma-xil ovqatlanishingiz ham sut sifati, ham ruhiy salomatligingiz uchun och qolishdan ko‘ra ancha foydali.') WHERE id = '0f643a6c-2b94-498e-845b-b4547838a7e6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni doim qo‘lda ko‘tarib yurish belingizni og‘ritishi mumkin, shuning uchun to‘g‘ri tanlangan sling yoki ergo-ryukzak (kenguru emas!) sizning eng yaxshi yordamchingiz bo‘la oladi. "Bola qo‘lga o‘rganib qoladi", "umurtqasi qiyshayadi" kabi gaplarga e’tibor bermang; aksincha, chaqaloqning oyoqlari "M" harfi shaklida (qurbaqaniki kabi) turadigan ergonomik tashuvchilar uning chanoq-son bo‘g‘imlari rivojlanishi uchun juda foydali. Bu usul chaqaloqqa ona qornidagi tor va xavfsiz muhitni eslatib, uni tinchlantiradi, sizning esa ikkala qo‘lingiz ham bo‘sh qoladi — uy ishlarini qilishingiz yoki shunchaki bemalol choy ichishingiz mumkin. Yaqinlik hissi har ikkingizga ham serotonin (baxt gormoni) baxsh etadi.') WHERE id = 'a2fbf383-d8f0-4347-a3ef-d35f626ab799';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uyingizga kelgan mehmonlarning chaqaloqni o‘pishni yoki uni qo‘ldan qo‘lga olib ko‘tarishni istashi sizni bezovta qilsa, "yo‘q" deyishdan va chegaralar belgilashdan aslo tortinmang. Chaqaloqning immuniteti hali juda zaif, kattalar uchun oddiy bo‘lgan uchuq virusi (gerpes) esa chaqaloq hayotiga xavf tug‘dirishi mumkin. Mehmonlardan qo‘llarini yuvishlarini, kasal bo‘lsalar kelmasliklarini hamda chaqaloqning yuzi yoki qo‘llaridan o‘pmasliklarini xushmuomalalik bilan so‘rash — sizning eng tabiiy huquqingiz. Agar kimdir bundan ranjisa, bu ularning muammosi; sizning asosiy vazifangiz boshqalarning ko‘ngliga qarash emas, chaqaloqni himoya qilishdir.') WHERE id = '7b5d5e0e-5e56-4eb3-b899-1d95dce7cd83';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, ajoyib Ona! Bugun chaqalog‘ingiz roppa-rosa 1 oylik bo‘ldi! Shu bir oy davomida qancha qiyinchiliklarni yengib o‘tganingizni, uyqusiz qolganingizni, ammo qanchalik matonatli bo‘lganingizni eslab, o‘zingiz bilan faxrlaning. Ayni paytda chaqaloqni har oylik shifokor ko‘rigidan o‘tkazish (vazni va bo‘yini o‘lchash) vaqti ham keldi; u qo‘shgan har bir gramm — mehnatingiz samarasidir. Bugun chaqalog‘ingizning bir oylik esdalik suratini oling, sanalarni qayd eting va bu kichik yubileyni, hatto bir bo‘lak tort bilan bo‘lsa ham, albatta nishonlang. Vaqt juda tez o‘tadi, bu lahzalarni xotirada muhrlash kelajakda eng go‘zal esdalikka aylanadi.') WHERE id = '520fba19-0b3a-4361-9ce1-dac3a718ebb0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni cho‘miltirayotganda qulog‘iga suv kirib ketishidan qo‘rqsangiz, xavotir olmang; quloq pardasi ichki quloqni suvdan himoya qiladi va suv kirishi odatda jiddiy muammo tug‘dirmaydi (agar quloq pardasi shikastlanmagan bo‘lsa). Cho‘milish chaqaloq uchun nafaqat tozalanish, balki zavqlanish va bo‘shashish usuli hamdir; agar u suvni yaxshi ko‘rsa, uni har oqshom bir xil vaqtda, uxlashdan oldin cho‘miltirish ajoyib uyqu marosimiga aylanishi mumkin. Iliq suv mushaklarni bo‘shashtiradi, tinchlantiradi va chaqaloqqa "endi tun bo‘ldi, uxlash vaqti keldi" degan signalni beradi. Cho‘miltirgandan keyin uni iliq sochiqqa o‘rab, yengil massaj qilish uyquga ketishini osonlashtiradi.') WHERE id = 'd1cd229a-65ce-4753-a5dc-ce53e13d2100';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tug‘ruqdan keyingi ilk oy o‘tgach, "Baby blues" deb ataladigan g‘amgin va o‘ta ta’sirchan davr odatda yakunlangan bo‘lishi kerak; agar siz hanuz o‘zingizni doimo g‘amgin, umidsiz, charchagan his qilsangiz yoki chaqaloqqa nisbatan befarq bo‘lib qolsangiz, bunga jiddiy e’tibor bering. Bu tug‘ruqdan keyingi depressiya (TKD) bo‘lishi mumkin. Bu aslo sizning aybingiz, injiqligingiz yoki zaifligingiz emas, balki gormonal va kimyoviy muvozanatning buzilishidir. "Men onaman, chidashim kerak" deb o‘zingizni ayblamang; agar ichingizdagi bo‘shliq hissi yo‘qolmasa, albatta shifokoringiz yoki psixolog bilan gaplashing. Sizning ruhiy salomatligingiz chaqaloqning jismoniy salomatligi kabi, balki undan ham muhimroqdir.') WHERE id = '792d4a29-1f99-4846-89d2-54738a980f78';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning tirnoqlari qog‘ozdek yupqa, ammo ustaradek o‘tkir bo‘lishi mumkin. U beixtiyor harakatlar bilan yuzini tirnab, o‘ziga shikast yetkazishi ehtimoli bor. Tirnoqlarini olish juda qo‘rqinchli tuyulishi mumkin, ammo buning eng oson yo‘li — chaqaloq qattiq uxlayotganida maxsus bolalar qaychisi bilan ehtiyotkorlik bilan kesishdir. Ba’zi onalar qo‘lqop kiydirishni afzal ko‘radi, biroq chaqaloq dunyoni qo‘llari orqali his qilib o‘rganadi. Qo‘llarining yopiq turishi uning rivojlanishini sekinlashtirishi va o‘zini tinchlantirish mexanizmini buzishi mumkin. Qo‘rqmang, tasodifan kichik kesik paydo bo‘lsa ham, uni toza paxta bilan bosib turish kifoya — tezda bitib ketadi. Dadil bo‘ling!') WHERE id = '3eb8e784-2dc2-4db5-bcf8-7391a821ce01';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tug‘ruqdan keyingi bu davrda ba’zan o‘zingizni dunyodan uzilib qolgan, faqat emizadigan va taglik almashtiradigan bir "robot"dek his qilishingiz mumkin. Ammo unutmang: siz nafaqat onasiz, balki do‘st, umr yo‘ldosh va o‘z qiziqishlariga ega alohida shaxssiz. Bugun chaqaloq uxlaganida dugonangizga qo‘ng‘iroq qiling, ijtimoiy tarmoqlarda qiziqarli biror narsa o‘qing yoki shunchaki derazadan qarab, "men shu yerdaman va hammasi joyida" deng. Ruhiy salomatligingiz jismoniy salomatligingizdan kam ahamiyatli emas. Agar o‘zingizni yolg‘iz va cheklangandek his qilsangiz, bu tuyg‘ularni yaqinlaringiz bilan bo‘lishing — gaplashish yengil tortishingizga yordam beradi.') WHERE id = 'e0cd0853-270f-4ca4-a662-76294120406b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning shu kunlarda go‘yo sutga hech to‘ymayotgandek tutishi, tinmay ko‘krak so‘rashi va uyqusi buzilishi sizni qo‘rqitmasin. Bu, katta ehtimol bilan, "3-haftadagi o‘sish sakrashi"dir (growth spurt). Bu davrda chaqaloq organizmi tez o‘sadi, shu sababli unga ko‘proq energiya kerak bo‘ladi. Sizning tanangiz esa bu talabga moslashish uchun ko‘proq sut ishlab chiqarishga harakat qiladi. Onalarning bu bosqichdagi eng katta xatosi — "sutim kamayib ketdi" deb, sun’iy ozuqaga o‘tishdir. Aksincha, bu vaqtinchalik inqiroz bo‘lib, yagona yechim — soatga qaramasdan, chaqaloq istaganicha emizishdir. Sabrli bo‘ling, bu zo‘riqish odatda 24-48 soat ichida o‘tib ketadi va sut miqdori yana me’yorlashadi.') WHERE id = '2fdd98da-1e6c-412b-96b1-b850d42327b4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning silliq, ipakdek yuzida to‘satdan mayda qizil toshmalar yoki husnbuzarlar paydo bo‘lishi mumkin. Darhol "Men nima yedimki, bolam shunday bo‘lib qoldi?" deb o‘zingizni ayblamang. Bu "yangi tug‘ilgan chaqaloqlar aknesi" deb ataladi va homiladorlik vaqtida sizdan chaqaloqqa o‘tgan gormonlarning uning organizmidan chiqib ketish jarayonidir. Bu toshmalar allergiya emas, shu sababli ularni siqish, spirt bilan artish yoki turli kremlar surtish qat’iyan mumkin emas — bu faqat teriga zarar yetkazishi mumkin. Yuzini har kuni shunchaki iliq qaynatilgan suv bilan artish kifoya, toshmalar bir necha hafta ichida o‘z-o‘zidan yo‘qoladi.') WHERE id = 'c3f99f3b-1467-413f-94c0-72c3e11f5099';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kechqurun boshlanib, soatlab davom etadigan mashhur yig‘i xurujlari (kolika) bu davrda eng yuqori darajaga yetishi mumkin. Bunday paytda chaqaloqni tinchlantirish uchun "oq shovqin"dan (white noise) foydalanib ko‘ring. Chaqaloq ona qornida doimo qon aylanishi va ichki a’zolar tovushlarini eshitgan. Shu sababli fen, changyutgich shovqini yoki telefondagi "oq shovqin" ilovalarining ovozi unga tanish tuyulib, xavfsizlik hissini beradi. Chaqaloqni mahkam bag‘ringizga bosib, bir maromda tebratgan holda bu tovushlarni eshittirish uning asab tizimini tinchlantirishi mumkin. Unutmang, bu yig‘ilar sizning aybingiz emas, ular shunchaki chaqaloqning hali to‘liq rivojlanmagan hazm qilish tizimi reaksiyasidir.') WHERE id = '401736ab-8891-41f0-a7a6-17ce6782e7e4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning ko‘rish qobiliyati endi rivojlana boshlaydi, ammo u hali ranglarni to‘liq ajrata olmaydi va dunyoni asosan xira soyalar ko‘rinishida ko‘radi. Uning diqqatini jalb qilish va miya rivojlanishini qo‘llab-quvvatlash uchun oq-qora kartochkalar yoki keskin kontrastli o‘yinchoqlardan foydalanishingiz mumkin. Ularni chaqaloqning yuzidan taxminan 20-30 sm masofada tutish kerak. Chaqaloq bu kartochkalarga tikilib, ularni diqqat bilan kuzatayotganini ko‘rasiz. Bu oddiy o‘yin nafaqat uning ko‘z mushaklarini mashq qildiradi, balki miya hujayralari (neyronlar) o‘rtasida yangi aloqalar paydo bo‘lishiga ham yordam beradi.') WHERE id = '6acb903b-f503-4e0a-bf5a-5cedae1d83e4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq massaji — qorin dam bo‘lishi va gaz og‘riqlarini kamaytirish, shuningdek, uni tinchlantirishning ajoyib usuli. Qo‘llaringizga ozgina tabiiy bolalar moyi surting, xona iliq ekaniga ishonch hosil qiling va chaqaloqning oyoqlaridan boshlab yuqoriga qarab mayin harakatlar bilan massaj qiling. Teginish paytida ajralib chiqadigan oksitotsin gormoni sizni ham, chaqaloqni ham tinchlantiradi. Bu odatni har oqshom cho‘miltirgandan keyin takrorlash uning tungi uyquga osonroq ketishiga yordam berishi mumkin.') WHERE id = '030269db-0cd6-4191-b990-5149723f7ac1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Butun e’tibor chaqaloqqa qaratilgani sababli turmush o‘rtog‘ingiz bilan munosabatlaringiz ikkinchi o‘ringa tushib qolgandek tuyulishi mumkin va bu mutlaqo tabiiy. Biroq "ota-ona" bo‘lish bilan birga "juftlik" ekaningizni ham unutmaslikka harakat qiling; chaqaloq uxlaganda birga choy ichish, quchoqlashish yoki shunchaki 10 daqiqa kuningiz qanday o‘tgani haqida suhbatlashish orangizdagi sovuqlikni eritishi mumkin. Otaga ham chaqaloq bilan mehr rishtalarini o‘rnatish imkonini yarating (masalan, chaqaloqning kekirishiga yordam berish yoki uni cho‘miltirish otaning vazifasi bo‘lishi mumkin). Bir jamoa ekaningizni his qilish ushbu qiyin kunlarda ikkalangizga ham kuch beradi.') WHERE id = '7b078d0d-8755-48b3-a240-4b2c014cdd7f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq hali emaklamasa ham, beixtiyor harakatlar bilan ag‘darilishga urinishi mumkin, bu esa xavfsizlik masalasini dolzarb qiladi. Oltin qoida: chaqaloqni hech qachon, hatto bir soniyaga ham baland joyda (divan, karavot, yo‘rgaklash stoli) yolg‘iz qoldirmang. "Hali qimirlamaydi" deb xotirjam bo‘lmang, chunki birinchi ag‘darilish odatda eng kutilmagan paytda yuz beradi. Uni faqat polga yozilgan gilam yoki maxsus o‘yin gilamchasi ustida yolg‘iz qoldirishingiz mumkin (albatta, nazorat ostida). Xavfsizlik odatlarini hozirdanoq shakllantirish kelajakdagi baxtsiz hodisalarning oldini oladi.') WHERE id = '0720bc24-8ac8-43a4-b347-e7e20231713d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mana, xalq orasida katta ahamiyat beriladigan kun ham keldi — "Bolaning chillasi chiqdi"! Tabriklaymiz! Qadimiy urf-odatlarga ko‘ra, bu kuni maxsus cho‘miltirish marosimi ("chilla suvi") o‘tkaziladi va ona-bola endi bemalol odamlar orasiga chiqishi mumkin. Tibbiy nuqtayi nazardan esa bu 6 haftalik tiklanish davri (loxiyaning tugashi, bachadonning qisqarishi) yakunlanganini anglatadi. Bu kunni bayramdek nishonlang, bezanib, o‘zingizga oro bering va ehtimol, chaqalog‘ingiz bilan ilk uzoq "rasmiy" sayrga chiqing. "Qirq" shunchaki raqam emas, bu sizning "yangi ona" maqomidan "tajribali ona" maqomiga o‘tishingiz ramzidir. Siz uddaladingiz!') WHERE id = '1ce90c4b-f9a4-402a-a99b-4457322248d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Chilladan chiqish" jamiyatimizda go‘yo marraga yetishdek qabul qilinadi, ammo aslida bu marafonning shunchaki boshlanishidir. "Endi hamma narsani uddalashim kerak", "Uyim top-toza bo‘lishi shart" kabi bosimlarga bo‘yin egmang. Tiklanish jarayoni hali ham davom etmoqda; ayniqsa, emizayotgan bo‘lsangiz, gormonlar (prolaktin) ta’sirida bo‘g‘imlaringiz bo‘shashishi yoki belingiz og‘rishini his qilishingiz mumkin. Ushbu "yangi erkinlik" davrida birdaniga o‘zingizga ortiqcha yuklama bermang, avvalgi sur’atingizga asta-sekin, qadamma-qadam qayting.') WHERE id = '0928cbd6-fa37-455a-a682-9515f253a752';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi ranglarni yaxshiroq ajrata boshlaydi; qizil va to‘q sariq uning diqqatini tortadigan dastlabki yorqin ranglar bo‘lishi mumkin. Beshigi ustiga osilgan aylanuvchi o‘yinchoqning (mobil) endi nafaqat musiqasi, balki harakati ham uni qiziqtiradi. Agar hali sotib olmagan bo‘lsangiz, oddiy geometrik shakllardan iborat va sekin harakatlanadigan mobil uning diqqatini jamlash qobiliyatini rivojlantiradi. Ammo e’tibor bering: chaqaloqni uxlatayotganda uyqusi qochmasligi uchun bu o‘yinchoqlarni olib qo‘ying.') WHERE id = 'c21766cd-a78b-4676-9247-d0b2e0b3de2f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tug‘ruqdan keyingi jinsiy hayot mavzusi ko‘pincha tabu hisoblanadi, ammo bu haqda ma’lumotga ega bo‘lishingiz kerak. Shifokor ruxsat berganidan keyin (odatda 6 haftadan so‘ng) jinsiy aloqa qilish mumkin, biroq istakning pasayishi (libidoning pastligi) yoki quruqlikni his qilishingiz mutlaqo normal. Bu emizish bilan bog‘liq gormonlar va charchoq ta’siridir. Juftingiz bilan bu haqda ochiq gaplashing, bir-biringizga vaqt bering va shoshilmang. Yaqinlik faqat jinsiy aloqa degani emas — shunchaki quchoqlashish va bir-biringizga teginish ham bu davrda juda muhim.') WHERE id = 'a59bf56c-999f-4547-b139-eaa70223118e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqalog‘ingiz o‘z qo‘llarini kashf etadigan davrga kirdi: u qo‘llarini og‘ziga olib borishi, barmoqlarini so‘rishi mumkin. Bu uning "qorni och" degani emas (garchi ochlik belgisi ham bo‘lishi mumkin), balki o‘zini tinchlantirish mexanizmi va dunyoni o‘rganish usulidir. Qo‘llarini og‘zidan chiqarishga yoki unga qo‘lqop kiydirishga urinmang. O‘z tanasini o‘rganishiga imkon bering. Faqat qo‘llari toza va tirnoqlari olinganiga ishonch hosil qiling.') WHERE id = '15366f98-572a-4b0c-8fda-af7cf85e56b4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi 2 oylik emlashlar vaqti keldi (agar hali qildirmagan bo‘lsangiz). Ozarbayjonda qo‘llaniladigan emlash taqvimiga ko‘ra, bu davrda chaqaloqqa odatda 5 yoki 6 komponentli kombinatsiyalangan vaksina (ko‘kyo‘tal, difteriya, qoqshol va boshqalarga qarshi) hamda pnevmokokk vaksinasi qilinadi. Emlashdan keyin chaqaloqning harorati biroz ko‘tarilishi yoki u bezovta bo‘lishi mumkin. Bu qo‘rqinchli emas, aksincha, immunitet "ishga tushgani" va organizm himoyalanayotganini ko‘rsatadi. Shifokor tavsiyasiga ko‘ra, uyda chaqaloqlar uchun mo‘ljallangan, tarkibida paratsetamol bo‘lgan shamcha yoki siropni albatta saqlang, ammo harorat 38 darajadan oshmaguncha dori berishga shoshilmang.') WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning og‘zidan so‘lak oqa boshladimi va u qo‘llarini tishlayaptimi? Buvilar darhol "tishi chiqyapti" deyishlari mumkin, ammo odatda 2 oy tish chiqishi uchun erta hisoblanadi (istisnolar bo‘lsa-da). Bu davrda so‘lak bezlari faol ishlay boshlaydi, lekin chaqaloq hali so‘lakni to‘liq yutishni o‘rganmagan bo‘ladi, shuning uchun u og‘zidan oqib chiqadi. Shu bilan birga, so‘lakdagi fermentlar uning hazm qilish tizimini kelajakda qattiq ovqatga tayyorlaydi. Bo‘yni nam qolib, toshma yoki bichilish paydo bo‘lmasligi uchun shunchaki ko‘krakchasini tez-tez almashtirib turing.') WHERE id = '99be53c6-0b63-4846-ac0b-fd476ca9e54e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Dush qabul qilayotganda qo‘lingizga tutam-tutam soch tushsa, qo‘rqmang — kal bo‘lib qolmaysiz! Bu "Tug‘ruqdan keyingi soch to‘kilishi" deb ataladi va butunlay gormonal jarayondir. Homiladorlik paytida ko‘paygan estrogen gormoni sochlaringizning to‘kilishiga yo‘l qo‘ymagan edi, endi esa bu gormonlar kamaymoqda va o‘z vaqtida to‘kilmagan sochlar birdaniga to‘kilyapti. Bu vaqtinchalik bo‘lib, taxminan 6-12 oy ichida tiklanadi. Qimmat shampunlarga pul sarflash o‘rniga, ovqatlanishingiz va temir darajangizga e’tibor bering — vaqt o‘tishi bilan hammasi iziga tushadi.') WHERE id = 'f657e712-ddb7-463c-a1f6-51d68e963ec9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi tun bilan kunduzni biroz farqlay boshlaydi, shuning uchun "uyqu marosimi"ni yaratish uchun ayni muddao. Bu qat’iy tartib emas, shunchaki izchil ketma-ketlikdir: Iliq vanna -> Pijama kiydirish -> Xira yorug‘lik -> Alla yoki oq shovqin -> Uyqu. Har kuni bir xil ketma-ketlikni takrorlash chaqaloqning miyasiga "endi uxlash vaqti keldi" degan signalni yuboradi. Bu odat bugun natija bermasa ham, bir necha haftadan keyin sizning najotkoringizga aylanadi.') WHERE id = '2614d60b-6450-43ee-a569-f20e3ea56045';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '6-8-haftalar (ya’ni hozirgi davr) chaqaloqlar eng ko‘p yig‘laydigan payt bo‘lishi mumkin. Ba’zan hech qanday sababsiz, qorni to‘q va tagligi toza bo‘lsa ham yig‘lashi mumkin. Bu uning asab tizimi atrofdagi tovushlar, yorug‘lik va boshqa ta’sirlardan haddan tashqari zo‘riqayotganidan darak beradi. O‘zingizni ayblamang, bu sizning "yomon ona" ekaningiz bilan bog‘liq emas, balki rivojlanishning tabiiy bir qismidir. Shunchaki yonida bo‘ling, bag‘ringizga bosing va "bu ham o‘tib ketadi" deng. Darhaqiqat, bir necha haftadan keyin bu yig‘lashlar keskin kamayadi.') WHERE id = 'c94543e8-f599-4ccd-918b-88ff573157bb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz allaqachon "agu" deyishni yoki tomoq tovushlarini chiqarishni boshladimi? Bu nutq rivojlanishining ilk bosqichidir! U tovush chiqarganda, siz ham xuddi shu tovush bilan javob bering, go‘yo "suhbatlashayotgandek" bo‘ling. Tadqiqotlar shuni ko‘rsatadiki, ota-onaning chaqaloq tovushlariga taqlid qilishi unga "men seni eshityapman va tushunyapman" degan xabarni beradi. Bu oddiy o‘yin uning o‘ziga bo‘lgan ishonchini oshiradi va kelajakda ertaroq gapirishi uchun zamin yaratadi.') WHERE id = '045f5830-2fde-4a82-b369-03b2e1dcea23';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Oynaga qaraganingizda, homiladorlikdan qolgan ortiqcha vazn yoki osilib qolgan qorinni ko‘rib, hali ham tushkunlikka tushishingiz mumkin. Unutmang, bu qorin 9 oy davomida kattalashdi, uning to‘liq tiklanishi uchun ham kamida shuncha vaqt kerak. Qat’iy parhezlar (ayniqsa, emizikli onalarda) sutning kamayishi va soch to‘kilishiga sabab bo‘lishi mumkin. Hozir ozish haqida emas, sog‘lom ovqatlanish haqida o‘ylang. Ko‘p suv, sabzavotlar va oqsil sizning eng yaxshi yordamchilaringizdir. Tanangizdan nafratlanmang, u sizga dunyodagi eng go‘zal sovg‘ani berdi.') WHERE id = '772a8327-4bbe-46b7-9c90-09e5deaa584b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Qorin bilan yotish vaqti"ni (tummy time) yanada qiziqarli qilish uchun "samolyot" o‘yinini sinab ko‘ring. Chalqancha yotib, tizzalaringizni buking va chaqaloqni boldirlaringiz ustiga qorni bilan yotqizib, sekin tebrating (albatta, qo‘llaringiz bilan ushlab turing). Bu unga atrofni boshqa rakursdan ko‘rish imkonini beradi, siz bilan ko‘z orqali aloqa qilishiga yordam beradi va vestibulyar apparatini (muvozanat hissini) rivojlantiradi. Chaqaloqlar polda yolg‘iz mashq qilishdan ko‘ra, onasining tanasi ustida mashq qilishni ko‘proq yoqtiradi.') WHERE id = 'f63c5890-33d1-4cec-a07d-853961a0ca97';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu hali to‘liq izga tushmagan bo‘lsa-da, kunduzgi uyqular (nap) qisqara boshlashi mumkin. Agar chaqalog‘ingiz kunduzi atigi 20-30 daqiqa uxlab, uyg‘onib ketsa, buni "uxladi, tamom" deb qabul qilmang. Ba’zan chaqaloqlar uyqu sikllari orasida (har 40-45 daqiqada) uyg‘onadi, ammo aslida hali uyquga to‘ymagan bo‘ladi. U uyg‘onishi bilan darhol chiroqni yoqib, o‘ynashni boshlamang; yoniga yoting, asta ovuting yoki emizib, uyqusini uzaytirishga harakat qiling.') WHERE id = '2c5835b8-b6ba-41d1-b215-505864265cfb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Yaqinlashayotgan 2 oylik emlashlar (vaksinatsiya) haqida shifokoringiz bilan gaplashish vaqti keldi. Ozarbayjonda Milliy emlash taqvimiga ko‘ra, bu davrda ko‘kyo‘tal, difteriya, qoqshol, gepatit B va boshqalarga qarshi (Hexaxim yoki shunga o‘xshash), shuningdek, Rotavirus va Pnevmokok vaksinalari ko‘zda tutilgan. Atrofdagilarning "vaksina zararli", "bola gapirmay qoladi" kabi ilmiy asosga ega bo‘lmagan qo‘rqinchli gaplariga ishonmang. Vaksina — chaqaloqni kelajakdagi o‘limga olib keluvchi kasalliklardan himoya qiladigan eng kuchli qalqondir. Savollaringizni "qo‘shni xoladan" emas, pediatringizdan so‘rang.') WHERE id = '28360eb0-4c71-4798-a428-29239685c45f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning ko‘rish olami yanada rang-barang bo‘lib bormoqda: endi u nafaqat qizil va to‘q sariq, balki yashil va sariq ranglarni ham ajrata boshlaydi. Uning rivojlanishini qo‘llab-quvvatlash uchun uni uyning turli xonalarida aylantiring, ko‘zguda o‘z aksini ko‘rsating (chaqaloqlar hali bu o‘zlari ekanini anglamasalar-da, ko‘zgudagi akslarini juda yaxshi ko‘radilar). «Qani, ko‘raylik-chi, bu yerda kim bor ekan?» deb u bilan gaplashing. Bunday ijtimoiy o‘yinlar uning miya neyronlari jadal rivojlanishiga yordam beradi.') WHERE id = '34645ca6-b752-434e-a340-59af7488ff61';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ba’zan onalar emizayotgan bo‘lsa ham, vazni kamaymaydi, aksincha, ortadi. Bu uyqusizlik va stress tufayli ko‘payadigan kortizol gormoni bilan bog‘liq bo‘lishi mumkin: organizm o‘zini «xavf ostida» his qilib, yog‘ zaxirasini to‘playdi. «Sut ko‘paysin» deb shirin choy, holva va xamirli taomlar iste’mol qilish kerakligi — afsona. Sutni ko‘paytiradigan asosiy omillar yetarlicha suv ichish va chaqaloqni tez-tez emizishdir. Shakarni kamaytirib, ko‘proq sabzavot iste’mol qilish quvvatingizni oshiradi hamda vazningiz asta-sekin me’yorlashishiga yordam beradi.') WHERE id = '70fa5f2d-ef18-4d50-b156-41acde57d635';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qorni bilan yotqizganingizda (tummy time) endi faqat boshini emas, ko‘kragini ham yerdan ko‘tarishga urinayaptimi? Bu haqiqiy «mini mashq»! Uning qo‘llari va orqa mushaklari mustahkamlanmoqda. Agar hali buni uddalay olmasa, unga yordam bering: kichkina sochiqni o‘rab, qo‘ltiqlari ostiga qo‘ying — bu unga tayanch bo‘ladi. Yetib olishga urinishi uchun qarshisiga sevimli o‘yinchog‘ini qo‘ying. Bu mashqlar kelajakda emaklash va o‘tirish uchun muhimdir.') WHERE id = '8cfe7b98-ab62-49f4-b9ea-ef363b224769';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu davrda chaqaloqlarda «oziqlanmasdan so‘rish» refleksi kuchli bo‘ladi, ya’ni u och emas, shunchaki tinchlanish uchun nimanidir so‘rishni xohlaydi. Agar u barmoqlarini so‘rsa va siz unga so‘rg‘ich bermoqchi bo‘lsangiz, «ortodontik» shakldagisini tanlashga harakat qiling. So‘rg‘ich yomon odat emas, u chaqaloqlarning to‘satdan o‘lim sindromi (SIDS) xavfini kamaytirishga yordam beruvchi vosita hisoblanadi. Biroq chaqaloq har safar yig‘laganda so‘rg‘ichdan uni «ovutish» uchun foydalanmang, avval nima bezovta qilayotganini tushunishga harakat qiling.') WHERE id = '4ec5ed37-79da-4c46-9571-b8e74147be8d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq boshining bir tomoni yassilanib qolganini sezyapsizmi? Bu «pozitsion plagiosefaliya» deb ataladi va chaqaloq doimo bir tomonga qarab yotishi natijasida yuzaga keladi. Bosh suyagi hali yumshoq bo‘lgani uchun buni osonlikcha tuzatish mumkin. Oddiy yechim: uni beshikka yotqizayotganda har kecha boshining yo‘nalishini o‘zgartiring (bir kuni o‘ngga, bir kuni chapga). U uyg‘oq paytida esa boshining orqa qismiga bosim tushmasligi uchun imkon qadar ko‘proq qorni bilan yotqizing.') WHERE id = '248e6415-444f-4d09-8609-b540277d00d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Bugun chaqalog‘ingiz 2 oylik bo‘ldi! Endi siz rasman «yangi tug‘ilgan» (newborn) davrini ortda qoldirdingiz, u endi «go‘dak» (infant) hisoblanadi. Ilk kunlardagi o‘sha mitti, yordamsiz jonzotni hozir sizga jilmayib, turli tovushlar chiqarayotgan bolakay bilan solishtiring. Hali qiyin kunlar bo‘ladi: tish chiqishi, uyqu regressiyasi va boshqalar oldinda. Ammo siz endi tajribali onasiz va har qanday qiyinchilikni yenga olasiz. O‘zingizni bag‘ringizga bosing — siz ajoyib ishni uddalayapsiz!') WHERE id = 'd3b345c6-e91a-402d-9918-ceed5b8d37b4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Yostiq yoki kiyimi tez-tez ho‘l bo‘lib qolyaptimi? 3-oyda so‘lak ajralishining ko‘payishi mutlaqo tabiiy. Bu albatta tishi chiqayotganini anglatmaydi (garchi milklarida qichishish bo‘lishi mumkin). Bu ovqat hazm qilish tizimi rivojlanayotganini va og‘iz bo‘shlig‘idagi bakteriyalarga qarshi tabiiy himoya shakllanayotganini ko‘rsatadi. Toshma paydo bo‘lmasligi uchun bo‘yniga shunchaki "so‘lak tutgich" (ko‘krakpech) taqib qo‘ying va og‘iz atrofini quruq tuting.') WHERE id = '65b4b1d4-9f03-4890-8a26-60e163757dc4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Suv berish kerakmi?" degan savol bu oylarda onalarni ko‘p o‘ylantiradi. Ayniqsa, buvilar "bechora chanqab qoldi" deyishlari mumkin. Biroq Jahon sog‘liqni saqlash tashkiloti (JSST) dastlabki 6 oy davomida chaqaloqqa ona suti yoki sutli aralashmadan boshqa HECH NARSA (hatto suv ham) bermaslikni tavsiya qiladi. Ona sutining 88%-i suvdan iborat bo‘lib, bu chaqaloqning suvga bo‘lgan ehtiyojini to‘liq qondiradi. Uning oshqozoni hali juda kichik, uni suv bilan to‘ldirish sut iste’molini kamaytirishi va rivojlanishiga xalaqit berishi mumkin.') WHERE id = 'daa57941-307c-46d4-ad44-8c2b7828cf2e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kundalik hayotingizga o‘zingiz uchun "tanaffus" tugmasini qo‘shing. Chaqaloq uxlaganda darhol uy tozalashga shoshilmang. Sizning ham "batareyangiz" quvvatlanishga muhtoj. 20 daqiqa mizg‘ib olish, kitob o‘qish yoki shunchaki shiftga tikilib yotish — sizning haqqingiz. Siz "mukammal uy bekasi" bo‘lishingiz shart emas, ammo "sog‘lom ona" bo‘lishingiz kerak. Chang kutishi mumkin, lekin ruhiy salomatligingiz kuta olmaydi.') WHERE id = '8ae3c3ee-3ed1-4cce-8f50-41530ca784cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Shu oydan boshlab "Ovqatlanish - Faollik - Uyqu" tartibini shakllantirishni boshlashingiz mumkin. Ya’ni: Chaqaloq uyg‘onadi -> Sut ichadi -> O‘ynaydi -> Uxlaydi. Ko‘pincha onalar chaqaloqni emizib uxlatishadi (bu noto‘g‘ri emas, ammo odatga aylanishi mumkin). Agar "ovqatlanish-o‘ynash-uxlash" ketma-ketligini qo‘llasangiz, chaqaloq ovqatlanishni uyqu bilan kamroq bog‘laydi va kelajakda uning mustaqil uxlab qolishi osonlashadi. Albatta, bu qat’iy qoida emas, shunchaki sinab ko‘rishga arziydigan usul.') WHERE id = '2c9372ab-3791-4b09-9ac2-4545b2a50eba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning qo‘llari endi "o‘z holicha" harakatlanmaydi — u ongli ravishda buyumlarga qo‘l uzatishga va ularni ushlashga urinadi. Avvallari barmog‘ingizni kaftiga qo‘yganingizda refleks tarzda siqib olgan bo‘lsa, endi o‘yinchoqni ko‘rib, unga qo‘l uzatadi. Bu rivojlanish juda quvonarli, ammo ehtiyot bo‘ling: quchog‘ingizda bo‘lganida sochingizni, marjoningizni yoki ko‘zoynagingizni tortishga urinadi. Shuningdek, issiq choy solingan piyolalarni undan uzoqroq tuting, chunki u to‘satdan harakat qilib, choyni o‘z ustiga to‘kib yuborishi mumkin. Endi xavfsiz masofani saqlash juda muhim.') WHERE id = '851b7601-c8f0-43b8-a2e5-3708104c42ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar tunda uyqusizlik hali ham davom etayotgan bo‘lsa, "Uyquda oziqlantirish" (Dream Feed) usulini sinab ko‘rishingiz mumkin. Bunda chaqaloqni to‘liq uyg‘otmasdan, uyqusiragan holida (masalan, siz uxlashdan oldin soat 23:00-da) emizib, yana joyiga yotqiziladi. Bu usul ba’zan chaqaloqning yarim tunda uyg‘onishining oldini oladi va sizga biroz uzoqroq, uzluksiz uxlash imkonini beradi. Agar bu usul yordam bermasa va chaqaloq uyg‘onib yig‘lasa, uni majburlamang; har bir bolaning bioritmi turlicha.') WHERE id = '1a681284-0141-4b15-bc3b-3b5a269a1b94';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '3-oyga xush kelibsiz! Siz chaqaloq rivojlanishida «To‘rtinchi trimestr» deb ataladigan dastlabki 3 oylik moslashuv davrining oxiriga yaqinlashyapsiz. Endi chaqalog‘ingiz shunchaki yeb-uxlaydigan mavjudot emas, balki atrofni anglaydigan, tovushlarga munosabat bildiradigan ijtimoiy shaxsga aylanmoqda. Shu oydan boshlab uning uyg‘oq yuradigan vaqti uzayadi, uyqusi esa (umid qilamizki!) biroz tartibga tushadi. Bu yangi bosqichda u siz bilan ko‘proq «suhbatlashishni» xohlaydi, shuning uchun u bilan ko‘p gaplashish va unga qo‘shiqlar kuylashga tayyor bo‘ling.') WHERE id = '8828f855-f7c6-48a8-aae1-636ec24ccff1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz qo‘llarini yuzi qarshisida tutib, ularga hayrat bilan qarayaptimi? Bu uning ilk «o‘yinchog‘i»ni kashf etayotganidir! Bu «qo‘l-ko‘z muvofiqligi» deb ataladi. U qo‘llari o‘ziga tegishli ekanini va ularni boshqara olishini anglay boshlaydi. Bu jarayonga xalaqit bermang, qo‘llarini yashirmang. Aksincha, bilaklariga rangli yoki ovoz chiqaradigan (qo‘ng‘iroqchali) bilaguzuklar taqib, bu kashfiyotni yanada qiziqarli qilishingiz mumkin. Bu uning miyasi rivoji uchun ajoyib mashqdir.') WHERE id = 'c44f54e6-bd35-4121-9f0f-f6748ef02647';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uyqu masalasi hali ham og‘riqli bo‘lsa-da, yaxshi xabar bor: chaqalog‘ingizning miyasi endi «Melatonin» (uyqu gormoni) ishlab chiqara boshlaydi va sirkadiyalik ritmi (biologik soati) shakllanadi. Endi uning kecha bilan kunduzni adashtirish ehtimoli kamayadi. Unga yordam berish uchun ertalab xonani quyosh nuri bilan to‘ldiring, kechqurun esa chiroqlarni ertaroq o‘chirib, tinch muhit yarating. Tabiiy yorug‘likning bunday tartibi uning miyasiga «hozir uyg‘oq bo‘lish vaqti» va «hozir uxlash vaqti» degan signallarni yuboradi.') WHERE id = 'f3bdc990-29cc-452b-b018-a1508cec7d80';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uning bo‘yin mushaklari ancha mustahkamlangan va qorni bilan yotganida boshini 45-90 daraja ko‘tarib, atrofga qaray oladi. Hatto ba’zan «samolyot» kabi qo‘l-oyoqlarini havoga ko‘tarib, tebranishi mumkin. Bu uning bel mushaklarini kelajakdagi emaklash va o‘tirish bosqichlariga tayyorlaydi. Agar u hali ham boshini to‘liq tutib tura olmasa, xavotir olmang, har bir bolaning rivojlanish sur’ati o‘ziga xos; shunchaki qorni bilan yotish vaqtini (tummy time) kundalik tartibdan qoldirmang.') WHERE id = '72ecbac3-10ef-45d2-898d-f50326e4aca5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning boshida, ayniqsa liqildoq sohasida sarg‘ish, yog‘li qobiqlar (qazg‘oq) paydo bo‘lganini ko‘rdingizmi? Bu xalq orasida «Gul», tibbiyotda esa «Seboreyali dermatit» deb ataladi. Qo‘rqmang, bu gigiyena talablariga rioya qilinmagani sababli paydo bo‘lmaydi va yuqumli emas. U onadan o‘tgan gormonlar ta’sirida yog‘ bezlarining ortiqcha ishlashi natijasida yuzaga keladi. Qobiqlarni yulishga urinmang, shunchaki cho‘miltirishdan oldin zaytun yoki bodom yog‘i surtib yumshating, so‘ng yumshoq cho‘tka bilan ohista tarab, yuvib tashlang. Vaqt o‘tishi bilan o‘z-o‘zidan yo‘qoladi.') WHERE id = 'ebf4f9a7-c423-4f9b-a35f-e6aea203cbf5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqalog‘ingizning kulgisi refleks emas, balki butunlay ongli! Siz unga jilmayganingizda, qitiqlaganingizda yoki «ku-ku» (bekinmachoq) o‘ynaganingizda u ovoz chiqarib kulishni boshlashi mumkin. Bu tovush dunyodagi eng go‘zal musiqa, shunday emasmi? Uning hazil tuyg‘usi shakllanmoqda. G‘alati tovushlar chiqarishingiz va yuzingizni turli holatlarga keltirishingiz unga juda yoqadi. Kulish uning o‘pkasini rivojlantiradi va stress gormonlarini kamaytiradi.') WHERE id = '1fddfb5f-0320-4827-b223-17100c2c0495';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni qorni bilan yotqizganingizda (tummy time), uning yon tomonga ag‘darilishga urinayotganini ko‘rishingiz mumkin. Ba’zi chaqqon chaqaloqlar bu davrda qorni bilan yotgan holatdan chalqanchasiga (boshining og‘irligi tufayli tasodifan) ag‘darilib olishlari mumkin. Bu juda quvonarli, ammo ayni paytda ogohlantiruvchi belgidir: Endi uni taglik almashtirish stolida, divanda yoki baland joyda bir soniyaga ham qarovsiz qoldirib bo‘lmaydi. Shu oydan boshlab yiqilish xavfi keskin ortadi, eng xavfsiz joy esa — pol (gilam yoki o‘yin gilamchasi)dir.') WHERE id = '51999bec-e90a-4151-af89-e280275c886e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqaloq chiqaradigan tovushlar faqat yig‘idan iborat emas: u unli tovushlarni ("a", "o", "u") cho‘zib aytishi yoki chinqirishi mumkin. Bu — uning ovoz paylari mashqi. Siz oshxonada ish qilayotganingizda u xonada ovoz chiqarsa, albatta unga ovoz bilan javob bering ("Ha, sizni eshityapman, hozir boraman"). Bunday "masofadan muloqot" unga xavfsizlik hissini beradi: "Onamni ko‘rmasam ham, ovozi eshitilyapti, demak, yolg‘iz emasman". Bu ajralish xavotirini (separation anxiety) kamaytirishga yordam beradi.') WHERE id = '4b396ede-815b-4edd-bee5-1ab95bd630c3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning vazni ortgani sari belingiz va qo‘llaringizda og‘riq (ayniqsa, "ona bilagi" sindromi) paydo bo‘lishi mumkin. Uni ko‘tarib olayotganda yoki emizayotganda tana holatingizga e’tibor bering: yelkangizni quloqlaringiz tomon ko‘tarmang, tik o‘tiring va belingizni ushlab turadigan yostiqlardan albatta foydalaning. Chaqaloqni yerdan ko‘tarayotganda belingizni emas, tizzalaringizni buking. Umurtqa pog‘onangiz sizga hali uzoq yillar kerak bo‘ladi, uni hozirdanoq asrang.') WHERE id = 'dc8afbc6-14c7-4301-94dd-c5e5a4b2292b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Atrofdagilardan "bolangiz 3 oylik bo‘ldi, endi ovqatning suvidan tatib ko‘rsating", "biroz non mag‘zidan bering, o‘rgansin" kabi gaplarni eshitishingiz mumkin. Qat’iy bo‘ling va "YO‘Q" deng. Jahon sog‘liqni saqlash tashkiloti (JSST) aniq tavsiya qiladi: Dastlabki 6 oy FAQAT ona suti (yoki sutli aralashma). Chaqaloqning oshqozon-ichak tizimi hali kraxmal yoki boshqa oziq-ovqatlarni hazm qilishga tayyor emas; qo‘shimcha ovqatni erta boshlash allergiya, qorin dam bo‘lishi va kelajakda semirishga olib kelishi mumkin. Shoshilmang, uning ovqat yeyishga butun umri davomida vaqti bo‘ladi.') WHERE id = '0739a3ba-203e-453e-b9ac-6bd4bfdbcdf4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu davrdagi eng qiziqarli o‘yinchoq — ko‘zgu! Chaqaloqning qarshisiga xavfsiz (sinmaydigan) ko‘zgu qo‘ying. U ko‘zgudagi "boshqa chaqaloqqa" jilmayadi, unga tegishga urinadi va hayratlanadi. Hozircha u ko‘zgudagi aks o‘zi ekanini tushunmaydi (bu taxminan 18-oyda yuz beradi), ammo yuz ifodalari va harakatlarni kuzatish uning ijtimoiy rivojlanishi uchun juda foydali. Bu o‘yin chaqaloqning qorni bilan yotish vaqtini uzaytirish uchun ham ajoyib usuldir.') WHERE id = 'd5f46289-84de-4aa8-8cc6-e208423016ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning atrofdagi olamga qiziqishi ortgani sari uni emizish qiyinlashishi mumkin. U har bir tovush va harakatga boshini burib qarashni xohlaydi va ko‘krakni qo‘yib yuboradi. Bu holatni "qiziquvchan chaqaloq sindromi" deb atashadi. Asabiylashmang, emizish uchun shunchaki tinchroq, qorong‘i va chalg‘ituvchi narsalar bo‘lmagan xonani tanlang. Bo‘yningizdagi yorqin marjon yoki diqqatni tortadigan buyumlarni yechib qo‘ying. Uning tunda yoki uyqusi kelgan paytda yaxshiroq emishini ko‘rasiz — bu normal holat.') WHERE id = '9cc144a8-c429-4c7c-b711-108cf929ab92';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq qo‘llarini kashf etayotganda ba’zan tirnoqlari bilan yuzini tirnab olishi mumkin. Agar tirnoqlarini olishdan qo‘rqsangiz, buni u uxlayotganida qiling yoki tirnoqlari biroz yumshashi uchun cho‘miltirgandan keyinga qoldiring. Endi qo‘lqopcha kiydirish tavsiya etilmaydi, chunki chaqaloq qo‘llari bilan narsalarga tegib, ularni og‘ziga solib, dunyoni o‘rganadi. Kichik tirnalgan joy tezda bitadi, ammo qo‘llari bilan his qilishiga to‘sqinlik qilish uning rivojlanishini sekinlashtirishi mumkin.') WHERE id = '4516cd0b-d8f9-4d0b-92cb-3f43fabc6642';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, "To‘rtinchi trimestr" deb ataladigan dastlabki 3 oylik moslashuv davri deyarli yakunlandi! Chaqalog‘ingiz endi "tashqi dunyo"ga to‘liq ko‘nikdi. U uyg‘oq paytida faqat yotoqda qoldirmang: uy bo‘ylab aylantiring, birga derazadan qarang, turli xonalarga olib kiring. Endi u kuzatuvchiga aylangan. Bu davrda u bilan vizual va ovozli muloqotni qancha ko‘p qilsangiz, miyasidagi neyron aloqalar shuncha mustahkam bo‘ladi. Siz uning birinchi va eng yaxshi ustozisiz.') WHERE id = 'ef4c7b42-edd4-4ffb-87e6-5505b04254f6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz kechalari uzoqroq (masalan, 4-5 soat uzluksiz) uxlay boshlaganini sezyapsizmi? Bu uning oshqozoni kattalashgani va tun bo‘yi to‘q qola olishini ko‘rsatadi. Ammo xursand bo‘lishga shoshilmang, bu "asal oyi" davri bo‘lishi mumkin. Ayrim chaqaloqlarda 3-4 oylik atrofida "uyqu regressiyasi" (sleep regression) boshlanadi. Agar uyqusi buzilsa, vahimaga tushmang: bu uning miya rivojlanishi yangi bosqichga o‘tayotganini ko‘rsatadi. Siz faqat o‘zingiz yaratgan uyqu marosimiga rioya qilishda davom eting, chunki barqarorlik uning eng katta ehtiyojidir.') WHERE id = '7478fbcd-b780-4677-b9cd-7d27602a29cc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqalog‘ingizning qo‘llari musht bo‘lib tugilmaydi, ko‘pincha ochiq turadi. Bu uning mushak tonusi (gipertonus) pasayib, me’yorga qaytayotganini ko‘rsatadi. U qo‘llarini birlashtira oladi, barmoqlari bilan o‘ynaydi. Unga turli teksturadagi (yumshoq, g‘adir-budur, shitirlaydigan) matolar yoki o‘yinchoqlar berib, teginish sezgisini rivojlantirishingiz mumkin. Miya rivojlanishi barmoq uchlaridan boshlanadi: u qancha ko‘p turli yuzalarga teginsa, miyasi shuncha ko‘p ma’lumotni qayta ishlaydi.') WHERE id = 'd9c1219d-f2eb-4189-a9f5-e0d58b033ef7';